                    const linkedId = tx.linkedBillId;
                    if (!linkedId) return true;
                    const setting = recurringNonMonthly.find(s => linkedId === `bill-settings-${s.id}`);
                    if (!setting) return true;
                    return isValidOccurrenceDate(setting, tx.date);
