        document.getElementById('loan-store-name').value = '';
        tempEditingLoanIconDataUrl = '';
        renderLoanIconPreview();

        tempEditingPromos = [];
        tempEditingPaymentPlans = [];
        resetExistingPlanEditor();
        renderEditingPaymentPlans();

        tempEditingCustomSchedule = [];
        resetCustomScheduleEditor();
        renderEditingCustomSchedule();
        document.getElementById('loan-custom-schedule-section').classList.add('hidden');

        const isCredit = (type === 'credit');
