        const linkId = `seasonal-charge-${expense.id}-${year}-${String(monthIndex + 1).padStart(2, '0')}`;
        const occDate = expense.hasCharge ? getSeasonalChargeOccurrenceDate(expense, year, monthIndex) : null;
