function renderBillSplitterMetrics(mBills, allBills) {
    const ownership = state.billTrackerOwnership || 'joint';
    const metricCycle = state.billMetricsCycle || 'month';
    const selectedCycleLabel = metricCycle === 'month' ? 'Month' : metricCycle === '1st' ? '1st Cycle' : '15th Cycle';
    const allocateBillToCycle = (bill, cycle) => {
        if (bill.cycleAllocation === 'both') return bill.budgetAmount / 2;
        const billCycle = bill.cycleAllocation === '15th' ? '15th' : '1st';
        return billCycle === cycle ? bill.budgetAmount : 0;
    };
    const scopedBills = allBills.filter(bill => (bill.ownership || 'joint') === ownership);
    const expense1st = scopedBills.reduce((sum, bill) => sum + allocateBillToCycle(bill, '1st'), 0);
    const expense15th = scopedBills.reduce((sum, bill) => sum + allocateBillToCycle(bill, '15th'), 0);
    const expenseMonth = expense1st + expense15th;
    // Signed net per cycle (increase minus reduce) via the same helper the transfer calculations
    // use — NOT Math.abs() of each row, which used to add every "Reduce" allocation's magnitude
    // instead of subtracting it, silently inflating both totals by 2x the reduced amount.
    const jason1st = getAllocationCycleTotal(mBills, 'cycle1st', 'jason');
    const jason15th = getAllocationCycleTotal(mBills, 'cycle15th', 'jason');
    const asia1st = getAllocationCycleTotal(mBills, 'cycle1st', 'asia');
    const asia15th = getAllocationCycleTotal(mBills, 'cycle15th', 'asia');
    const selectCycle = (first, second) => metricCycle === '1st' ? first : metricCycle === '15th' ? second : first + second;
    // Rounded to whole dollars for these summary cards — cents-level precision isn't useful at a
    // glance here, and it's what makes the "1st Cycle: $X / $Y" split format below read cleanly.
    const formatMoney = value => `${value < 0 ? '-' : ''}$${Math.round(Math.abs(value)).toLocaleString('en-US')}`;
    const setMetric = (valueId, value, subId, subText, tone = value >= 0 ? 'positive' : 'negative') => {
        const element = document.getElementById(valueId);
        element.textContent = formatMoney(value);
        element.className = `card-value ${tone}`;
        // innerHTML (not textContent) so subText's <br> — splitting content onto separate lines —
        // actually renders; subText is always our own formatMoney()/date-label output, never user
        // input, so this is safe.
        document.getElementById(subId).innerHTML = subText;
    };
    // Real calendar dates for the current month, used to label which date range each view actually
    // covers (e.g. "15th - 31st", not always "15th - 30th") — the ordinal suffix (1st/2nd/3rd/nth)
    // matches how the user phrased it.
    const ordinal = n => {
        const suffixes = ['th', 'st', 'nd', 'rd'];
        const v = n % 100;
        return `${n}${suffixes[(v - 20) % 10] || suffixes[v] || suffixes[0]}`;
    };
    const monthName = MONTH_NAMES[state.currentMonth];
    const daysInMonth = new Date(state.currentYear, MONTH_ORDER.indexOf(state.currentMonth) + 1, 0).getDate();
    const lastDayOrdinal = ordinal(daysInMonth);
    document.getElementById('bills-metrics-title').textContent = `${ownership === 'jason' ? 'Personal' : 'Joint'} Bill Splitter Metrics — ${selectedCycleLabel}`;
    document.querySelectorAll('[data-bills-metrics-cycle]').forEach(button => button.classList.toggle('active', button.dataset.billsMetricsCycle === metricCycle));

    // Expenses card: the big number is always the total for whatever's selected (unchanged). Month
    // view breaks it down by cycle AND shows each cycle's 50/50 per-person split (joint expenses
    // only — a "personal" scoped card isn't a shared pot, so no split line there); a specific-cycle
    // view drops the numeric breakdown entirely and just labels which date range you're looking at.
    document.getElementById('bills-expenses-title').textContent = `${ownership === 'jason' ? 'Personal' : 'Joint'} Expenses`;
    // "$total / $splitPerPerson" — e.g. "1st Cycle: $2,942 / $1,471".
    const expensesSub = metricCycle === 'month'
        ? (ownership === 'joint'
            ? `1st Cycle: ${formatMoney(expense1st)} / ${formatMoney(expense1st / 2)}<br>2nd Cycle: ${formatMoney(expense15th)} / ${formatMoney(expense15th / 2)}`
            : `1st Cycle: ${formatMoney(expense1st)}<br>2nd Cycle: ${formatMoney(expense15th)}`)
        : (metricCycle === '1st' ? `Expenses: 1st - 14th` : `Expenses: 15th - ${lastDayOrdinal}`);
    setMetric('bills-expenses-total', selectCycle(expense1st, expense15th), 'bills-expenses-sub', expensesSub, 'negative');

    // Personal Allocations cards: same pattern, minus the per-person split (each of these is already
    // one specific person's own total, not a shared pot to divide further).
    const allocationSub = (person, first, second) => metricCycle === 'month'
        ? `1st Cycle: ${formatMoney(first)}<br>2nd Cycle: ${formatMoney(second)}`
        : (metricCycle === '1st' ? `${person}'s Allocations: 1st - 14th` : `${person}'s Allocations: 15th - ${lastDayOrdinal}`);
    setMetric('bills-jason-allocations', selectCycle(jason1st, jason15th), 'bills-jason-allocations-sub', allocationSub('Jason', jason1st, jason15th), 'positive');
    setMetric('bills-asia-allocations', selectCycle(asia1st, asia15th), 'bills-asia-allocations-sub', allocationSub('Asia', asia1st, asia15th), 'positive');

    // Mirror the Dashboard's own "Remaining Balance" card exactly — same function, same cycle
    // boundary (the 14th, not the 15th), same two figures — rather than an independently computed
    // balance here that can silently drift out of sync with what the Dashboard actually shows.
    const { bal14th, balLast } = ownership === 'jason'
        ? getPersonalCalendarBalancesForMonth(state.currentYear, state.currentMonth)
        : getJointCalendarBalancesForMonth(state.currentYear, state.currentMonth);
    const selectedBalance = metricCycle === '1st' ? bal14th : balLast;
    // Always a single "as of" date label, never a 1st/2nd breakdown — Month and 2nd Cycle both mean
    // "as of the end of the month," 1st Cycle means "as of the 14th."
    const balanceAsOfLabel = metricCycle === '1st' ? `Ending balance as of ${monthName} 14th` : `Ending balance as of ${monthName} ${lastDayOrdinal}`;
    document.getElementById('bills-balance-title').textContent = `${ownership === 'jason' ? 'Personal' : 'Joint'} Remaining Balance`;
    setMetric('bills-balance-total', selectedBalance, 'bills-balance-sub', balanceAsOfLabel);

    // Running totals in each section's OWN header (not just these dashboard cards), scoped to
    // whatever Month/1st/15th cycle is currently selected — reuses the exact figures already
    // computed above, which already correctly half-split any 'both'-cycle bill/allocation.
    const totalForView = selectCycle(expense1st, expense15th);
    const jointTotalLine = document.getElementById('joint-expenses-total-line');
    if (jointTotalLine) {
        jointTotalLine.textContent = ownership === 'joint'
            ? `${selectedCycleLabel} total: ${formatMoney(totalForView)} · Split: ${formatMoney(totalForView / 2)} / person`
            : `${selectedCycleLabel} total: ${formatMoney(totalForView)}`;
    }
    const allocTotalLine = document.getElementById('personal-allocations-total-line');
    if (allocTotalLine) {
        const jasonTotal = selectCycle(jason1st, jason15th);
        const asiaTotal = selectCycle(asia1st, asia15th);
        // Unlike Joint Expenses (a single shared pot split 50/50), each personal allocation is
        // already individually tagged to Jason or Asia — so the useful per-person figure here is
        // each one's own real total, not an even split of the combined sum.
        allocTotalLine.textContent = `${selectedCycleLabel} total: ${formatMoney(jasonTotal + asiaTotal)} · Jason: ${formatMoney(jasonTotal)} / Asia: ${formatMoney(asiaTotal)}`;
    }
}
// Generic per-column searchable multi-select filter, shared by the Joint/Personal Bills, Personal
// Allocations, and Seasonal Expenses tables. Operates purely on the rendered DOM: each column's
// distinct values are read straight off the current tbody rows (using each cell's bolded primary
// text where present), and matching is done by hiding/showing <tr> elements after render — no
// changes needed to the tables' existing data-building/sorting logic. Filter selections are kept
// in-memory as Sets (keyed by "tableKey:columnIndex", each value a Set of the checked options,
// empty Set = no filter applied for that column) since Sets are what .has()/.add()/.delete() need
// — but a Set isn't JSON-serializable, so it can't live in `state` directly. serializeColumnFilterState/
// rehydrateColumnFilterState convert to/from a plain array-valued object at the save/load boundary
// so this can be persisted locally and pushed to the Settings sheet tab like any other view setting.
const columnFilterState = {};

function getColumnFilterSet(filterKey) {
    if (!columnFilterState[filterKey]) columnFilterState[filterKey] = new Set();
    return columnFilterState[filterKey];
}

function serializeColumnFilterState() {
    const out = {};
    Object.keys(columnFilterState).forEach(k => {
        if (columnFilterState[k] && columnFilterState[k].size > 0) out[k] = Array.from(columnFilterState[k]);
    });
    return out;
}

function rehydrateColumnFilterState(serialized) {
    Object.keys(columnFilterState).forEach(k => delete columnFilterState[k]);
    Object.entries(serialized || {}).forEach(([k, values]) => {
        columnFilterState[k] = new Set(Array.isArray(values) ? values : []);
    });
}

function getColumnCellValue(tr, colIndex) {
    const td = tr.children[colIndex];
    if (!td) return '';
    const strong = td.querySelector('strong');
    return (strong ? strong.textContent : td.textContent).replace(/\s+/g, ' ').trim();
}

// Clears every active column filter for one or more tableKeys (columnFilterState is keyed
// "tableKey:colIndex") and, if given, resets that table's sort state back to a default — then
// re-renders. One generic function instead of hand-rolling the same clear+rerender per table.
function resetTableFiltersAndSort(tableKeys, resetSort, rerenderFn) {
    (Array.isArray(tableKeys) ? tableKeys : [tableKeys]).forEach(tableKey => {
        Object.keys(columnFilterState).forEach(k => {
            if (k.startsWith(tableKey + ':')) delete columnFilterState[k];
        });
    });
    if (resetSort) resetSort();
    saveDatabase();
    rerenderFn();
}

function closeAllColumnFilterPopovers() {
    document.querySelectorAll('.col-filter-popover').forEach(p => p.remove());
}

// Hides/shows <tr> elements in `tbody` based on every active filter recorded for `tableKey`. A
// column only filters when at least one of its checkboxes is selected.
function applyColumnFilters(tbody, tableKey) {
    if (!tbody) return;
    const activeCols = Object.keys(columnFilterState)
        .filter(k => k.startsWith(tableKey + ':') && columnFilterState[k] && columnFilterState[k].size > 0)
        .map(k => ({ col: Number(k.split(':')[1]), values: columnFilterState[k] }));
    
    const rows = [...tbody.querySelectorAll(':scope > tr')];
    if (rows.length === 0) return;

    if (activeCols.length > 0) {
        let visibleCount = 0;
        rows.forEach(tr => {
            const visible = activeCols.every(f => f.values.has(getColumnCellValue(tr, f.col)));
            if (visible) visibleCount++;
        });

        // Safety check: if an active filter matches 0 rows (stale filter), reset it so rows are never hidden blindly
        if (visibleCount === 0) {
            Object.keys(columnFilterState).forEach(k => {
                if (k.startsWith(tableKey + ':')) delete columnFilterState[k];
            });
            if (state.columnFilterState) {
                Object.keys(state.columnFilterState).forEach(k => {
                    if (k.startsWith(tableKey + ':')) delete state.columnFilterState[k];
                });
            }
            rows.forEach(tr => tr.style.display = '');
            return;
        }
    }

    rows.forEach(tr => {
        const visible = activeCols.every(f => f.values.has(getColumnCellValue(tr, f.col)));
        tr.style.display = visible ? '' : 'none';
    });

    updateDashboardFilteredMetrics();
}

function getFormattedTransferTitle(tx, isJointLedgerView = false) {
    if (!tx) return '';
    const rawDesc = tx.description || tx.name || '';
    const desc = rawDesc.toLowerCase();
    
    const isSavings = tx.savingsTransfer || desc.includes('savings') || (tx.transferId && String(tx.transferId).includes('savings')) || (tx.id && String(tx.id).includes('savings'));
    const isJoint = tx.type === 'contribution' || desc.includes('joint') || desc.includes('xfer to joint') || (tx.transferId && String(tx.transferId).includes('checking-xfer')) || (tx.id && String(tx.id).includes('joint-xfer')) || (tx.id && String(tx.id).includes('xfer-')) || (tx.id && String(tx.id).includes('p-joint'));

    if (isSavings) {
        const amt = Number(tx.amount || 0);
        let isDeposit = false;
        if (tx.isSavingsRegister) {
            isDeposit = amt >= 0;
        } else {
            isDeposit = amt < 0; // Money leaving personal into savings is a Savings Deposit
        }
        return isDeposit ? 'Savings Deposit' : 'Savings Withdrawal';
    }

    if (isJoint) {
        let person = 'Jason';
        if (tx.contributionRecipient === 'asia' || (tx.asia && Number(tx.asia) > 0) || desc.includes('asia') || (tx.id && String(tx.id).includes('asia')) || tx.owner === 'asia') {
            person = 'Asia';
        } else if ((tx.jason && Number(tx.jason) > 0) || desc.includes('jason') || (tx.id && String(tx.id).includes('jason')) || tx.owner === 'jason') {
            person = 'Jason';
        }

        const amt = Number(tx.amount || 0);
        let isDeposit = false;
        // tx.isJointRegister is never actually set anywhere in the codebase (it's read here and
        // nowhere else — confirmed via grep) — it's dead as a signal, so this always fell through
        // to isJointLedgerView, which the two Joint Ledger call sites (renderJointList's search
        // filter and buildJointRowHtml) never passed either. Every row in the Joint Ledger was
        // therefore using the PERSONAL-side sign convention (amt < 0 = Deposit) instead of the
        // joint one (amt >= 0 = Deposit) — a real deposit showed as "Joint Withdrawal" and vice
        // versa, for both auto-calculated and manually-entered rows alike. Confirmed live,
        // 2026-08-01: user reported real deposit rows (e.g. "Xfer to Joint", amount +$2,700)
        // mislabeled "Joint Withdrawal". getTransactionIndicatorBadges' own copy of this same logic
        // (~app.js:13185) already falls back to `state.dashboardType === 'joint'` for exactly this
        // reason — mirrored here so this function's title and that function's badge chip can no
        // longer disagree about the same transaction.
        if (tx.isJointRegister || isJointLedgerView || state.dashboardType === 'joint') {
            isDeposit = amt >= 0; // Money entering joint is positive (Joint Deposit)
        } else {
            isDeposit = amt < 0; // Money leaving personal to deposit into joint (Joint Deposit)
        }

        return isDeposit ? `Joint Deposit - (${person})` : `Joint Withdrawal - (${person})`;
    }

    return rawDesc;
}

function updateDashboardFilteredMetrics() {
    const isList = state.viewMode === 'list';
    let count = 0;
    let totalAmt = 0;
    let isFiltered = false;

    if (isList) {
        const tbody = document.querySelector('#list-view-table-container tbody, #cc-list-table-container tbody');
        if (tbody) {
            const rows = Array.from(tbody.querySelectorAll(':scope > tr'));
            const masterSearch = (document.getElementById('list-view-master-search')?.value || '').trim();
            const hasColFilters = Object.keys(columnFilterState || {}).some(k => columnFilterState[k] && columnFilterState[k].size > 0);
            isFiltered = masterSearch.length > 0 || hasColFilters;

            rows.forEach(tr => {
                if (tr.style.display !== 'none') {
                    count++;
                    const amtVal = parseFloat(tr.dataset.amount || tr.getAttribute('data-amount') || '0');
                    if (!isNaN(amtVal)) {
                        totalAmt += amtVal;
                    }
                }
            });
        }
    } else {
        const isJoint = state.dashboardType === 'joint';
        const year = state.currentYear;
        const month = state.currentMonth;

        if (isJoint) {
            const mStr = typeof month === 'number' ? (month + 1).toString().padStart(2, '0') : month;
            const txs = (state.jointRegister || []).filter(tx => tx.date && String(tx.date).startsWith(`${year}-${mStr}`) && !tx.billOccurrenceDeleted);
            count = txs.length;
            totalAmt = txs.reduce((sum, t) => sum + (Number(t.amount) || 0), 0);
        } else {
            const mStr = typeof month === 'number' ? (month + 1).toString().padStart(2, '0') : month;
            const key = `${year}-${mStr}`;
            const list = (state.personalCalendar && state.personalCalendar[key]) || [];
            count = list.length;
            totalAmt = list.reduce((sum, t) => sum + (Number(t.amount) || 0), 0);
        }
    }

    const formattedAmt = (totalAmt >= 0 ? '+' : '-') + '$' + Math.abs(totalAmt).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    ['filtered-items-count', 'list-filtered-items-count'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = count;
    });

    ['filtered-items-amount', 'list-filtered-items-amount'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = formattedAmt;
    });

    ['filtered-items-label', 'list-filtered-items-label'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = isFiltered ? 'Filtered' : 'View Items';
    });

    if (isList && state.dashboardType === 'joint') {
        const summaryHost = document.getElementById('list-view-summary-host');
        if (summaryHost) {
            const tbody = document.querySelector('#list-view-table-container .joint-list-table tbody');
            if (tbody) {
                let jasonTotal = 0;
                let asiaTotal = 0;
                const rows = Array.from(tbody.querySelectorAll(':scope > tr'));
                rows.forEach(tr => {
                    if (tr.style.display !== 'none') {
                        const jasonCell = tr.children[2];
                        const asiaCell = tr.children[3];
                        if (jasonCell && jasonCell.textContent !== '—' && !jasonCell.textContent.includes('-')) {
                            const raw = jasonCell.textContent.replace(/[^0-9.]+/g, '');
                            const val = parseFloat(raw) || 0;
                            jasonTotal += val;
                        }
                        if (asiaCell && asiaCell.textContent !== '—' && !asiaCell.textContent.includes('-')) {
                            const raw = asiaCell.textContent.replace(/[^0-9.]+/g, '');
                            const val = parseFloat(raw) || 0;
                            asiaTotal += val;
                        }
                    }
                });
                const contributionTotal = jasonTotal + asiaTotal;
                const money = amount => `${amount < 0 ? '-' : '+'}$${Math.abs(amount).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
                const color = amount => amount < 0 ? 'negative' : 'positive';
                summaryHost.innerHTML = `<div style="display:flex;gap:1.5rem;flex-wrap:wrap;padding:0.6rem 1rem;margin:0.5rem 0;background:rgba(255,255,255,0.03);border:1px solid var(--glass-border);border-radius:8px;font-size:0.85rem;"><span>Jason Contributions: <strong class="${color(jasonTotal)}">${money(jasonTotal)}</strong></span><span>Asia Contributions: <strong class="${color(asiaTotal)}">${money(asiaTotal)}</strong></span><span>Total Contributions: <strong class="${color(contributionTotal)}">${money(contributionTotal)}</strong></span></div>`;
            }
        }
    }
}

// Wires a filter button into a <th> (idempotent — safe to call on every render since <thead> markup
// is static and never rebuilt). `tbody` is passed as a function so it's re-resolved fresh each time
// the popover is opened, in case the element was replaced.
function setupColumnFilterButton(th, tableKey, colIndex, getTbody) {
    if (th.querySelector('.col-filter-btn')) return;
    if (!th.querySelector('.col-th-inner')) {
        const wrapper = document.createElement('span');
        wrapper.className = 'col-th-inner';
        while (th.firstChild) wrapper.appendChild(th.firstChild);
        th.appendChild(wrapper);
    }
    const filterKey = `${tableKey}:${colIndex}`;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'col-filter-btn';
    btn.title = 'Filter this column';
    btn.textContent = '🔍';
    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const wasOpen = !!th.querySelector('.col-filter-popover');
        closeAllColumnFilterPopovers();
        if (wasOpen) return;

        const tbody = getTbody();
        if (!tbody) return;
        const values = Array.from(new Set(
            [...tbody.querySelectorAll(':scope > tr')].map(tr => getColumnCellValue(tr, colIndex)).filter(Boolean)
        )).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

        const popover = document.createElement('div');
        popover.className = 'col-filter-popover';
        popover.addEventListener('click', (ev) => ev.stopPropagation());
        const search = document.createElement('input');
        search.type = 'text';
        search.placeholder = 'Search…';
        search.className = 'col-filter-search';
        const list = document.createElement('div');
        list.className = 'col-filter-list';
        popover.appendChild(search);
        popover.appendChild(list);
        th.appendChild(popover);

        const selected = getColumnFilterSet(filterKey);
        const makeOption = (label, checked, onToggle, extraClass = '') => {
            const row = document.createElement('label');
            row.className = 'col-filter-option' + (extraClass ? ' ' + extraClass : '');
            const cb = document.createElement('input');
            cb.type = 'checkbox';
            cb.checked = checked;
            cb.addEventListener('change', () => onToggle(cb.checked));
            row.appendChild(cb);
            row.appendChild(document.createTextNode(label));
            return row;
        };
        const renderList = (searchText) => {
            list.innerHTML = '';
            const matches = values.filter(v => v.toLowerCase().includes(searchText.toLowerCase()));
            const allChecked = matches.length > 0 && matches.every(v => selected.has(v));
            list.appendChild(makeOption('All', allChecked, (checked) => {
                matches.forEach(v => checked ? selected.add(v) : selected.delete(v));
                applyColumnFilters(getTbody(), tableKey);
                btn.classList.toggle('active', selected.size > 0);
                renderList(search.value);
                saveDatabase();
            }, 'col-filter-all'));
            if (!matches.length) {
                const empty = document.createElement('div');
                empty.className = 'col-filter-empty';
                empty.textContent = 'No matches';
                list.appendChild(empty);
            }
            matches.forEach(v => {
                list.appendChild(makeOption(v, selected.has(v), (checked) => {
                    checked ? selected.add(v) : selected.delete(v);
                    applyColumnFilters(getTbody(), tableKey);
                    btn.classList.toggle('active', selected.size > 0);
                    renderList(search.value);
                    saveDatabase();
                }));
            });
        };
        renderList('');
        search.addEventListener('input', () => renderList(search.value));
        search.focus();
    });
    if (getColumnFilterSet(filterKey).size > 0) btn.classList.add('active');
    th.appendChild(btn);
}

// Attaches filter buttons to every <th> in `theadSelector` except those listed in `skipCols`.
// Shows a ▲/▼ next to whichever column a table is currently sorted by. Generic across every
// data-*-sort header (data-bill-sort, data-allocation-sort, data-seasonal-sort,
// data-bill-tracker-sort, ...) — pass the attribute name and the {key, direction} it's sorted by.
// Writes into the .col-sort-indicator span rather than the header's own text so it survives
// setupColumnFilterButton wrapping the original label into .col-th-inner, and any later dynamic
// relabeling of that text (e.g. Bill Splitter's Day/Charge Day header) doesn't have to know about it.
function updateSortIndicators(theadSelector, sortAttr, sortState) {
    document.querySelectorAll(`${theadSelector} [${sortAttr}]`).forEach(th => {
        const key = th.getAttribute(sortAttr);
        const host = th.querySelector('.col-th-inner') || th;
        let indicator = host.querySelector('.col-sort-indicator');
        if (!indicator) {
            indicator = document.createElement('span');
            indicator.className = 'col-sort-indicator';
            host.appendChild(indicator);
        }
        indicator.textContent = sortState.key === key ? (sortState.direction === 'asc' ? ' ▲' : ' ▼') : '';
    });
}

function setupTableColumnFilters(theadSelector, tableKey, getTbody, skipCols = []) {
    const headerRow = document.querySelector(`${theadSelector} tr`);
    if (!headerRow) return;
    [...headerRow.children].forEach((th, colIndex) => {
        if (skipCols.includes(colIndex)) return;
        setupColumnFilterButton(th, tableKey, colIndex, getTbody);
    });
}

document.addEventListener('click', (e) => {
    if (!e.target.closest('.col-filter-popover') && !e.target.closest('.col-filter-btn')) {
        closeAllColumnFilterPopovers();
    }
});

// Lets every native date input in the app accept a 2-digit year for speed (e.g. typing "26"
// instead of "2026") without giving up the native calendar picker. The browser's own date input
// can't be told to interpret a partial year as-you-type, but whatever it ends up storing once the
// field commits (on 'change') is still just a plain ISO string we can inspect and correct: a year
// under 100 only ever happens here because someone typed a short year, never a real one, so it's
// safe to always assume the 2000s and rewrite it before anything else reads the field's value.
document.addEventListener('change', (e) => {
    if (!(e.target instanceof HTMLInputElement) || e.target.type !== 'date' || !e.target.value) return;
    const [y, m, d] = e.target.value.split('-');
    if (y && Number(y) < 100) {
        e.target.value = `${2000 + Number(y)}-${m}-${d}`;
        e.target.dispatchEvent(new Event('change', { bubbles: true }));
    }
}, true);

// Describes a non-monthly subscription bill by the weekday it recurs on (e.g. "Weekly on
// Wednesdays", "Every 2 weeks on Fridays") instead of the raw anchor date, since the weekday is what
// actually repeats — the date itself was just the first occurrence. Quarterly/annual charges fall
// back to the anchor date since "day of week" isn't a meaningful way to describe something that
// happens once every several months.
const WEEKDAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
function getSubscriptionDayLabel(bill, frequencyLabels) {
    const label = frequencyLabels[bill.chargeFrequency] || bill.chargeFrequency;
    if (bill.chargeFrequency === 'quarterly' || bill.chargeFrequency === 'annual') {
        return `${label} from ${bill.frequencyStartDate}`;
    }
    if (bill.frequencyStartDate) {
        const weekdayName = new Date(bill.frequencyStartDate + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'long' });
        return `${label} on ${weekdayName}s`;
    }
    // Legacy weekly bills store the recurring weekday directly (weeklyDay: 0-6) instead of an anchor date.
    if (Number.isInteger(bill.weeklyDay)) {
        return `${label} on ${WEEKDAY_NAMES[bill.weeklyDay]}s`;
    }
    return label;
}
function renderBillsTab() {
    // Re-applies collapsed/expanded state to the Hide/Show buttons every render, not just when one
    // of them is clicked directly — otherwise a change made elsewhere (the master Hide/Show-All
    // header button) silently updated the underlying flags but never touched these panels.
    syncCollapseToggleButtons();
    const key = `${state.currentYear}-${state.currentMonth}`;
    ensureYearMonthInitialized(state.currentYear, state.currentMonth);
    autopopulateBillsForMonth(state.currentYear, state.currentMonth);
    applyAllocationTemplatesForMonth(state.currentYear, state.currentMonth);
    applySeasonalExpensesForMonth(state.currentYear, state.currentMonth);
    applySeasonalChargeForMonth(state.currentYear, state.currentMonth);
    const mBills = state.monthlyBills[key];
    if (!mBills) return;

    const currentCycle = state.billMetricsCycle || 'month';

    const allBills = ['cycle1st', 'cycle15th'].flatMap(cycleKey => (mBills[cycleKey].bills || []).map(bill => normalizeBillSplitterItem(bill, cycleKey)));
    renderBillSplitterMetrics(mBills, allBills);
    const calcBillsSplit = (cycleData, cycleKey) => {
        let jointBudget = 0;
        allBills.forEach(bill => {
            const assignedCycle = bill.cycleAllocation === '15th' ? 'cycle15th' : 'cycle1st';
            const allocatedAmount = bill.cycleAllocation === 'both' ? bill.budgetAmount / 2 : (assignedCycle === cycleKey ? bill.budgetAmount : 0);
            if (bill.ownership === 'joint') jointBudget += allocatedAmount;
        });
        // Preserve sign: negative "offset" allocations are meant to net against other allocations,
        // not add to them. 'both'-cycle allocations split half/half via getAllocationCycleTotal.
        const jasonAllocations = getAllocationCycleTotal(mBills, cycleKey, 'jason');
        const asiaAllocations = getAllocationCycleTotal(mBills, cycleKey, 'asia');
        const jointShare = Math.round(jointBudget * 50 + 1e-8) / 100;
        return {
            jasonTotal: Math.round((jasonAllocations + jointShare) * 100 + 1e-8) / 100,
            asiaTotal: Math.round((asiaAllocations + jointShare) * 100 + 1e-8) / 100,
            jointShare, jasonAllocations, asiaAllocations
        };
    };

    const split1st = calcBillsSplit(mBills.cycle1st, 'cycle1st');
    const split15th = calcBillsSplit(mBills.cycle15th, 'cycle15th');
    const monthPrefix = `${state.currentYear}-${String(MONTH_ORDER.indexOf(state.currentMonth) + 1).padStart(2, '0')}-`;
    const monthlyManualTransfers = (state.manualTransfers || []).filter(transfer => transfer.date.startsWith(monthPrefix)).sort((a, b) => a.date.localeCompare(b.date));
    const manualByCycle = { jason1st: 0, jason15th: 0, asia1st: 0, asia15th: 0 };
    monthlyManualTransfers.forEach(transfer => {
        const cycle = Number(transfer.date.slice(8, 10)) < 15 ? '1st' : '15th';
        const person = transfer.person === 'asia' ? 'asia' : 'jason';
        manualByCycle[`${person}${cycle}`] += Number(transfer.amount) || 0;
    });
    // Headline transfer amounts are ALWAYS the pure calculated budget (Expenses/jointShare +
    // Allocations) plus Extra Transfers — this card must never be affected by dynamicOverrides,
    // skippedTransfers, or anything else that changes what actually posts to the ledger. Per
    // explicit design decision: "making changes in the ledger should not affect the amount to
    // transfer over." The actual posted transfer can be edited/reduced/moved independently (see
    // the dynamic transaction override editor); that's a real-world "what actually happened"
    // concern, while this card answers "what SHOULD the transfer be" and stays fixed regardless.
    // A separate, purely informational "overridden" flag (dynamicOverrideFlag below) indicates
    // when the real posted amount for a cycle differs from this figure, without changing it.
    const jason1st = split1st.jasonTotal + manualByCycle.jason1st;
    const jason15th = split15th.jasonTotal + manualByCycle.jason15th;
    const asia1st = split1st.asiaTotal + manualByCycle.asia1st;
    const asia15th = split15th.asiaTotal + manualByCycle.asia15th;
    // Small yellow warning-triangle flag next to any transfer amount that includes a manually-entered
    // Extra Transfer, so it's visible at a glance where an extra transfer is coming out of — both on
    // the monthly total and on whichever cycle box it actually falls in.
    const extraFlag = amt => amt !== 0 ? '<span class="extra-transfer-flag" title="Includes an Extra Transfer">&#9888;</span>' : '';
    // Read-only "this cycle's real posted transfer was overridden" indicator — never feeds into
    // jason1st/jason15th/asia1st/asia15th above, purely a visual pointer to the dynamic tx editor.
    const overrides = state.dynamicOverrides || {};
    const dynamicOverrideFlag = (...ids) => {
        const dynId = ids.find(id => {
            const o = overrides[id];
            return o && (o.amount !== undefined || o.deleted === true || (Array.isArray(o.splitPieces) && o.splitPieces.length > 0));
        });
        if (!dynId) return '';
        const syntheticTx = { id: dynId };
        return `<span class="dynamic-override-flag" data-dyn-id="${dynId}" title="${escapeHTML(getJointTransferOverrideTooltip(syntheticTx))}">&#9873;${escapeHTML(getJointTransferSplitCycleLabel(syntheticTx))}</span>`;
    };
    const monthKeySuffix = `${state.currentYear}-${state.currentMonth}`;
    const jasonOverrideFlag1st = dynamicOverrideFlag(`joint-xfer-jason-1st-${monthKeySuffix}`, `xfer-1st-${monthKeySuffix}`);
    const jasonOverrideFlag15th = dynamicOverrideFlag(`joint-xfer-jason-15th-${monthKeySuffix}`, `xfer-15th-${monthKeySuffix}`);
    const asiaOverrideFlag1st = dynamicOverrideFlag(`joint-xfer-asia-1st-${monthKeySuffix}`);
    const asiaOverrideFlag15th = dynamicOverrideFlag(`joint-xfer-asia-15th-${monthKeySuffix}`);
    document.getElementById('jason-transfer-1st').innerHTML = `$${jason1st.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}${extraFlag(manualByCycle.jason1st)}${jasonOverrideFlag1st}`;
    document.getElementById('jason-transfer-15th').innerHTML = `$${jason15th.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}${extraFlag(manualByCycle.jason15th)}${jasonOverrideFlag15th}`;
    document.getElementById('asia-transfer-1st').innerHTML = `$${asia1st.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}${extraFlag(manualByCycle.asia1st)}${asiaOverrideFlag1st}`;
    document.getElementById('asia-transfer-15th').innerHTML = `$${asia15th.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}${extraFlag(manualByCycle.asia15th)}${asiaOverrideFlag15th}`;
    document.getElementById('jason-transfer').innerHTML = `Monthly Total: $${(jason1st + jason15th).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}${extraFlag(manualByCycle.jason1st + manualByCycle.jason15th)}${jasonOverrideFlag1st || jasonOverrideFlag15th ? '<span class="dynamic-override-flag" title="A cycle in this month was overridden">&#9873;</span>' : ''}`;
    document.getElementById('asia-transfer').innerHTML = `Monthly Total: $${(asia1st + asia15th).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}${extraFlag(manualByCycle.asia1st + manualByCycle.asia15th)}${asiaOverrideFlag1st || asiaOverrideFlag15th ? '<span class="dynamic-override-flag" title="A cycle in this month was overridden">&#9873;</span>' : ''}`;

    // Breakdown of what actually makes up each person's monthly transfer total — Expenses (their
    // 50/50 share of joint bills), Allocations (their own personal allocation entries), and Extra
    // Transfers (one-off manual transfers, added via "Extra Transfers" above), each on its own line.
    const fmtMoney = v => `$${Math.abs(v).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
    // Monthly total breakdown: one line, slash-separated. Per-cycle breakdowns (below) stay one
    // item per line — they're already inside a narrow cycle box where a slash-separated line would
    // wrap awkwardly.
    const renderTransferBreakdownInline = (elId, expenses, allocations, extra) => {
        const el = document.getElementById(elId);
        if (!el) return;
        el.innerHTML = `Expenses: ${fmtMoney(expenses)} &nbsp;/&nbsp; Allocations: ${fmtMoney(allocations)} &nbsp;/&nbsp; Extra Transfers: ${extra < 0 ? '-' : ''}${fmtMoney(extra)}`;
    };
    const renderTransferBreakdown = (elId, expenses, allocations, extra) => {
        const el = document.getElementById(elId);
        if (!el) return;
        el.innerHTML = `Expenses: ${fmtMoney(expenses)}<br>Allocations: ${fmtMoney(allocations)}<br>Extra Transfers: ${extra < 0 ? '-' : ''}${fmtMoney(extra)}`;
    };
    renderTransferBreakdownInline('jason-transfer-breakdown',
        split1st.jointShare + split15th.jointShare,
        split1st.jasonAllocations + split15th.jasonAllocations,
        manualByCycle.jason1st + manualByCycle.jason15th);
    renderTransferBreakdownInline('asia-transfer-breakdown',
        split1st.jointShare + split15th.jointShare,
        split1st.asiaAllocations + split15th.asiaAllocations,
        manualByCycle.asia1st + manualByCycle.asia15th);
    // Same breakdown, but scoped to each individual cycle (1st/15th) rather than the monthly total —
    // shown right under each cycle's own transfer amount box.
    renderTransferBreakdown('jason-transfer-1st-breakdown', split1st.jointShare, split1st.jasonAllocations, manualByCycle.jason1st);
    renderTransferBreakdown('jason-transfer-15th-breakdown', split15th.jointShare, split15th.jasonAllocations, manualByCycle.jason15th);
    renderTransferBreakdown('asia-transfer-1st-breakdown', split1st.jointShare, split1st.asiaAllocations, manualByCycle.asia1st);
    renderTransferBreakdown('asia-transfer-15th-breakdown', split15th.jointShare, split15th.asiaAllocations, manualByCycle.asia15th);

    const manualTransfersBody = document.getElementById('manual-transfers-body');
    manualTransfersBody.innerHTML = '';
    let displayManual = monthlyManualTransfers;
    if (currentCycle !== 'month') {
        displayManual = displayManual.filter(t => {
            const cycle = Number(t.date.slice(8, 10)) < 15 ? '1st' : '15th';
            return cycle === currentCycle;
        });
    }
    displayManual.forEach(transfer => {
        const cycle = Number(transfer.date.slice(8, 10)) < 15 ? '1st' : '15th';
        const row = document.createElement('tr');
        row.innerHTML = `<td>${formatDateDisplay(transfer.date)}</td><td>${transfer.person === 'asia' ? 'Asia' : 'Jason'}</td><td>${escapeHTML(transfer.description)}</td><td>${cycle}</td><td class="positive font-heading">+$${Number(transfer.amount).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td><td><button type="button" class="action-btn small-btn danger-btn delete-manual-transfer-btn">Delete</button></td>`;
        row.querySelector('.delete-manual-transfer-btn').addEventListener('click', () => {
            if (!confirm(`Delete the planned transfer on ${formatDateDisplay(transfer.date)}?`)) return;
            state.manualTransfers = (state.manualTransfers || []).filter(item => item.id !== transfer.id);
            state.jointRegister = (state.jointRegister || []).filter(item => item.linkedManualTransferId !== transfer.id);
            Object.keys(state.personalCalendar || {}).forEach(key => {
                state.personalCalendar[key] = (state.personalCalendar[key] || []).filter(item => item.linkedManualTransferId !== transfer.id);
            });
            saveDatabase();
            renderApp();
        });
        manualTransfersBody.appendChild(row);
    });
    if (!displayManual.length) manualTransfersBody.innerHTML = '<tr><td colspan="6" class="muted-text" style="text-align:center;">No manual transfers planned for this period.</td></tr>';

    const jointBody = document.getElementById('joint-bills-body');
    jointBody.innerHTML = '';
    const ownershipFilter = state.billTrackerOwnership || 'joint';
    document.getElementById('bill-tracker-title').textContent = ownershipFilter === 'jason' ? 'Personal Expenses' : 'Joint Expenses';
    document.getElementById('btn-add-joint-bill').textContent = ownershipFilter === 'jason' ? '+ Add Personal Expense' : '+ Add Joint Expense';
    const categoryFilter = document.getElementById('bill-category-filter').value;
    const billSort = state.billTrackerSorts?.[ownershipFilter] || { key: ownershipFilter === 'jason' ? 'dueDay' : 'account', direction: 'asc' };
    document.getElementById('bill-sort-select').classList.add('hidden');
    // Text is set on the wrapper span (not the <th> itself) once column-filter buttons have been
    // wired in, since setting .textContent directly on the <th> would wipe out the filter button.
    const dateHeaderEl = document.getElementById('bill-date-header');
    const dateHeaderLabel = ownershipFilter === 'jason' ? 'Charge Day' : 'Day';
    const dateHeaderInner = dateHeaderEl.querySelector('.col-th-inner');
    if (dateHeaderInner) dateHeaderInner.textContent = dateHeaderLabel; else dateHeaderEl.textContent = dateHeaderLabel;
    let displayBills = ['cycle1st', 'cycle15th'].flatMap(cycleKey =>
        (mBills[cycleKey].bills || []).map((rawBill, idx) => ({ bill: normalizeBillSplitterItem(rawBill, cycleKey), cycleKey, idx }))
    );
    displayBills.forEach(entry => { mBills[entry.cycleKey].bills[entry.idx] = entry.bill; });
    displayBills = displayBills.filter(entry => (entry.bill.ownership || 'joint') === ownershipFilter);

    // A 'both'-cycle bill (its monthly total split evenly across the 1st and 15th) used to render as
    // ONE combined row with a "1st: $X | 15th: $X" sub-line — that made it impossible to sort/filter
    // by each cycle's own transfer amount. Expanding into two virtual display rows here (still backed
    // by the exact same single stored bill/cycleKey — editing or deleting either row affects the
    // whole thing, matching today's single-record model) lets every downstream filter/sort/render
    // step just treat `effectiveCycle`/`splitAmount` as if it were a real single-cycle bill.
    displayBills = displayBills.flatMap(entry => {
        if (entry.bill.cycleAllocation === 'both') {
            return ['1st', '15th'].map(effectiveCycle => ({ ...entry, effectiveCycle, splitAmount: entry.bill.budgetAmount / 2, isSplit: true }));
        }
        return [{ ...entry, effectiveCycle: entry.bill.cycleAllocation === '15th' ? '15th' : '1st', splitAmount: entry.bill.budgetAmount, isSplit: false }];
    });

    // Expense calendar — same Joint/Personal toggle as the list below, just plotted by due day
    // instead of listed in a table. Uses the ownership-filtered set before the category list filter
    // narrows it further. Also respects the Month/1st Cycle/15th Cycle header filter (currentCycle),
    // same as the list below it, so switching to a cycle shows only that half of the month and the
    // panel shrinks/grows to fit instead of always padding out to the full month.
    const isExpenseCalendar = state.expenseCalendarViewMode === 'calendar';
    document.getElementById('expense-calendar-view')?.classList.toggle('hidden', !isExpenseCalendar);
    document.getElementById('expense-list-view')?.classList.toggle('hidden', isExpenseCalendar);
    document.querySelectorAll('#expense-calendar-view-toggle .segment-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.expenseViewMode === (state.expenseCalendarViewMode || 'list'));
    });
    document.getElementById('joint-expenses-content')?.classList.toggle('calendar-mode', isExpenseCalendar);
    if (isExpenseCalendar) {
        // Pay Date mode plots every bill on its own real charge/due day (real Fridays for a
        // biweekly paycheck-funded bill, etc.); Transfer Date mode plots it on the 1st/15th date
        // its budgeted share actually moves — see getBillCalendarOccurrences.
        const expenseDateMode = state.expenseCalendarDateMode === 'transfer' ? 'transfer' : 'pay';
        document.getElementById('expense-calendar-date-mode-toggle')?.classList.remove('hidden');
        document.querySelectorAll('#expense-calendar-date-mode-toggle .segment-btn').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.expenseDateMode === expenseDateMode);
        });
        const calendarItems = displayBills.flatMap(entry =>
            getBillCalendarOccurrences(entry.bill, state.currentYear, state.currentMonth, expenseDateMode)
                .map(occ => ({ ...entry.bill, cycleKey: entry.cycleKey, dueDay: occ.dueDay, budgetAmount: occ.budgetAmount }))
        );
        const daysInCalMonth = new Date(state.currentYear, MONTH_ORDER.indexOf(state.currentMonth) + 1, 0).getDate();
        const cycleRange = currentCycle === '1st' ? { start: 1, end: 14 }
            : currentCycle === '15th' ? { start: 15, end: daysInCalMonth }
            : null;
        renderBillCalendarGrid('expense-calendar-days', state.currentYear, state.currentMonth,
            calendarItems, (item) => openBillSplitterEditor(item, item.cycleKey), cycleRange);
    } else {
        document.getElementById('expense-calendar-date-mode-toggle')?.classList.add('hidden');
    }

    if (currentCycle !== 'month') {
        displayBills = displayBills.filter(entry => entry.effectiveCycle === currentCycle);
    }
    if (categoryFilter !== 'all') displayBills = displayBills.filter(entry => entry.bill.category === categoryFilter);
    const jointBillsSearch = document.getElementById('joint-bills-master-search')?.value || '';
    if (jointBillsSearch.trim()) {
        displayBills = displayBills.filter(({ bill }) => {
            const sourceName = bill.paymentSource === 'none' || !bill.paymentSource ? 'No Source' : bill.paymentSource === 'jointChecking' ? 'Joint Checking' : bill.paymentSource === 'jasonChecking' ? "Jason's Checking" : bill.paymentSource === 'asiaChecking' ? "Asia's Checking" : (state.loans.find(card => card.id === bill.paymentSource)?.name || 'Credit Card');
            return matchesMasterSearch(jointBillsSearch, bill.account, bill.category, bill.ownership, sourceName, Number(bill.budgetAmount || 0).toFixed(2));
        });
    }
    displayBills.sort((a, b) => {
        const value = entry => {
            const bill = entry.bill;
            if (billSort.key === 'dueDay') {
                // Monthly charges sort numerically by day-of-month (0-31). Subscriptions (weekly,
                // biweekly, etc.) don't have a meaningful day-of-month, so they're grouped together
                // below all numeric days, ordered by frequency type then by weekday.
                if (bill.chargeFrequency === 'monthly') return Number(bill.dueDay) || 0;
                const freqOrder = { weekly: 0, biweekly: 1, fourweekly: 2, quarterly: 3, annual: 4 }[bill.chargeFrequency] ?? 5;
                const weekday = bill.frequencyStartDate
                    ? new Date(bill.frequencyStartDate + 'T00:00:00').getDay()
                    : (Number.isInteger(bill.weeklyDay) ? bill.weeklyDay : 0);
                return 1000 + freqOrder * 10 + weekday;
            }
            // Sort by each row's own per-cycle amount (splitAmount), not the bill's full monthly
            // total — the whole point of splitting a 'both' bill into two rows is being able to
            // sort/filter by what actually transfers on THAT cycle.
            if (billSort.key === 'budgetAmount') return Number(entry.splitAmount) || 0;
            if (billSort.key === 'monthlyTotal') return Number(bill.budgetAmount) || 0;
            if (billSort.key === 'paymentAmount') return Number(bill.paymentAmount) || 0;
            if (billSort.key === 'isRecurring') return bill.isRecurring ? 1 : 0;
            if (billSort.key === 'source') {
                // Matches the label shown in the Source column's badge (getBillIndicatorBadge).
                if (bill.billTrackerSettingId) return 'bill tracker';
                if (bill.isMortgage) return 'loan · recurring';
                if (bill.linkedCardPaymentId) {
                    const target = bill.payoffTargetId ? state.loans.find(l => l.id === bill.payoffTargetId) : null;
                    return target && target.type === 'loan' ? 'loan' : 'credit card';
                }
                return 'manual';
            }
            return String(bill[billSort.key] || '').toLowerCase();
        };
        const first = value(a); const second = value(b);
        const comparison = typeof first === 'number' ? first - second : first.localeCompare(second);
        return billSort.direction === 'desc' ? -comparison : comparison;
    });

    displayBills.forEach(({ bill, cycleKey, idx, effectiveCycle, splitAmount, isSplit }) => {
        const sourceName = bill.paymentSource === 'none' || !bill.paymentSource ? 'No Source' : bill.paymentSource === 'jointChecking' ? 'Joint Checking' : bill.paymentSource === 'jasonChecking' ? "Jason's Checking" : bill.paymentSource === 'asiaChecking' ? "Asia's Checking" : (state.loans.find(card => card.id === bill.paymentSource)?.name || 'Credit Card');
        const cycleLabel = `${effectiveCycle}${isSplit ? ' <span class="split-badge" title="This bill\'s monthly total is split across both the 1st and 15th cycles">&#128256; Split</span>' : ''}`;
        const frequencyLabels = { monthly: 'Monthly', weekly: 'Weekly', biweekly: 'Every 2 weeks', fourweekly: 'Every 4 weeks', quarterly: 'Every 3 months', annual: 'Annual' };
        const categoryLabels = { bill: 'Bill', expense: 'Expense', utility: 'Utility', savings: 'Savings / Investments' };
        const categoryLabel = categoryLabels[bill.category] || (bill.category.charAt(0).toUpperCase() + bill.category.slice(1));
        const isAutoCardOrLoan = !!bill.linkedCardPaymentId && bill.cardPaymentKind === 'auto';
        const linkedTarget = bill.linkedCardPaymentId && bill.payoffTargetId ? state.loans.find(l => l.id === bill.payoffTargetId) : null;
        const mortgageTarget = bill.isMortgage && bill.mortgageLoanId ? state.loans.find(l => l.id === bill.mortgageLoanId) : null;
        const recurringRange = mortgageTarget
            ? `Yes<br><span class="muted-text">${mortgageTarget.paymentEndDate ? 'Through ' + mortgageTarget.paymentEndDate : 'Ongoing'}</span>`
            : (bill.isRecurring
                ? `Yes<br><span class="muted-text">${bill.recurringStartMonth ? 'Starts ' + bill.recurringStartMonth : 'Current'}${bill.recurringEndMonth ? ' through ' + bill.recurringEndMonth : ''}</span>`
                : (isAutoCardOrLoan
                    ? `Yes<br><span class="muted-text">${linkedTarget && linkedTarget.paymentEndDate ? 'Through ' + linkedTarget.paymentEndDate : 'Ongoing'}</span>`
                    : 'No'));
        const row = document.createElement('tr');
        row.innerHTML = `
            <td><strong>${escapeHTML(bill.account)}</strong></td>
            <td><strong>${categoryLabel}</strong>${bill.billTrackerCategory ? `<br><span class="muted-text">${escapeHTML(bill.billTrackerCategory)}</span>` : ''}<br>${bill.entryType === 'actual' ? 'Actual Charge' : 'Transfer Only'}<br><span class="muted-text">${bill.ownership === 'joint' ? 'Joint' : 'Personal'}</span></td>
            <td>${getBillIndicatorBadge(bill)}</td>
            <td>${cycleLabel}</td>
            <td>${bill.chargeFrequency === 'monthly' ? 'Day ' + bill.dueDay : getSubscriptionDayLabel(bill, frequencyLabels)}</td>
            <td class="font-heading">$${bill.budgetAmount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
            <td class="font-heading">$${splitAmount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
            <td class="font-heading">${bill.ownership === 'joint' ? `Jason: $${(splitAmount / 2).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}<br>Asia: $${(splitAmount / 2).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}` : '<span class="muted-text">&mdash;</span>'}</td>
            <td class="${bill.entryType === 'actual' ? 'negative' : ''} font-heading">${bill.entryType === 'actual' ? '$' + (isSplit ? bill.paymentAmount / 2 : bill.paymentAmount).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '—'}</td>
            <td>${bill.entryType === 'actual' ? sourceName : 'Not posted'}</td>
            <td>${recurringRange}</td>
            <td class="table-actions-cell"><button class="action-btn small-btn edit-bill-btn"${isSplit ? ' title="Editing here updates both the 1st and 15th amounts together"' : ''}>Edit</button><button class="action-btn small-btn danger-btn delete-bill-btn"${isSplit ? ' title="Deleting here removes both the 1st and 15th rows together"' : ''}>Delete</button></td>`;
        row.querySelector('.edit-bill-btn').addEventListener('click', () => openBillSplitterEditor(bill, cycleKey));
        row.querySelector('.delete-bill-btn').addEventListener('click', () => deleteBillSplitterItemInteractive(bill, cycleKey));
        // Mobile has no Actions column (see index.css) — tapping the row opens the same editor
        // desktop reaches via its own Edit button, and that modal has its own Delete button.
        if (isMobileViewport()) row.addEventListener('click', () => openBillSplitterEditor(bill, cycleKey));
        jointBody.appendChild(row);
    });
    if (!displayBills.length) jointBody.innerHTML = `<tr><td colspan="12" class="muted-text" style="text-align:center;">${categoryFilter === 'all' ? 'No Bill Splitter items logged for this period.' : 'No items match this category filter.'}</td></tr>`;
    setupTableColumnFilters('#joint-expenses-content thead', 'jointBills', () => document.getElementById('joint-bills-body'), [11]);
    applyColumnFilters(jointBody, 'jointBills');
    updateSortIndicators('#joint-expenses-content thead', 'data-bill-sort', billSort);
    const personalBody = document.getElementById('personal-allocations-body');
    personalBody.innerHTML = '';
    const allocationEntries = ['1st', '15th'].flatMap(cycle => {
        const cycleKey = cycle === '1st' ? 'cycle1st' : 'cycle15th';
        return (mBills[cycleKey].contributions || []).map((alloc, idx) => ({ alloc, idx, cycle, cycleKey }));
    });
    // A 'both'-cycle allocation used to render as ONE combined row with the full monthly total —
    // same problem and same fix as Bill Splitter bills above: expand into two virtual display rows
    // (still backed by the exact same single stored contribution object; editing or deleting either
    // row affects the whole thing) so sort/filter/cycle-scope can treat each row as its own single-
    // cycle entry. Kept separate from `allocationEntries` (used below for bulk-select/delete-by-id
    // lookups) so a bulk delete never double-processes the same physical record via its two rows.
    let displayAllocations = allocationEntries.flatMap(entry => {
        if (entry.alloc.cycle === 'both') {
            return ['1st', '15th'].map(effectiveCycle => ({ ...entry, cycle: effectiveCycle, isSplit: true, jasonSplit: (Number(entry.alloc.jason) || 0) / 2, asiaSplit: (Number(entry.alloc.asia) || 0) / 2 }));
        }
        return [{ ...entry, isSplit: false, jasonSplit: Number(entry.alloc.jason) || 0, asiaSplit: Number(entry.alloc.asia) || 0 }];
    });
    if (currentCycle !== 'month') {
        displayAllocations = displayAllocations.filter(entry => entry.cycle === currentCycle);
    }
    const personalAllocSearch = document.getElementById('personal-allocations-master-search')?.value || '';
    if (personalAllocSearch.trim()) {
        displayAllocations = displayAllocations.filter(({ alloc, cycle }) => matchesMasterSearch(
            personalAllocSearch, alloc.name, cycle, Number(alloc.jason || 0).toFixed(2), Number(alloc.asia || 0).toFixed(2)
        ));
    }
    const allocationSort = state.billTrackerSorts?.allocations || { key: 'name', direction: 'asc' };
    displayAllocations.sort((a, b) => {
        const value = entry => {
            // Sort by each row's own per-cycle amount, matching the whole point of splitting a
            // 'both' allocation into two rows — being able to sort/filter by what actually moves on
            // that cycle, not the combined monthly total.
            if (allocationSort.key === 'cycle') return entry.cycle === '1st' ? 1 : 15;
            if (allocationSort.key === 'jason') return entry.jasonSplit;
            if (allocationSort.key === 'asia') return entry.asiaSplit;
            if (allocationSort.key === 'monthlyTotal') return (Number(entry.alloc.jason) || 0) + (Number(entry.alloc.asia) || 0);
            return String(entry.alloc.name || '').toLowerCase();
        };
        const first = value(a); const second = value(b);
        const comparison = typeof first === 'number' ? first - second : first.localeCompare(second);
        return allocationSort.direction === 'desc' ? -comparison : comparison;
    });
    // Ids the user has checked for bulk deletion. Kept outside `state` (purely a transient UI
    // selection, not data worth persisting/syncing) but module-level so it survives the re-renders
    // that happen between checking a box and clicking "Delete Selected". Pruned against this
    // render's actual rows below so a stale id from a previous month/filter can't linger and
    // silently delete something the user can no longer even see.
    const displayedAllocIds = new Set(displayAllocations.map(({ alloc }) => alloc.id));
    Array.from(_selectedAllocationIds).forEach(id => { if (!displayedAllocIds.has(id)) _selectedAllocationIds.delete(id); });
    const deleteSelectedBtn = document.getElementById('btn-delete-selected-allocations');
    const selectAllCheckbox = document.getElementById('alloc-select-all');
    const updateAllocSelectionUI = () => {
        if (deleteSelectedBtn) {
            deleteSelectedBtn.classList.toggle('hidden', _selectedAllocationIds.size === 0);
            deleteSelectedBtn.textContent = `Delete Selected (${_selectedAllocationIds.size})`;
        }
        if (selectAllCheckbox) {
            selectAllCheckbox.checked = displayAllocations.length > 0 && displayAllocations.every(({ alloc }) => _selectedAllocationIds.has(alloc.id));
        }
    };
    displayAllocations.forEach(({ alloc, idx, cycle, cycleKey, isSplit, jasonSplit, asiaSplit }) => {
            const row = document.createElement('tr');
            if (!alloc.id) alloc.id = 'alloc-' + Math.random().toString(36).substr(2, 9);
            row.dataset.allocId = alloc.id;
            const isRecurring = !!state.allocationTemplates[alloc.seriesId];
            const formatAllocationAmount = (value, isPersonRecurring) => {
                if (value === null || value === undefined || value === '') return '<span class="muted-text">&mdash;</span>';
                const amount = Number(value) || 0;
                const sign = amount > 0 ? '+' : amount < 0 ? '-' : '';
                const icon = (isRecurring && isPersonRecurring) ? ' <span class="recurring-icon" title="Recurring allocation" style="font-size: 0.85rem; margin-left: 4px; cursor: help;">🔁</span>' : '';
                return `<span class="${amount < 0 ? 'negative' : 'positive'}">${sign}$${Math.abs(amount).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</span>${icon}`;
            };
            // Split rows show each cycle's own HALF of the stored total (jasonSplit/asiaSplit), not
            // the full alloc.jason/alloc.asia — that full total now lives in its own Monthly Total
            // column instead.
            const jasonHtml = formatAllocationAmount(jasonSplit, alloc.jason !== null && alloc.jason !== undefined && Number(alloc.jason) !== 0);
            const asiaHtml = formatAllocationAmount(asiaSplit, alloc.asia !== null && alloc.asia !== undefined && Number(alloc.asia) !== 0);
            const cycleDisplay = `${cycle}${isSplit ? ' <span class="split-badge" title="This allocation\'s monthly total is split across both the 1st and 15th cycles">&#128256; Split</span>' : ''}`;
            const monthlyTotalHtml = `Jason: ${formatAllocationAmount(alloc.jason, false)}<br>Asia: ${formatAllocationAmount(alloc.asia, false)}`;
            row.innerHTML = `<td><input type="checkbox" class="alloc-select-row" ${_selectedAllocationIds.has(alloc.id) ? 'checked' : ''}></td><td><strong>${escapeHTML(alloc.name)}</strong><br><span class="muted-text">${(alloc.frequency || 'monthly').charAt(0).toUpperCase() + (alloc.frequency || 'monthly').slice(1)}${alloc.frequency === 'weekly' ? ' Â· ' + (alloc.occurrenceCount || 0) + ' occurrences this month' : ''}</span></td><td><span class="card-icon info" style="font-size:.75rem;padding:2px 6px;">Due on ${cycleDisplay}</span></td><td class="font-heading alloc-amt-cell" data-person="jason" title="${isSplit ? 'Split allocation — double-click to open the full editor' : 'Double-click to edit this month only'}">${jasonHtml}</td><td class="font-heading alloc-amt-cell" data-person="asia" title="${isSplit ? 'Split allocation — double-click to open the full editor' : 'Double-click to edit this month only'}">${asiaHtml}</td><td class="font-heading">${monthlyTotalHtml}</td><td class="table-actions-cell"><button class="action-btn small-btn outline-btn edit-alloc-btn"${isSplit ? ' title="Editing here updates both the 1st and 15th amounts together"' : ''}>Edit</button> <button class="action-btn small-btn danger-btn delete-alloc-btn"${isSplit ? ' title="Deleting here removes both the 1st and 15th rows together"' : ''}>Delete</button></td>`;
            row.querySelector('.alloc-select-row').addEventListener('change', (e) => {
                if (e.target.checked) _selectedAllocationIds.add(alloc.id); else _selectedAllocationIds.delete(alloc.id);
                // Keep any sibling row sharing this same underlying allocation (its other split half,
                // already in the DOM) visually in sync instead of waiting for the next full render.
                personalBody.querySelectorAll(`tr[data-alloc-id="${alloc.id}"] .alloc-select-row`).forEach(cb => { cb.checked = e.target.checked; });
                updateAllocSelectionUI();
            });
            row.querySelector('.edit-alloc-btn').addEventListener('click', () => openAllocationEditor(alloc, cycleKey));
            // Quick single-month amount edit: double-clicking the Jason/Asia cell edits `alloc` in
            // place (it's the actual generated contribution row object for THIS month/cycle, already
            // sitting in mBills[cycleKey].contributions), never the recurring allocationTemplates
            // entry that drives future months — this is the same "edit the generated occurrence
            // directly" override pattern the app already relies on elsewhere (see
            // applyAllocationTemplatesForMonth's hasRole check), so it's safe and won't get clobbered
            // or regenerated on future renders. Split rows only ever show HALF the stored value, so
            // this inline editor (which writes the raw value straight back to alloc[person]) is
            // disabled for them — it opens the full modal editor instead, to avoid silently writing a
            // half-amount back as if it were the whole total.
            if (isSplit) {
                row.querySelectorAll('.alloc-amt-cell').forEach(cell => {
                    cell.style.cursor = 'pointer';
                    cell.addEventListener('dblclick', () => openAllocationEditor(alloc, cycleKey));
                });
            } else row.querySelectorAll('.alloc-amt-cell').forEach(cell => {
                cell.addEventListener('dblclick', () => {
                    const person = cell.dataset.person;
                    const currentValue = alloc[person];
                    const input = document.createElement('input');
                    input.type = 'number';
                    input.step = '0.01';
                    input.className = 'alloc-amt-inline-input';
                    input.value = currentValue === null || currentValue === undefined || currentValue === '' ? '' : currentValue;
                    input.style.width = '90px';
                    cell.innerHTML = '';
                    cell.appendChild(input);
                    input.focus();
                    input.select();
                    const commit = () => {
                        const raw = input.value.trim();
                        const newValue = raw === '' ? null : (parseFloat(raw) || 0);
                        alloc[person] = newValue;
                        alloc[`source${person.charAt(0).toUpperCase()}${person.slice(1)}`] = newValue;
                        recalculateBillCycleTotals(mBills);
                        saveDatabase();
                        renderApp();
                        logSystem(`Updated ${alloc.name} (${person === 'jason' ? 'Jason' : 'Asia'}) for ${state.currentMonth} ${state.currentYear} only.`);
                    };
                    let committed = false;
                    input.addEventListener('blur', () => { if (!committed) { committed = true; commit(); } });
                    input.addEventListener('keydown', (e) => {
                        if (e.key === 'Enter') { committed = true; input.blur(); commit(); }
                        else if (e.key === 'Escape') { committed = true; renderApp(); }
                    });
                });
            });
            row.querySelector('.delete-alloc-btn').addEventListener('click', () => deleteAllocationInteractive(alloc));
            // Mobile has no Actions column (see index.css) — tapping the row opens the same editor
            // desktop reaches via its own Edit button, and that modal has its own Delete button.
            // Excludes the checkbox (still needed for multi-select) and the Jason/Asia cells (which
            // keep their own existing double-click-to-inline-edit behavior).
            if (isMobileViewport()) {
                row.addEventListener('click', (e) => {
                    if (e.target.closest('input, .alloc-amt-cell')) return;
                    openAllocationEditor(alloc, cycleKey);
                });
            }
            personalBody.appendChild(row);
    });
    if (!displayAllocations.length) personalBody.innerHTML = '<tr><td colspan="7" class="muted-text" style="text-align:center;">No personal allocations logged for this period.</td></tr>';
    updateAllocSelectionUI();
    if (selectAllCheckbox && !selectAllCheckbox._wired) {
        selectAllCheckbox._wired = true;
        selectAllCheckbox.addEventListener('change', (e) => {
            const rows = personalBody.querySelectorAll('.alloc-select-row');
            const ids = displayAllocations.map(({ alloc }) => alloc.id);
            if (e.target.checked) ids.forEach(id => _selectedAllocationIds.add(id));
            else ids.forEach(id => _selectedAllocationIds.delete(id));
            rows.forEach(cb => { cb.checked = e.target.checked; });
            updateAllocSelectionUI();
        });
    }
    if (deleteSelectedBtn && !deleteSelectedBtn._wired) {
        deleteSelectedBtn._wired = true;
        deleteSelectedBtn.addEventListener('click', () => {
            if (_selectedAllocationIds.size === 0) return;
            const targets = allocationEntries.filter(({ alloc }) => _selectedAllocationIds.has(alloc.id));
            if (!targets.length) return;
            if (!confirm(`Delete ${targets.length} selected personal allocation(s) from ${state.currentMonth} ${state.currentYear}?`)) return;
            const deleteFuture = confirm(`Also delete these from all future months where they recur?\n\nOK = current and future\nCancel = current month only`);
            let removed = 0;
            targets.forEach(({ alloc }) => { removed += deleteAllocationOccurrence(alloc, state.currentYear, state.currentMonth, deleteFuture); });
            _selectedAllocationIds.clear();
            saveDatabase();
            renderApp();
            logSystem(`Deleted ${targets.length} selected personal allocation(s) (${removed} occurrence(s) removed).`);
        });
    }
    setupTableColumnFilters('#personal-allocations-content thead', 'personalAllocations', () => document.getElementById('personal-allocations-body'), [0, 6]);
    applyColumnFilters(personalBody, 'personalAllocations');
    updateSortIndicators('#personal-allocations-content thead', 'data-allocation-sort', allocationSort);
}
// Lives under the Bill Tracker tab (relocated from Bill Splitter) but keeps feeding
// applySeasonalExpensesForMonth()/applySeasonalChargeForMonth(), which are tab-agnostic and read
// state.seasonalExpenses directly — moving the management UI doesn't touch that generator logic.
function renderSeasonalExpensesSection() {
    const seasonalBody = document.getElementById('seasonal-expenses-body');
    if (!seasonalBody) return;
    seasonalBody.innerHTML = '';
    const seasonalCountLine = document.getElementById('seasonal-expenses-count-line');
    if (seasonalCountLine) {
        const count = (state.seasonalExpenses || []).length;
        seasonalCountLine.textContent = count === 0 ? 'No seasonal expenses tracked' : `${count} seasonal expense${count === 1 ? '' : 's'} tracked`;
    }
    const seasonalSort = state.billTrackerSorts.seasonal || { key: 'month', direction: 'asc' };
    const sortedSeasonalExpenses = [...(state.seasonalExpenses || [])].sort((a, b) => {
        const value = expense => {
            if (seasonalSort.key === 'amount') return Number(expense.amount) || 0;
            if (seasonalSort.key === 'cycles') return Number(expense.cycles) || 0;
            if (seasonalSort.key === 'month') return expense.startDate || '';
            return String(expense[seasonalSort.key] || '').toLowerCase();
        };
        const first = value(a); const second = value(b);
        const comparison = typeof first === 'number' ? first - second : first.localeCompare(second);
        return seasonalSort.direction === 'desc' ? -comparison : comparison;
    });
    sortedSeasonalExpenses.forEach(expense => {
        const row = document.createElement('tr');
        const installment = expense.amount / expense.cycles;
        const seasonalDateRange = expense.startDate + (expense.endDate ? ` &ndash; ${expense.endDate}` : '');
        const frequencyLabel = expense.isRecurring ? `Repeats ${expense.frequency || 'yearly'}` : 'One-time';
        const chargeSourceCard = state.loans.find(l => l.id === expense.chargeSource && l.type === 'credit');
        const chargeSourceLabel = chargeSourceCard ? escapeHTML(chargeSourceCard.name) : (expense.chargeSource === 'joint' ? 'Joint' : 'Personal');
        const chargeLabel = expense.hasCharge ? `$${Number(expense.chargeAmount || 0).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} on ${formatDateDisplay(expense.chargeDate)} (${chargeSourceLabel})` : '&mdash;';
        row.innerHTML = `<td><strong>${escapeHTML(expense.name)}</strong></td><td>${seasonalDateRange}</td><td>$${expense.amount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td><td>${expense.cycles} cycles × $${installment.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td><td>${frequencyLabel}</td><td>${chargeLabel}</td><td><button class="action-btn small-btn outline-btn edit-seasonal-btn">Edit</button> <button class="action-btn small-btn danger-btn delete-seasonal-btn">Delete</button></td>`;
        row.querySelector('.edit-seasonal-btn').addEventListener('click', () => openSeasonalEditor(expense));
        row.querySelector('.delete-seasonal-btn').addEventListener('click', () => {
            if (!confirm(`Delete ${expense.name} and its generated funding entries?`)) return;
            removeSeasonalInstallments(expense.id); state.seasonalExpenses = state.seasonalExpenses.filter(item => item.id !== expense.id); saveDatabase(); renderApp();
        });
        seasonalBody.appendChild(row);
    });
    setupTableColumnFilters('#seasonal-expenses-content thead', 'seasonal', () => document.getElementById('seasonal-expenses-body'), [6]);
    applyColumnFilters(seasonalBody, 'seasonal');
    updateSortIndicators('#seasonal-expenses-content thead', 'data-seasonal-sort', seasonalSort);
    // The card itself (header + "Add Seasonal Expense" button) always stays visible so there's a way
    // to add the first one — only the "no items" placeholder text is skipped when empty, leaving the
    // table body simply blank instead.
}
// 4. RENDER DELIVERY EARNINGS TAB (Platform totals & weekly grid)
// Reflects state.deliveryColumnPrefs (which platform columns are visible, mobile-only feature — cash
// and grub hub especially are rarely used by some, and the log is cramped enough on a phone that
// hiding unused columns matters) onto both the checkboxes and the table's hide-col-* classes.
function syncDeliveryColumnToggles() {
    const prefs = state.deliveryColumnPrefs || {};
    const table = document.getElementById('delivery-table');
    document.querySelectorAll('.delivery-col-toggle').forEach(cb => {
        const col = cb.dataset.col;
        const visible = prefs[col] !== false;
        cb.checked = visible;
        if (table) table.classList.toggle(`hide-col-${col}`, !visible);
    });
}

// Computes real pixel offsets for the delivery grid's two stacked sticky bars (the "Show columns"
// row, then the table header right below it) instead of relying on hardcoded CSS pixel guesses.
// Those guesses were calibrated against the desktop .main-sticky-dashboard's height, but that
// element drops to position:static on mobile (see the 900px media query) — with nothing sticky
// above it there anymore, a fixed offset left the "Show columns" row (and the header stacked below
// it) floating at a fixed distance from the top that didn't correspond to anything, landing them
// visually mid-list instead of pinned above row 1. Measuring the actual rendered height of
// whatever's sticky above adapts correctly to any header height, wrapped multi-line "Show columns"
// row, or breakpoint — desktop and mobile alike.
// Same idea as _updateDeliveryStickyOffsets() below — stacks the Personal/Joint List view's own
// sticky title+quick-add block directly beneath whatever's already sticky above it (the dashboard
// header's month/year nav + Calendar/List/Month/Full Year toggles), instead of both pinning to
// top:0 and physically overlapping.
function _updateListViewStickyOffset() {
    const stickyDashboard = document.querySelector('.main-sticky-dashboard');
    const dashboardIsSticky = stickyDashboard && getComputedStyle(stickyDashboard).position === 'sticky' && stickyDashboard.offsetWidth > 0 && stickyDashboard.offsetHeight > 0;
    const dashboardHeight = dashboardIsSticky ? stickyDashboard.getBoundingClientRect().height : 0;

    // 1. Personal / Joint List View header & table headers
    const personalHeader = document.querySelector('#dashboard-list-view .list-view-sticky-header');
    let personalHeaderHeight = 0;
    if (personalHeader) {
        personalHeader.style.top = `${dashboardHeight}px`;
        personalHeaderHeight = personalHeader.getBoundingClientRect().height;
    }

    const personalTableHeaders = document.querySelectorAll('#list-view-table-container .data-table th');
    personalTableHeaders.forEach(th => {
        th.style.top = `${dashboardHeight + personalHeaderHeight}px`;
    });

    // 2. CC List View header & table headers
    const ccHeader = document.querySelector('#cc-list-view-container .list-view-sticky-header');
    let ccHeaderHeight = 0;
    if (ccHeader) {
        ccHeader.style.top = `${dashboardHeight}px`;
        ccHeaderHeight = ccHeader.getBoundingClientRect().height;
    }

    const ccTableHeaders = document.querySelectorAll('#cc-list-view-table-container .data-table th');
    ccTableHeaders.forEach(th => {
        th.style.top = `${dashboardHeight + ccHeaderHeight}px`;
    });

    // 3. Savings Ledger header & table headers — per explicit user request, 2026-08-05, same pattern
    // as Personal/Joint and CC above. Shared between Calendar and List view (one header above both),
    // so the table-header pass below is a no-op whenever #savings-list-view is hidden (Calendar mode
    // — querySelectorAll against a table that isn't showing just returns nothing to iterate).
    const savingsHeader = document.getElementById('savings-list-sticky-header');
    let savingsHeaderHeight = 0;
    if (savingsHeader) {
        savingsHeader.style.top = `${dashboardHeight}px`;
        savingsHeaderHeight = savingsHeader.getBoundingClientRect().height;
    }
    const savingsTableHeaders = document.querySelectorAll('#savings-list-view .data-table th');
    savingsTableHeaders.forEach(th => {
        th.style.top = `${dashboardHeight + savingsHeaderHeight}px`;
    });
}

if (typeof window !== 'undefined') {
    window.addEventListener('resize', _updateListViewStickyOffset);
    window.addEventListener('scroll', _updateListViewStickyOffset);
    if ('ResizeObserver' in window) {
        const _listViewHeaderObserver = new ResizeObserver(() => {
            _updateListViewStickyOffset();
        });
        const observeHeaders = () => {
            document.querySelectorAll('.list-view-sticky-header, .main-sticky-dashboard').forEach(el => {
                _listViewHeaderObserver.observe(el);
            });
        };
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', observeHeaders);
        } else {
            observeHeaders();
        }
    }
}

function _updateDeliveryStickyOffsets() {
    const colToggles = document.getElementById('delivery-col-toggles');
    const table = document.getElementById('delivery-table');
    if (!colToggles || !table) return;

    // .delivery-grid-card .table-responsive is forced back to overflow:visible on mobile now (index.css,
    // mobile media query) — the platform columns/off-day banner hidden there mean the table no longer
    // has any real horizontal overflow to justify overflow-x:auto's forced-overflow-y-to-auto quirk,
    // which used to trap this header's position:sticky inside its own non-scrolling box instead of the
    // real page scroll. With that freed, mobile shares the page's own scroll same as desktop, so both
    // branches compute the same real pinned-header height instead of mobile hardcoding 0. Confirmed
    // real bug, 2026-08-05 ("make this sticky") — the header was never actually staying visible while
    // scrolling on mobile before this.
    const dashboardHeight = (() => {
        const stickyDashboard = document.querySelector('.main-sticky-dashboard');
        const dashboardIsSticky = stickyDashboard && getComputedStyle(stickyDashboard).position === 'sticky';
        return dashboardIsSticky ? stickyDashboard.getBoundingClientRect().height : 0;
    })();

    // .delivery-col-toggles is not sticky (see index.css) — only the header itself pins, directly
    // below whatever's sticky above it (the dashboard on desktop, nothing on mobile — see above).
    table.querySelectorAll('thead th').forEach(th => {
        th.style.top = `${dashboardHeight}px`;
    });
}

function renderDeliveryTab() {
    const month = state.currentMonth;

    // Collapses the whole Platform Breakdown + Weekly Summary card as one unit — the toggle button
    // lives in the card's own header, outside #delivery-stats-body, so it stays visible and able to
    // bring the content back even while the body itself is hidden.
    const platformBoxCollapsed = !!state.platformBreakdownCollapsed;
    const deliveryStatsBody = document.getElementById('delivery-stats-body');
    const btnTogglePlatform = document.getElementById('btn-toggle-platform-breakdown');
    if (deliveryStatsBody) deliveryStatsBody.classList.toggle('hidden', platformBoxCollapsed);
    if (btnTogglePlatform) btnTogglePlatform.textContent = platformBoxCollapsed ? 'Show' : 'Hide';

    // Filter gig earnings for current month & year
    const gigs = state.deliveryEarnings.filter(g => {
        const dateObj = new Date(g.date + 'T00:00:00');
        const mShort = MONTH_ORDER[dateObj.getMonth()];
        return dateObj.getFullYear() === state.currentYear && mShort === month;
    });

    // Platform Breakdown
    const totals = { cash: 0, sideGigs: 0, grubHub: 0, uberEats: 0, grandTotal: 0 };
    gigs.forEach(g => {
        totals.cash += g.cash || 0;
        totals.sideGigs += g.sideGigs || 0;
        totals.grubHub += g.grubHub || 0;
        totals.uberEats += g.uberEats || 0;
        totals.grandTotal += g.total || 0;
    });

    // Render Bars
    const barsContainer = document.getElementById('platform-bars');
    barsContainer.innerHTML = '';

    const platforms = [
        { key: 'cash', label: 'Cash', value: totals.cash },
        { key: 'sideGigs', label: 'Door Dash', value: totals.sideGigs },
        { key: 'grubHub', label: 'Grub Hub', value: totals.grubHub },
        { key: 'uberEats', label: 'Uber Eats', value: totals.uberEats }
    ];

    const maxVal = Math.max(...platforms.map(p => p.value), 1);

    platforms.forEach(p => {
        const widthPct = (p.value / maxVal) * 100;
        const row = document.createElement('div');
        row.className = 'platform-bar-row';
        row.innerHTML = `
            <span class="platform-label">${p.label}</span>
            <div class="platform-track">
                <div class="platform-fill" style="width: ${widthPct}%"></div>
            </div>
            <span class="platform-value">$${p.value.toFixed(0)}</span>
        `;
        barsContainer.appendChild(row);
    });

    // Group gigs into Mon-Sun weeks dynamically
    const weeks = getDeliveryWeeksForMonth(month);

    // Adjust week index bounds
    if (state.deliveryWeekIndex >= weeks.length) {
        state.deliveryWeekIndex = Math.max(0, weeks.length - 1);
    }
    if (state.deliveryWeekIndex < 0) {
        state.deliveryWeekIndex = 0;
    }

    if (weeks.length === 0) {
        document.getElementById('weekly-totals-list').innerHTML = `<p class="muted-text">No data for this period.</p>`;
        document.getElementById('delivery-log-body').innerHTML = `<tr><td colspan="10" class="muted-text" style="text-align:center;">No logs found.</td></tr>`;
        document.getElementById('delivery-week-label').textContent = 'No week available';
        return;
    }

    const activeWeek = weeks[state.deliveryWeekIndex];

    // Render Weekly Totals list in sidebar
    const weeklyList = document.getElementById('weekly-totals-list');
    weeklyList.innerHTML = '';

    // "Selected" (the week currently being viewed) and "current" (the real calendar week today
    // falls in) are independent — a user browsing past/future weeks shouldn't lose track of where
    // "now" actually is, so both get their own distinct highlight instead of one overloading the other.
    const todayStr = formatLocalDate(new Date());
    weeks.forEach((w, wIdx) => {
        const wSum = w.reduce((sum, g) => sum + g.total, 0);
        const wBudget = w.reduce((sum, g) => sum + (Number(state.deliveryBudgets?.[g.date]) || 0), 0);
        const startStr = new Date(w[0].date+'T00:00:00').toLocaleDateString('en-US', {month:'short', day:'numeric'});
        const endStr = new Date(w[w.length-1].date+'T00:00:00').toLocaleDateString('en-US', {month:'short', day:'numeric'});
        const isCurrentWeek = w.some(g => g.date === todayStr);
        const item = document.createElement('div');
        item.className = `weekly-total-item ${wIdx === state.deliveryWeekIndex ? 'selected-day' : ''} ${isCurrentWeek ? 'current-week' : ''}`;
        item.style.cursor = 'pointer';
        item.innerHTML = `
            <span class="weekly-total-label">Week ${wIdx+1} (${startStr} - ${endStr})</span>
            <span class="weekly-total-val">$${wSum.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} / $${wBudget.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} goal</span>
        `;
        item.addEventListener('click', () => {
            state.deliveryWeekIndex = wIdx;
            renderDeliveryTab();
        });
        weeklyList.appendChild(item);
    });

    // Render grid label
    const startStr = new Date(activeWeek[0].date+'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    const endStr = new Date(activeWeek[activeWeek.length-1].date+'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    document.getElementById('delivery-week-label').textContent = `Week of ${startStr} - ${endStr}`;

    // Render Grid body
    const gridBody = document.getElementById('delivery-log-body');
    gridBody.innerHTML = '';
    const todayDateStr = formatLocalDate(new Date());

    activeWeek.forEach(gRecord => {
        const row = document.createElement('tr');
        const rowClasses = [];
        if (gRecord.offDayReason) rowClasses.push('off-day-row');
        if (gRecord.date === todayDateStr) rowClasses.push('today-row');
        row.className = rowClasses.join(' ');
        const dailyBudget = Number(state.deliveryBudgets?.[gRecord.date]) || 0;
        const difference = gRecord.total - dailyBudget;
        let diffClass = '';
        let diffText = '—';
        if (dailyBudget > 0) {
            if (difference > 0) {
                diffClass = 'positive';
                diffText = `+$${difference.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
            } else if (difference < 0) {
                diffClass = 'negative';
                diffText = `-$${Math.abs(difference).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
            } else {
                diffClass = '';
                diffText = '$0.00';
            }
        }

        let colsHtml = '';
        if (gRecord.offDayReason) {
            colsHtml = `
                <td colspan="4" class="off-day-overlay-cell">🚫 Off-Day: ${escapeHTML(gRecord.offDayReason)}</td>
                <td class="font-heading" style="font-weight:600; text-align:right;">$0.00</td>
            `;
        } else {
            const formatVal = (k) => {
                const val = gRecord[k];
                return val ? `$${val.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}` : '$0.00';
            };
            // Always readonly now (not just on mobile) — every platform amount is entered/edited
            // through the gig-entry-dialog popup (individual timestamped entries, summed together)
            // instead of typing a formula directly into the cell. It must stay enabled (just
            // visually greyed for a no-earnings day) so a click still opens the dialog; otherwise a disabled field
            // can't be clicked at all and there's no way back into the modal to un-check "no earnings".
            // Desktop edits the field directly, so disabling it there to block typing is correct.
            const noEarnAttrs = isTouchDevice() ? 'style="opacity:0.5;"' : 'disabled style="opacity:0.5;"';
            colsHtml = `
                <td class="col-cash">
                    <div class="gig-cell-content">
                        <textarea class="gig-input" rows="1" data-date="${gRecord.date}" data-key="cash" data-label="Cash" placeholder="$0.00" readonly ${gRecord.noEarnCash ? noEarnAttrs : ''}>${formatVal('cash')}</textarea>
                        <input type="checkbox" class="gig-no-earn" tabindex="-1" data-date="${gRecord.date}" data-key="cash" ${gRecord.noEarnCash ? 'checked' : ''} title="No earnings">
                    </div>
                </td>
                <td class="col-doordash">
                    <div class="gig-cell-content">
                        <textarea class="gig-input" rows="1" data-date="${gRecord.date}" data-key="sideGigs" data-label="Door Dash" placeholder="$0.00" readonly ${gRecord.noEarnSideGigs ? noEarnAttrs : ''}>${formatVal('sideGigs')}</textarea>
                        <input type="checkbox" class="gig-no-earn" tabindex="-1" data-date="${gRecord.date}" data-key="sideGigs" ${gRecord.noEarnSideGigs ? 'checked' : ''} title="No earnings">
                    </div>
                </td>
                <td class="col-grubhub">
                    <div class="gig-cell-content">
                        <textarea class="gig-input" rows="1" data-date="${gRecord.date}" data-key="grubHub" data-label="Grub Hub" placeholder="$0.00" readonly ${gRecord.noEarnGrubHub ? noEarnAttrs : ''}>${formatVal('grubHub')}</textarea>
                        <input type="checkbox" class="gig-no-earn" tabindex="-1" data-date="${gRecord.date}" data-key="grubHub" ${gRecord.noEarnGrubHub ? 'checked' : ''} title="No earnings">
                    </div>
                </td>
                <td class="col-ubereats">
                    <div class="gig-cell-content">
                        <textarea class="gig-input" rows="1" data-date="${gRecord.date}" data-key="uberEats" data-label="Uber Eats" placeholder="$0.00" readonly ${gRecord.noEarnUberEats ? noEarnAttrs : ''}>${formatVal('uberEats')}</textarea>
                        <input type="checkbox" class="gig-no-earn" tabindex="-1" data-date="${gRecord.date}" data-key="uberEats" ${gRecord.noEarnUberEats ? 'checked' : ''} title="No earnings">
                    </div>
                </td>
                <td class="font-heading" style="font-weight:600; text-align:right;">$${gRecord.total.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
            `;
        }

        const storedBudget = Number(state.deliveryBudgets?.[gRecord.date]) || 0;
        // Mobile shows the date as MM/DD only — the year column is cropped out entirely (see the
        // 900px media query) and a single week never spans more than one year anyway, so it's just
        // clutter on an already-narrow row. Desktop keeps the full MM/DD/YY from formatDateDisplay.
        const dateLabel = isMobileViewport() ? formatDateDisplay(gRecord.date).replace(/\/\d{2}$/, '') : formatDateDisplay(gRecord.date);
        row.innerHTML = `
            <td>
                <div style="display:flex; align-items:center;">
                    <input type="checkbox" class="day-off-toggle" tabindex="-1" data-date="${gRecord.date}" ${gRecord.offDayReason ? 'checked' : ''} title="Mark as Off-Day (Strike through entire day)">
                    <strong>${dateLabel}</strong>
                </div>
            </td>
            <td><span class="card-icon info" style="font-size:0.75rem; padding: 2px 6px;">${gRecord.day}</span></td>
            ${colsHtml}
            <td>
                <input type="text" class="gig-budget-input" tabindex="-1" data-date="${gRecord.date}" value="${storedBudget > 0 ? storedBudget : ''}" placeholder="—">
            </td>
            <td class="${diffClass} font-heading" style="text-align:right;">${diffText}</td>
            <td>
                <input type="text" class="gig-off-day-input" tabindex="-1" data-date="${gRecord.date}" value="${escapeHTML(gRecord.offDayReason || '')}" placeholder="e.g. Vacation">
            </td>
        `;

        // 0. Drag-and-drop: drag a day's date onto another day to move its earnings there
        const dateHandle = row.querySelector('td:first-child strong');
        if (dateHandle) {
            dateHandle.draggable = true;
            dateHandle.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', gRecord.date);
                row.classList.add('gig-row-dragging');
            });
            dateHandle.addEventListener('dragend', () => {
                row.classList.remove('gig-row-dragging');
            });
        }

        row.addEventListener('dragover', (e) => {
            e.preventDefault();
        });

        row.addEventListener('dragenter', (e) => {
            e.preventDefault();
            row.classList.add('gig-row-drag-hover');
        });

        row.addEventListener('dragleave', () => {
            row.classList.remove('gig-row-drag-hover');
        });

        row.addEventListener('drop', (e) => {
            e.preventDefault();
            row.classList.remove('gig-row-drag-hover');
            const sourceDate = e.dataTransfer.getData('text/plain');
            if (sourceDate && sourceDate !== gRecord.date) {
                mergeDeliveryEarningsIntoDay(sourceDate, gRecord.date);
            }
        });

        // Mobile: the per-platform columns are hidden entirely (see the 900px media query), so
        // tapping anywhere on the row that isn't an input/checkbox opens the platform picker
        // (openGigPlatformPicker) instead — the row's own replacement for "click a cell to log
        // earnings." Excludes the day-off checkbox and Budget field so their own normal behavior
        // (toggle / type a number) still works untouched.
        row.addEventListener('click', (e) => {
            if (!isMobileViewport()) return;
            if (e.target.closest('input, .off-day-overlay-cell')) return;
            openGigPlatformPicker(gRecord.date);
        });

        // 1. Gig input listeners — always readonly now; every cell just opens the multi-entry popup
        // (openGigEntryDialog) rather than being typed into directly. Tab/Shift+Tab still move focus
        // between cells for keyboard users, just without anything to compare/save on the way past.
        row.querySelectorAll('.gig-input').forEach(input => {
            const key = input.dataset.key;
            const openIfEnabled = () => {
                if (!input.disabled) openGigEntryDialog(gRecord.date, key, input.dataset.label);
            };

            input.addEventListener('click', openIfEnabled);

            // iOS Safari doesn't reliably fire `click` on the first tap of a readonly (not disabled)
            // text field — it treats that tap as a text-selection gesture first, so opening the
            // dialog took two taps. The wrapper div has no such quirk, so let taps pass through to
            // it via CSS (pointer-events) and handle the open here instead.
            const wrapper = input.closest('.gig-cell-content');
            if (wrapper) wrapper.addEventListener('click', openIfEnabled);

            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    openIfEnabled();
                } else if (e.key === 'Tab') {
                    const keysOrder = ['cash', 'sideGigs', 'grubHub', 'uberEats'];
                    const currentIdx = keysOrder.indexOf(key);
                    let nextDate = null;
                    let nextKey = null;

                    if (e.shiftKey) {
                        // Shift+Tab: Go backward
                        if (currentIdx > 0) {
                            nextDate = gRecord.date;
                            nextKey = keysOrder[currentIdx - 1];
                        } else {
                            const dayIdx = activeWeek.findIndex(d => d.date === gRecord.date);
                            if (dayIdx > 0) {
                                nextDate = activeWeek[dayIdx - 1].date;
                                nextKey = keysOrder[3];
                            }
                        }
                    } else {
                        // Tab: Go forward
                        if (currentIdx < 3) {
                            nextDate = gRecord.date;
                            nextKey = keysOrder[currentIdx + 1];
                        } else {
                            const dayIdx = activeWeek.findIndex(d => d.date === gRecord.date);
                            if (dayIdx >= 0 && dayIdx < activeWeek.length - 1) {
                                nextDate = activeWeek[dayIdx + 1].date;
                                nextKey = keysOrder[0];
                            }
                        }
                    }

                    if (nextDate && nextKey) {
                        e.preventDefault();
                        const targetInput = document.querySelector(`textarea.gig-input[data-date="${nextDate}"][data-key="${nextKey}"]`);
                        if (targetInput) targetInput.focus();
                    }
                }
            });
        });

        // 2. Checkbox change listener
        row.querySelectorAll('.gig-no-earn').forEach(cb => {
            cb.addEventListener('change', (e) => {
                const date = e.target.dataset.date;
                const key = e.target.dataset.key;
                const checked = e.target.checked;

                const rec = state.deliveryEarnings.find(item => item.date === date);
                if (rec) {
                    const capKey = key.charAt(0).toUpperCase() + key.slice(1);
                    rec['noEarn' + capKey] = checked;
                    if (checked) {
                        rec[key + 'Entries'] = [];
                    }
                    recalcGigEntryTotal(rec, key);
                    logSystem(`Delivery Earnings updated for ${date} — ${key} ${checked ? 'marked No Earnings' : 'No Earnings cleared'}.`);
                    saveDatabase();
                    renderApp();
                }
            });
        });

        // 3. Budget input listener
        const budgetInput = row.querySelector('.gig-budget-input');
        if (budgetInput) {
            budgetInput.addEventListener('change', (e) => {
                const date = e.target.dataset.date;
                const parsedVal = parseFormula(e.target.value);

                state.deliveryBudgets = state.deliveryBudgets || {};
                if (parsedVal > 0) {
                    state.deliveryBudgets[date] = parsedVal;
                    logSystem(`Delivery Earnings updated for ${date} — Budget: $${parsedVal.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}.`);
                } else {
                    delete state.deliveryBudgets[date];
                    logSystem(`Delivery Earnings updated for ${date} — Budget cleared.`);
                }
                saveDatabase();
                renderApp();
            });
        }

        // 4. Off-Day Reason listener
        const offDayInput = row.querySelector('.gig-off-day-input');
        if (offDayInput) {
            offDayInput.addEventListener('change', (e) => {
                const date = e.target.dataset.date;
                const val = e.target.value.trim();

                const rec = state.deliveryEarnings.find(item => item.date === date);
                if (rec) {
                    rec.offDayReason = val;
                    if (val) {
                        // Clear actual earnings and no-earn checkboxes
                        rec.cash = 0;
                        rec.sideGigs = 0;
                        rec.grubHub = 0;
                        rec.uberEats = 0;
                        rec.total = 0;
                        rec.noEarnCash = false;
                        rec.noEarnSideGigs = false;
                        rec.noEarnGrubHub = false;
                        rec.noEarnUberEats = false;
                        if (state.deliveryBudgets) {
                            delete state.deliveryBudgets[date];
                        }
                    }
                    saveDatabase();
                    renderApp();
                }
            });
        }

        // 5. Day Off Toggle Checkbox
        const dayOffToggle = row.querySelector('.day-off-toggle');
        if (dayOffToggle) {
            dayOffToggle.addEventListener('change', (e) => {
                const date = e.target.dataset.date;
                const checked = e.target.checked;

                const rec = state.deliveryEarnings.find(item => item.date === date);
                if (rec) {
                    if (checked) {
                        rec.offDayReason = rec.offDayReason || 'Off-Day';
                        // Clear actual earnings and no-earn checkboxes
                        rec.cash = 0;
                        rec.cashFormula = '';
                        rec.sideGigs = 0;
                        rec.sideGigsFormula = '';
                        rec.grubHub = 0;
                        rec.grubHubFormula = '';
                        rec.uberEats = 0;
                        rec.uberEatsFormula = '';
                        rec.total = 0;
                        rec.noEarnCash = false;
                        rec.noEarnSideGigs = false;
                        rec.noEarnGrubHub = false;
                        rec.noEarnUberEats = false;
                        if (state.deliveryBudgets) {
                            delete state.deliveryBudgets[date];
                        }
                    } else {
                        rec.offDayReason = '';
                    }
                    logSystem(`Delivery Earnings updated for ${date} — ${checked ? 'marked Off-Day' : 'Off-Day cleared'}.`);
                    saveDatabase();
                    renderApp();
                }
            });
        }

        gridBody.appendChild(row);
    });

    syncDeliveryColumnToggles();
    renderDeliveryYearSummary();
    _updateDeliveryStickyOffsets();

    // Restore focus if a tab navigation was queued
    if (state.nextFocusDate && state.nextFocusKey) {
        const targetInput = document.querySelector(`textarea.gig-input[data-date="${state.nextFocusDate}"][data-key="${state.nextFocusKey}"]`);
        if (targetInput) {
            targetInput.focus();
            targetInput.select();
        }
        state.nextFocusDate = null;
        state.nextFocusKey = null;
    }
}

function getWeeksGroupedByMonth(year) {
    // Scan Dec 1 of previous year to Jan 31 of next year to cover boundaries
    const start = new Date(year - 1, 11, 1);
    const day = start.getDay();
    const diffToMonday = day === 0 ? -6 : 1 - day;
    const currentMonday = new Date(start);
    currentMonday.setDate(start.getDate() + diffToMonday);

    const end = new Date(year + 1, 0, 31);

    const grouped = {};
    MONTH_ORDER.forEach(m => grouped[m] = []);

    let safetyCounter = 0;
    while (currentMonday < end && safetyCounter < 100) {
        safetyCounter++;
        const week = [];
        for (let i = 0; i < 7; i++) {
            const date = new Date(currentMonday);
            date.setDate(currentMonday.getDate() + i);
            week.push(ensureDeliveryEarningForDate(date));
        }

        // Count days in each year-month
        const monthCounts = {};
        week.forEach(gRecord => {
            const dateObj = new Date(gRecord.date + 'T00:00:00');
            const dYear = dateObj.getFullYear();
            const dMonth = MONTH_ORDER[dateObj.getMonth()];
            const key = `${dYear}-${dMonth}`;
            monthCounts[key] = (monthCounts[key] || 0) + 1;
        });

        // Find majority year-month
        let maxKey = null;
        let maxCount = -1;
        for (const [k, count] of Object.entries(monthCounts)) {
            if (count > maxCount) {
                maxCount = count;
                maxKey = k;
            }
        }

        if (maxKey) {
            const [kYear, kMonth] = maxKey.split('-');
            if (parseInt(kYear) === year) {
                grouped[kMonth].push(week);
            }
        }

        currentMonday.setDate(currentMonday.getDate() + 7);
    }

    return grouped;
}

// Group delivery earnings into Mon-Sun weeks for a specific month using majority rule
function getDeliveryWeeksForMonth(month) {
    const grouped = getWeeksGroupedByMonth(state.currentYear);
    state.deliveryEarnings.sort((a, b) => a.date.localeCompare(b.date));
    return grouped[month] || [];
}

