function getDebtLogoIcon(key, label) {
    const src = DEBT_ACCOUNT_LOGOS[key];
    return {
        glyph: `<img class="debt-account-logo" src="${src}" alt="${label} logo">`,
        label,
        image: true,
    };
}
// Shared by every "upload a custom account icon" field (loan-dialog, and the new Personal/Joint/
// Savings Account Settings dialogs) — reads an <input type="file"> selection into a data URL via
// FileReader, with a type/size guard, and hands the result to `callback`. Kept small (1.5MB) since
// this ends up embedded directly in state (and therefore the Google Drive JSON/localStorage) like
// the built-in DEBT_ACCOUNT_LOGOS images already are, not stored as a separate file. Per explicit
// user request, 2026-08-05 ("is there a way to upload images to use for account icons?").
function readImageFileAsDataUrl(file, callback) {
    if (!file) return;
    if (!file.type || !file.type.startsWith('image/')) {
        alert('Please choose an image file.');
        return;
    }
    const MAX_BYTES = 1.5 * 1024 * 1024;
    if (file.size > MAX_BYTES) {
        alert('That image is too large (max 1.5MB). Please choose a smaller image, or resize/compress it first.');
        return;
    }
    const reader = new FileReader();
    reader.onload = () => callback(reader.result);
    reader.onerror = () => alert('Failed to read that image file.');
    reader.readAsDataURL(file);
}

// A user-uploaded icon always wins over the auto-matched logo/emoji below — per explicit user
// request, 2026-08-05. Same `{glyph, label, image: true}` shape getDebtLogoIcon() returns, so
// every consumer of this function (renderDebtAccountIconBadge, etc.) doesn't need to know the
// difference between a built-in logo and a custom one.
function getCustomAccountIcon(dataUrl, label) {
    if (!dataUrl) return null;
    return {
        glyph: `<img class="debt-account-logo" src="${dataUrl}" alt="${escapeHTML(label)} icon">`,
        label,
        image: true
    };
}

function getDebtAccountIcon(account) {
    const custom = getCustomAccountIcon(account?.customIconDataUrl, account?.name || 'Account');
    if (custom) return custom;
    const text = `${account?.name || ''} ${account?.storeName || ''}`.toLowerCase();
    const logoMappings = [
        [/(american express|amex)/, 'amex', 'American Express'],
        // Disney+ (the streaming subscription bill) needs to win over the generic "disney" store-card
        // match below it, since both patterns would otherwise match the same "Disney+" bill name.
        [/(disney\+|disney plus)/, 'disneyPlus', 'Disney+'],
        [/disney/, 'disney', 'Disney'],
        [/(southwest|rapid rewards)/, 'southwest', 'Southwest Airlines'],
        [/(american airlines|aadvantage)/, 'americanAirlines', 'American Airlines'],
        [/comerica/, 'comerica', 'Comerica'],
        [/paypal/, 'paypal', 'PayPal'],
        [/wells fargo/, 'wellsFargo', 'Wells Fargo'],
        [/\bsofi\b/, 'sofi', 'SoFi'],
        [/(target|bullseye)/, 'target', 'Target'],
        [/amazon/, 'amazon', 'Amazon'],
        [/discover/, 'discover', 'Discover'],
        [/best buy/, 'bestBuy', 'Best Buy'],
        [/upstart/, 'upstart', 'Upstart'],
        [/(greensky|green sky)/, 'greensky', 'GreenSky'],
        [/lightstream/, 'lightstream', 'LightStream'],
        [/round\s*point/, 'roundpoint', 'RoundPoint'],
        [/federal student/, 'federalStudentLoans', 'Federal Student Loans'],
        [/service finance/, 'serviceFinance', 'Service Finance'],
        [/apple fitness/, 'appleFitness', 'Apple Fitness+'],
        [/apple tv/, 'appleTV', 'Apple TV+'],
        [/icloud/, 'icloud', 'iCloud'],
        [/at&t/, 'att', 'AT&T'],
        [/atmos/, 'atmosEnergy', 'Atmos Energy'],
        [/\bfetch\b/, 'fetchPetInsurance', 'Fetch Pet Insurance'],
        [/\bhp\b/, 'hpInk', 'HP'],
        [/\birs\b/, 'irs', 'IRS'],
        [/moxie/, 'moxie', 'Moxie Pest Control'],
        [/netflix/, 'netflix', 'Netflix'],
        [/one\s*guard/, 'oneGuard', 'OneGuard'],
        [/reliant/, 'reliantEnergy', 'Reliant Energy'],
        [/richardson/, 'richardsonWater', 'Richardson Water'],
        [/\bring\b/, 'ring', 'Ring'],
        [/spotify/, 'spotify', 'Spotify'],
        [/\busaa\b/, 'usaa', 'USAA'],
        [/\bcash\b/, 'cashApp', 'Cash'],
        [/groceries/, 'groceries', 'Groceries'],
        [/cat food/, 'catFood', 'Cat Food'],
        [/\broberto\b/, 'lawnMower', 'Lawn Care'],
    ];
    const logoMatch = logoMappings.find(([pattern]) => pattern.test(text));
    if (logoMatch) return getDebtLogoIcon(logoMatch[1], logoMatch[2]);
    const mappings = [
        [/(american express|amex)/, '🛡️', 'American Express Centurion'],
        [/\bsofi\b/, '💠', 'SoFi'],
        [/\bciti\b/, '🏙️', 'Citi'],
        [/\bchase\b/, '🔷', 'Chase'],
        [/capital one/, '1️⃣', 'Capital One'],
        [/wells fargo/, '🐎', 'Wells Fargo'],
        [/bank of america/, '🇺🇸', 'Bank of America'],
        [/\bapple\b/, '🍎', 'Apple'],
        [/home depot/, '🛠️', 'Home Depot'],
        [/\blowe'?s\b/, '🔨', 'Lowe’s'],
        [/synchrony/, '🔄', 'Synchrony'],
        [/paypal/, '🅿️', 'PayPal'],
        [/(student|federal)/, '🎓', 'Student Loan'],
        [/\btexas\b/, '⭐', 'Texas'],
        [/(bath|plumb)/, '🛁', 'Home Improvement'],
        [/(auto|vehicle|car loan)/, '🚗', 'Auto Loan'],
        [/(mortgage|home loan)/, '🏠', 'Mortgage'],
    ];
    const match = mappings.find(([pattern]) => pattern.test(text));
    if (match) return { glyph: match[1], label: match[2] };
    return account?.type === 'loan'
        ? getDebtLogoIcon('loanGeneric', 'Installment Loan')
        : { glyph: '💳', label: 'Credit Card' };
}

function getDebtAccountLoginUrl(account) {
    const raw = String(account?.loginUrl || '').trim();
    if (!raw) return '';
    try {
        const parsed = new URL(/^https?:\/\//i.test(raw) ? raw : `https://${raw}`);
        return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : '';
    } catch {
        return '';
    }
}

// Renders an account/bill's icon badge as a click target for its saved login URL — used everywhere
// an account icon appears (Bill Tracker, Loans, Credit Cards) instead of a separate "Account Login"
// text link. Clicking opens the site in a new tab; with no saved URL it pops an alert instead, via
// the single delegated listener registered below (setupDebtAccountIconLoginHandler).
function renderDebtAccountIconBadge(account, icon, extraClass = '') {
    const href = getDebtAccountLoginUrl(account);
    const classes = `debt-account-icon${icon.image ? ' has-logo' : ''}${extraClass ? ' ' + extraClass : ''} account-icon-clickable`;
    const title = href ? `Open ${account.name || 'account'} website` : icon.label;
    return `<span class="${classes}" data-login-url="${escapeHTML(href)}" data-account-name="${escapeHTML(account.name || 'this account')}" title="${escapeHTML(title)}" role="button" tabindex="0">${icon.glyph}</span>`;
}

// One delegated listener for every account-icon badge on the page, rather than wiring a click
// handler at each of the several places (Bill Tracker cards/list, Loans, Credit Cards) that render
// one — those cards/rows get torn down and rebuilt on every render, so a per-element listener would
// have to be re-attached every time anyway.
function setupDebtAccountIconLoginHandler() {
    document.addEventListener('click', (e) => {
        const badge = e.target.closest('.account-icon-clickable');
        if (!badge) return;
        const url = badge.dataset.loginUrl;
        if (url) {
            window.open(url, '_blank', 'noopener,noreferrer');
        } else {
            alert(`No account website saved for ${badge.dataset.accountName || 'this account'}.`);
        }
    });
    // Keyboard activation (Enter/Space) for the same badges, since they're focusable via tabindex.
    document.addEventListener('keydown', (e) => {
        if (e.key !== 'Enter' && e.key !== ' ') return;
        const badge = e.target.closest('.account-icon-clickable');
        if (!badge) return;
        e.preventDefault();
        badge.click();
    });
}

function findDebtLedgerEntry(accountId, entryId) {
    const calendar = state.cardCalendars?.[accountId] || {};
    for (const [key, list] of Object.entries(calendar)) {
        const index = (list || []).findIndex(item => item.id === entryId);
        if (index >= 0) return { key, list, index, entry: list[index] };
    }
    return null;
}

function getDebtDefaultEntryDate(account, dayValue) {
    const today = new Date();
    const year = Number(state.ccYear) || today.getFullYear();
    const monthIndex = Math.max(0, MONTH_ORDER.indexOf(state.ccMonth));
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    const day = Math.min(daysInMonth, Math.max(1, Number(dayValue) || 1));
    return `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function openDebtBalanceAdjustment(accountId, entryId = '') {
    const account = state.loans.find(item => item.id === accountId);
    if (!account) return;
    const existing = entryId ? findDebtLedgerEntry(accountId, entryId)?.entry : null;
    const dateStr = existing?.date || getDebtDefaultEntryDate(account, account.statementDay);
    if (!existing) {
        const date = new Date(dateStr + 'T00:00:00');
        rebuildDebtMonthFinance(account.id, date.getFullYear(), MONTH_ORDER[date.getMonth()]);
    }
    document.getElementById('debt-balance-adjust-title').textContent = existing ? `Edit ${account.name} Balance Adjustment` : `Adjust ${account.name} Balance`;
    document.getElementById('debt-balance-adjust-account-id').value = account.id;
    document.getElementById('debt-balance-adjust-entry-id').value = existing?.id || '';
    document.getElementById('debt-balance-adjust-date').value = dateStr;
    document.getElementById('debt-balance-adjust-amount').value = Number.isFinite(Number(existing?.statementBalanceTarget))
        ? Number(existing.statementBalanceTarget).toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})
        : Math.max(0, calculateCardLedgerBalance(account.id, dateStr)).toFixed(2);
    document.getElementById('debt-balance-adjust-dialog').showModal();
}

// Recomputes the "Payment Covers" split hint text live as the user edits the amount or toggles
// between Additional P&I Only / Full Mortgage Payment, so they can see exactly how much of what
// they typed will actually reduce the loan balance vs. just pass through to escrow.
function updateLoanExtraPaymentSplitHint() {
    const hint = document.getElementById('loan-extra-payment-split-hint');
    if (!hint) return;
    const accountId = document.getElementById('loan-extra-payment-account-id').value;
    const loan = state.loans.find(item => item.id === accountId && item.type === 'loan');
    const paymentType = document.getElementById('loan-extra-payment-type').value;
    const requestedAmount = Number(document.getElementById('loan-extra-payment-amount').value) || 0;
    if (!loan?.isMortgage || paymentType !== 'full') {
        hint.textContent = '';
        return;
    }
    const escrowAmount = Math.max(0, Number(loan.escrowAmount) || 0);
    const piPortion = Math.max(0, requestedAmount - escrowAmount);
    hint.textContent = `$${escrowAmount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} to escrow (not applied to principal) + $${piPortion.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} reduces the loan balance.`;
}

function openLoanExtraPayment(accountId, entryId = '') {
    const loan = state.loans.find(item => item.id === accountId && item.type === 'loan');
    if (!loan) return;
    const existing = entryId ? findDebtLedgerEntry(accountId, entryId)?.entry : null;
    document.getElementById('loan-extra-payment-title').textContent = existing ? `Edit Extra Payment - ${loan.name}` : `Post Extra Payment - ${loan.name}`;
    document.getElementById('loan-extra-payment-account-id').value = accountId;
    document.getElementById('loan-extra-payment-entry-id').value = existing?.id || '';
    document.getElementById('loan-extra-payment-date').value = existing?.date || getDebtDefaultEntryDate(loan, loan.dueDay);
    document.getElementById('loan-extra-payment-description').value = existing?.description || 'Extra Loan Payment';
    // For a "Full Mortgage Payment" entry, the amount the user originally typed (escrow + P&I) is
    // bigger than what actually posted to the loan ledger (existing.amount, P&I only) — re-show the
    // original full figure on edit rather than the smaller loan-side-only amount.
    document.getElementById('loan-extra-payment-amount').value = existing
        ? Math.abs(Number(existing.originalRequestedAmount ?? existing.amount) || 0).toFixed(2)
        : '';
    document.getElementById('loan-extra-payment-source').value = existing?.owner || loan.paymentSource || 'jason';

    const typeGroup = document.getElementById('loan-extra-payment-type-group');
    const typeSelect = document.getElementById('loan-extra-payment-type');
    typeGroup.classList.toggle('hidden', !loan.isMortgage);
    typeSelect.value = existing?.mortgagePaymentType || 'pi';
    updateLoanExtraPaymentSplitHint();

    document.getElementById('loan-extra-payment-dialog').showModal();
}

function deleteEditableDebtEntry(accountId, entryId) {
    const found = findDebtLedgerEntry(accountId, entryId);
    if (!found) return;
    const label = found.entry.isBalanceAdjustment ? 'balance adjustment'
        : (found.entry.isLoanEstimatedInterest ? 'interest entry'
            : (found.entry.isAutomaticCardPayment ? 'automatic monthly payment' : 'extra payment'));
    if (!found.entry.isAutomaticCardPayment && !confirm(`Delete this ${label} dated ${formatDateDisplay(found.entry.date)}?`)) return;
    // Already confirmed above (for the non-automatic case) — skip the redundant generic prompt.
    const removed = deleteCardTransactionWithRecurringChoice(accountId, found.key, entryId, true);
    if (!removed) return;
    const account = state.loans.find(item => item.id === accountId);
    if (account) account.currentBal = calculateCardLedgerBalance(accountId);
    saveDatabase();
    renderCardDashboard(accountId);
    logSystem(`Deleted ${label}: ${found.entry.description}`);
}

// These three used to be plain module-level objects — never part of `state`, so they reset on
// every reload and never made it into a Sheets push no matter how "Auto Sync" was configured.
// Real state fields now, with lazy defaults here (rather than in _createBlankState()) so existing
// saved databases from before this change don't need a migration step.
function getDebtOverviewSort() { return state.debtOverviewSort || (state.debtOverviewSort = { loan: 'name', credit: 'name' }); }
function getDebtOverviewHideZero() { return state.debtOverviewHideZero || (state.debtOverviewHideZero = { loan: false, credit: false }); }
function getDebtSummaryCollapsed() { return state.debtSummaryCollapsed || (state.debtSummaryCollapsed = { loan: false, credit: false }); }

function applyDebtSummaryCollapsedState(type) {
    const content = document.getElementById(type === 'loan' ? 'loan-summary-content' : 'credit-summary-content');
    const button = document.getElementById(type === 'loan' ? 'btn-toggle-loan-summary' : 'btn-toggle-credit-summary');
    const collapsed = !!getDebtSummaryCollapsed()[type];
    content?.classList.toggle('hidden', collapsed);
    if (button) {
        button.textContent = collapsed ? 'Show' : 'Hide';
        button.setAttribute('aria-expanded', String(!collapsed));
    }
}

// Small pill badges for whatever's easy to miss once a card's settings are collapsed: an active
// purchase promo rate, an annual fee, open payment plans, or an active balance transfer. Shown on
// the Loans/Credit Cards overview list (both the card grid and table row) so this is visible
// without opening the settings dialog at all.
function getCardStatusBadges(account) {
    if (account.type !== 'credit') return '';
    const todayStr = formatLocalDate(new Date());
    const badges = [];
    if (account.promoActive && account.promoExpDate && account.promoExpDate >= todayStr) {
        badges.push('<span class="debt-status-badge promo">Promo Rate</span>');
    }
    if (account.hasAnnualFee && Number(account.annualFeeAmount) > 0) {
        badges.push('<span class="debt-status-badge fee">Annual Fee</span>');
    }
    const activePlans = deriveCardPaymentPlanBalances(account.id, todayStr).filter(p => p.currentBalance > 0.005);
    if (activePlans.length > 0) {
        badges.push(`<span class="debt-status-badge plans">${activePlans.length} Payment Plan${activePlans.length > 1 ? 's' : ''}</span>`);
    }
    const activeTransfers = (account.promos || []).filter(p => p.isXfer && (!p.expDate || p.expDate >= todayStr));
    if (activeTransfers.length > 0) {
        badges.push(`<span class="debt-status-badge transfer">${activeTransfers.length} Balance Transfer${activeTransfers.length > 1 ? 's' : ''}</span>`);
    }
    return badges.join('');
}

function renderDebtOverview(type, listContainerId, tableBodyId) {
    // Definitive fix: Always clear column filters for debt summary tables so cards/loans are never hidden by stale filter state
    const tableKey = type === 'loan' ? 'loanSummary' : 'creditSummary';
    Object.keys(columnFilterState || {}).forEach(k => {
        if (k.startsWith(tableKey + ':')) delete columnFilterState[k];
    });
    if (state && state.columnFilterState) {
        Object.keys(state.columnFilterState).forEach(k => {
            if (k.startsWith(tableKey + ':')) delete state.columnFilterState[k];
        });
    }
    const listContainer = document.getElementById(listContainerId);
    const tableBody = document.getElementById(tableBodyId);
    if (listContainer) listContainer.innerHTML = '';
    if (tableBody) tableBody.innerHTML = '';
    applyDebtSummaryCollapsedState(type);

    const isLoanType = type === 'loan';
    let accounts = state.loans.filter(item => item.type === type);
    if (getDebtOverviewHideZero()[type]) accounts = accounts.filter(account => Math.abs(calculateCardLedgerBalance(account.id)) > 0.005);
    const ownershipFilter = state.debtOwnershipFilter || 'all';
    document.querySelectorAll(`#debt-ownership-filter-${type} .segment-btn`).forEach(btn => {
        btn.classList.toggle('active', btn.dataset.debtOwnership === ownershipFilter);
    });
    if (ownershipFilter !== 'all') {
        accounts = accounts.filter(account => {
            const owner = account.paymentSource === 'joint' ? 'joint' : account.paymentSource === 'asia' ? 'asia' : 'jason';
            return owner === ownershipFilter;
        });
    }
    // Column-click sort (headers in the table view) takes priority over the dropdown when set —
    // clicking a header sets state.debtSummarySort[type]; the dropdown's own change handler clears
    // it so the two don't fight over which one "wins".
    if (!state.debtSummarySort) state.debtSummarySort = {};
    const columnSort = state.debtSummarySort[type];
    if (columnSort && columnSort.key) {
        const columnSortValue = (account) => {
            const balance = calculateCardLedgerBalance(account.id);
            switch (columnSort.key) {
                case 'name': return (account.name || '').toLowerCase();
                case 'startingBalance': return Number(account.startBal) || 0;
                case 'currentBalance': return balance;
                case 'paidToDate': return Math.max(0, (Number(account.startBal) || 0) - Math.max(0, balance));
                default: return '';
            }
        };
        accounts.sort((a, b) => {
            const valA = columnSortValue(a);
            const valB = columnSortValue(b);
            const cmp = typeof valA === 'number' ? valA - valB : String(valA).localeCompare(String(valB), undefined, { numeric: true });
            return columnSort.direction === 'asc' ? cmp : -cmp;
        });
    } else {
        const sortMode = getDebtOverviewSort()[type] || 'name';
        accounts.sort((a, b) => {
            if (sortMode === 'balance-desc') return calculateCardLedgerBalance(b.id) - calculateCardLedgerBalance(a.id);
            if (sortMode === 'balance-asc') return calculateCardLedgerBalance(a.id) - calculateCardLedgerBalance(b.id);
            return String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' });
        });
    }

    if (!accounts.length) {
        if (listContainer) listContainer.innerHTML = '<p class="muted-text debt-summary-empty">No accounts match the current summary filters.</p>';
        if (tableBody) tableBody.innerHTML = '<tr><td colspan="7" class="muted-text" style="text-align:center;">No accounts match the current summary filters.</td></tr>';
        return;
    }

    accounts.forEach(account => {
        const balance = calculateCardLedgerBalance(account.id);
        account.currentBal = balance;
        const startingBalance = Number(account.startBal) || 0;
        const paidToDate = Math.max(0, startingBalance - Math.max(0, balance));
        const payoffProjection = projectCardPayoffPath(account.id, 0, formatLocalDate(new Date()), 0, 0, false, 600);
        const payoffDate = payoffProjection.payoffDate || 'Payment too low';
        const icon = getDebtAccountIcon(account);
        const storeLabel = account.isStoreCard && account.storeName
            ? `<span class="debt-store-badge">Store card · ${escapeHTML(account.storeName)}</span>`
            : '';
        const statusBadgesHtml = [storeLabel, getCardStatusBadges(account)].filter(Boolean).join('');
        const statusBadgesRow = statusBadgesHtml ? `<div class="debt-status-badges">${statusBadgesHtml}</div>` : '';

        let progressPct;
        let progressLabel;
        let gaugeLeft;
        let gaugeRight;
        if (isLoanType) {
            progressPct = startingBalance > 0
                ? Math.min(100, Math.max(0, (paidToDate / startingBalance) * 100))
                : 100;
            progressLabel = `${progressPct.toFixed(0)}% Paid`;
            gaugeLeft = `Paid: ${formatCardBalance(paidToDate)}`;
            gaugeRight = `Original: ${formatCardBalance(startingBalance)}`;
        } else if (account.isChargeCard) {
            progressPct = 0;
            progressLabel = 'Charge Card';
            gaugeLeft = `Balance: ${formatCardBalance(balance)}`;
            gaugeRight = 'No preset limit';
        } else {
            const limit = Math.max(0, Number(account.limit) || 0);
            progressPct = limit > 0 ? Math.min(100, Math.max(0, (Math.max(0, balance) / limit) * 100)) : 0;
            progressLabel = `${progressPct.toFixed(0)}% Used`;
            gaugeLeft = `Used: ${formatCardBalance(balance)}`;
            gaugeRight = `Limit: ${formatCardBalance(limit)}`;
        }

        const card = document.createElement('div');
        card.className = 'glass-card loan-overview-card debt-summary-card';
        card.style.cursor = 'pointer';
        card.addEventListener('click', event => {
            if (event.target.closest('button, a, input, .account-icon-clickable')) return;
            state.ccSelectedCardId = account.id;
            if (isLoanType) renderLoansTab();
            else renderCreditCardsTab();
        });
        card.innerHTML = `
            <div class="loan-card-top">
                <div class="debt-account-heading">
                    ${renderDebtAccountIconBadge(account, icon)}
                    <div class="debt-account-heading-copy">
                        <h3 class="loan-card-title">${escapeHTML(account.name)}</h3>
                        ${statusBadgesRow}
                    </div>
                </div>
                <span class="card-icon info debt-progress-badge">${progressLabel}</span>
            </div>
            <div class="loan-progress-gauge">
                <div class="gauge-track"><div class="gauge-fill" style="width:${progressPct}%"></div></div>
                <div class="gauge-labels"><span>${gaugeLeft}</span><span>${gaugeRight}</span></div>
            </div>
            <div class="debt-overview-metrics">
                <div><span>Starting Balance</span><strong>${formatCardBalance(startingBalance)}</strong></div>
                <div><span>Current Balance</span><strong>${formatCardBalance(balance)}</strong></div>
                <div><span>Paid To Date</span><strong>${formatCardBalance(paidToDate)}</strong></div>
                <div><span>Payoff Date</span><strong>${escapeHTML(payoffDate)}</strong></div>
            </div>
            <div class="debt-card-actions">
                <button class="action-btn small-btn outline-btn edit-loan-card-btn" data-id="${account.id}" title="Account settings" aria-label="Open settings for ${escapeHTML(account.name)}">&#9881;</button>
            </div>`;

        card.querySelector('.edit-loan-card-btn').addEventListener('click', event => {
            event.stopPropagation();
            openEditLoanModal(account.id);
        });
        listContainer?.appendChild(card);

        if (!tableBody) return;
        const row = document.createElement('tr');
        row.style.cursor = 'pointer';
        row.addEventListener('click', event => {
            if (event.target.closest('button, a, input, .account-icon-clickable')) return;
            state.ccSelectedCardId = account.id;
            if (isLoanType) renderLoansTab();
            else renderCreditCardsTab();
        });
        const accountCell = `
            <div class="debt-table-account">
                ${renderDebtAccountIconBadge(account, icon, 'compact')}
                <div><strong>${escapeHTML(account.name)}</strong>${statusBadgesRow}</div>
            </div>`;
        row.innerHTML = `
            <td>${accountCell}</td>
            <td>${formatCardBalance(startingBalance)}</td>
            <td class="${balance < 0 ? 'positive' : 'negative'} font-heading" style="font-weight:600;">${formatCardBalance(balance)}</td>
            <td class="positive">${formatCardBalance(paidToDate)}</td>
            <td><strong>${isLoanType ? `${progressPct.toFixed(0)}%` : (account.isChargeCard ? 'N/A' : `${progressPct.toFixed(0)}%`)}</strong></td>
            <td><strong>${escapeHTML(payoffDate)}</strong></td>
            <td class="table-actions-cell"><div class="debt-table-action-buttons">
                <button class="action-btn small-btn outline-btn edit-loan-btn" data-id="${account.id}" title="Account settings" aria-label="Open settings for ${escapeHTML(account.name)}">&#9881;</button>
                <button class="action-btn small-btn danger-btn delete-loan-btn" data-id="${account.id}">Delete</button>
            </div></td>`;
        row.querySelector('.edit-loan-btn').addEventListener('click', event => {
            event.stopPropagation();
            openEditLoanModal(account.id);
        });
        row.querySelector('.delete-loan-btn').addEventListener('click', event => {
            event.stopPropagation();
            deleteLoanAccount(account);
        });
        tableBody.appendChild(row);
    });

    if (accounts.length === 0 && tableBody) {
        tableBody.innerHTML = `<tr><td colspan="7" class="muted-text" style="text-align:center;">No active ${isLoanType ? 'installment loans' : 'credit cards'}. Use the Add button to create one.</td></tr>`;
    }
    if (tableBody) {
        const tableKey = isLoanType ? 'loanSummary' : 'creditSummary';
        const theadSelector = (isLoanType ? '#loan-summary-content' : '#credit-summary-content') + ' thead';
        setupTableColumnFilters(theadSelector, tableKey, () => tableBody, [6]);
        applyColumnFilters(tableBody, tableKey);
        updateSortIndicators(theadSelector, 'data-debt-summary-sort', columnSort && columnSort.key ? columnSort : { key: null, direction: 'asc' });
    }
}

function renderLoansTab() {
    const selectedLoan = state.loans.find(item => item.id === state.ccSelectedCardId && item.type === 'loan');
    const overviewLayout = document.getElementById('loans-overview-layout');
    const detailLayout = document.getElementById('cc-dashboard-layout');
    if (selectedLoan) {
        placeDebtDashboardLayout('loan');
        overviewLayout?.classList.add('hidden');
        detailLayout?.classList.remove('hidden');
        renderCardDashboard(selectedLoan.id);
        _updateListViewStickyOffset();
        return;
    }
    overviewLayout?.classList.remove('hidden');
    if (detailLayout?.parentElement === document.getElementById('view-loans')) detailLayout.classList.add('hidden');
    renderDebtOverview('loan', 'loans-overview-grid', 'loans-table-body');
}

function renderCreditCardsTab() {
    placeDebtDashboardLayout('credit');
    reconcileCardCurrentBalances();
    const selectedCard = state.loans.find(item => item.id === state.ccSelectedCardId && item.type === 'credit');
    if (selectedCard) {
        document.getElementById('creditcards-overview-layout').classList.add('hidden');
        document.getElementById('cc-dashboard-layout').classList.remove('hidden');
        renderCardDashboard(selectedCard.id);
        _updateListViewStickyOffset();
        updateGlobalTogglesPlacement();
        updateGlobalNavVisibility();
        return;
    }
    document.getElementById('creditcards-overview-layout').classList.remove('hidden');
    document.getElementById('cc-dashboard-layout').classList.add('hidden');
    renderDebtOverview('credit', 'creditcards-overview-grid', 'creditcards-table-body');
    updateGlobalTogglesPlacement();
    updateGlobalNavVisibility();
}

function updateBalanceTransferModeFields() {
    const isExisting = document.getElementById('xfer-mode').value === 'existing';
    document.getElementById('xfer-source-group').classList.toggle('hidden', isExisting);
    document.getElementById('xfer-fee-group').classList.toggle('hidden', isExisting);
    document.getElementById('xfer-current-group').classList.toggle('hidden', !isExisting);
    document.getElementById('xfer-ledger-owner-group').classList.toggle('hidden', isExisting);
    document.getElementById('xfer-description-group').classList.toggle('hidden', isExisting);
    // Only relevant in "New Transfer" mode with "Other / Not Tracked" picked as the source — per
    // explicit user request, 2026-08-05.
    const isExternal = !isExisting && document.getElementById('xfer-source').value === '__external__';
    document.getElementById('xfer-external-source-group').classList.toggle('hidden', !isExternal);
    document.getElementById('xfer-amount-label').textContent = isExisting ? 'Original Transfer Amount' : 'Transfer Amount';
    document.getElementById('btn-execute-xfer').textContent = isExisting ? 'Add Existing Transfer' : 'Execute New Transfer';
    if (!isExisting) updateXferDescriptionPreview();
}

// Tracks the last auto-generated description so a live update (Transferred By/source/external-name
// changing) can tell "still the auto value, safe to overwrite" apart from "the user typed their own
// description, leave it alone" — both look identical once written into the field otherwise.
let xferDescriptionAutoValue = '';
function updateXferDescriptionPreview() {
    const descField = document.getElementById('xfer-description');
    if (!descField || descField.value !== xferDescriptionAutoValue) return;
    const sourceId = document.getElementById('xfer-source').value;
    const isExternal = sourceId === '__external__';
    const sourceCard = isExternal ? null : state.loans.find(l => l.id === sourceId);
    const sourceLabel = isExternal
        ? (document.getElementById('xfer-external-source-name').value.trim() || 'External Account')
        : (sourceCard ? (sourceCard.mobileNickname || sourceCard.name) : '');
    const transferOwnerLabel = document.getElementById('xfer-owner').value === 'asia' ? 'Asia' : 'Jason';
    xferDescriptionAutoValue = sourceLabel ? `Balance Transfer - ${transferOwnerLabel} - ${sourceLabel}` : '';
    descField.value = xferDescriptionAutoValue;
}

function recordExistingBalanceTransfer(targetId, originalAmount, currentBalance, rate, expDate, transferOwner) {
    const targetCard = state.loans.find(card => card.id === targetId);
    if (!targetCard) {
        alert('Save the card before adding an existing balance transfer.');
        return;
    }
    if (!targetCard.promos) targetCard.promos = [];
    targetCard.promos.push({
        id: 'xfer-' + Math.random().toString(36).substr(2, 9),
        amount: originalAmount,
        originalAmount,
        currentBalance,
        rate,
        expDate,
        isXfer: true,
        isExisting: true,
        transferOwner: transferOwner || '',
        xferFromId: ''
    });
    saveDatabase();
    renderApp();
    openEditLoanModal(targetId);
    logSuccess(`Recorded existing balance transfer with $${currentBalance.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} remaining.`);
}

function renderBalanceTransfers(card) {
    const list = document.getElementById('loan-xfer-list');
    if (!list) return;
    const transfers = (card.promos || []).filter(item => item.isXfer);
    list.innerHTML = '';
    if (!transfers.length) {
        list.innerHTML = '<span class="muted-text">No balance transfers recorded.</span>';
        return;
    }
    transfers.forEach(item => {
        const original = Number(item.originalAmount ?? item.amount) || 0;
        const current = Number(item.currentBalance ?? item.amount) || 0;
        const source = item.xferFromId ? state.loans.find(loan => loan.id === item.xferFromId)?.name : (item.xferFromExternalName || '');
        const person = item.transferOwner === 'jason' ? 'Jason' : item.transferOwner === 'asia' ? 'Asia' : 'Not recorded';
        const row = document.createElement('div');
        row.className = 'payment-plan-row';
        row.innerHTML = `<span><strong>${item.isExisting ? 'Existing' : 'New'} balance transfer</strong> - $${current.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} remaining of $${original.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} | ${Number(item.rate || 0).toFixed(2)}% APR | Expires ${item.expDate || '-'}${source ? ` | From ${escapeHTML(source)}` : ''} <span class="cc-owner-badge ${item.transferOwner || 'unknown'}">By: ${person}</span></span><div style="display:flex; gap:.4rem;"><button type="button" class="action-btn small-btn edit-xfer-btn">Edit</button><button type="button" class="action-btn small-btn danger-btn delete-xfer-btn">Delete</button></div>`;
        row.querySelector('.edit-xfer-btn').addEventListener('click', () => {
            editingXferId = item.id;
            document.getElementById('xfer-amount').value = original;
            document.getElementById('xfer-current-balance').value = current;
            document.getElementById('xfer-promo-rate').value = item.rate || 0;
            document.getElementById('xfer-promo-exp').value = item.expDate || '';
            document.getElementById('xfer-owner').value = item.transferOwner || 'jason';
            // The "Current Transfer Balance" field is normally only shown in "Existing Transfer"
            // mode — editing needs it regardless of mode, since both an original amount and its
            // remaining balance are being adjusted here, not just recorded once at creation time.
            document.getElementById('xfer-current-group').classList.remove('hidden');
            document.getElementById('xfer-source-group').classList.add('hidden');
            document.getElementById('xfer-fee-group').classList.add('hidden');
            // Editing a transfer's promo record (amount/rate/expiration) never touches its ledger
            // transactions — the ledger owner/description fields have nothing to do here.
            document.getElementById('xfer-ledger-owner-group').classList.add('hidden');
            document.getElementById('xfer-description-group').classList.add('hidden');
            document.getElementById('btn-execute-xfer').textContent = 'Update Transfer';
            document.getElementById('btn-cancel-xfer-edit').classList.remove('hidden');
            document.getElementById('xfer-amount').focus();
        });
        row.querySelector('.delete-xfer-btn').addEventListener('click', () => {
            if (!confirm('Delete this balance transfer record? This only removes the tracked promo balance/rate — it does not reverse any past ledger transactions.')) return;
            card.promos = (card.promos || []).filter(p => p.id !== item.id);
            if (editingXferId === item.id) resetXferEditor();
            saveDatabase();
            renderApp();
            openEditLoanModal(card.id);
        });
        list.appendChild(row);
    });
}
function executeBalanceTransfer(targetId, sourceId, amount, feePct, rate, expDate, transferOwner, externalSourceName, ledgerOwner, customDescription) {
    if (isNaN(amount) || amount <= 0) {
        logError("Please enter a valid transfer amount.");
        return;
    }

    const targetCard = state.loans.find(l => l.id === targetId);
    // "Other / Not Tracked" — per explicit user request, 2026-08-05: the source doesn't have to be
    // a card this app tracks (e.g. one of Asia's cards that was never added here). No sourceCard,
    // no balance to reduce, no transaction to log on "it" — everything below that touches
    // sourceCard is skipped for this case, same as the already-existing "existing transfer" path
    // (recordExistingBalanceTransfer) which also has no source.
    const isExternal = sourceId === '__external__';
    const sourceCard = isExternal ? null : state.loans.find(l => l.id === sourceId);

    if (!targetCard || (!isExternal && !sourceCard)) {
        logError("Invalid target or source account selected.");
        return;
    }

    const feeAmount = amount * (feePct / 100);
    const totalAdded = amount + feeAmount;
    // Mobile nickname preferred over the full account name for a tracked source/target — per
    // explicit user request, 2026-08-05 ("it should list the mobile nickname OR the external
    // account name as entered"). Not gated by isMobileViewport() like getAccountDisplayName() is
    // — this is a permanent transaction description, not a viewport-dependent header label.
    const sourceLabel = isExternal ? (externalSourceName || 'External Account') : (sourceCard.mobileNickname || sourceCard.name);
    const targetLabel = targetCard.mobileNickname || targetCard.name;
    const transferOwnerLabel = transferOwner === 'asia' ? 'Asia' : 'Jason';
    // The ledger `owner` field ('personal'/'joint') is the app-wide model every other transaction,
    // filter, and Bill Splitter total keys off — distinct from `transferOwner` ('jason'/'asia',
    // just who gets the badge). Defaulting to 'personal' here matches every other transaction's own
    // default. Per explicit user request, 2026-08-05.
    const resolvedLedgerOwner = ledgerOwner || 'jason';
    const defaultDescription = `Balance Transfer - ${transferOwnerLabel} - ${sourceLabel}`;
    const description = (customDescription || '').trim() || defaultDescription;

    // Adjust balances
    if (sourceCard) sourceCard.currentBal = Math.max(0, sourceCard.currentBal - amount);
    targetCard.currentBal += totalAdded;

    // Log transactions on the target card — today's real date, NOT state.selectedDate. Confirmed
    // real bug, 2026-08-05: state.selectedDate is whatever calendar day was last clicked ANYWHERE
    // in the app (see its only two assignment sites), which has nothing to do with "when I'm
    // executing this transfer" — a stale value from a previous session/click silently posted the
    // charge on some unrelated past/future date, invisible unless you happened to scroll there,
    // making a successful transfer look like it never created a transaction at all.
    const todayStr = formatLocalDate(new Date());
    const dObj = new Date(todayStr + 'T00:00:00');
    const y = dObj.getFullYear();
    const mShort = MONTH_ORDER[dObj.getMonth()];
    const key = `${y}-${mShort}`;

    if (!state.cardCalendars) state.cardCalendars = {};
    if (!state.cardCalendars[targetId]) state.cardCalendars[targetId] = {};
    if (!state.cardCalendars[targetId][key]) state.cardCalendars[targetId][key] = [];

    // Two separate charges on the target card — the transfer amount and the fee — rather than one
    // combined line, both tagged with the same balanceTransferId so they're recognizably tied to
    // this one transfer. Per explicit user request, 2026-08-05.
    const balanceTransferId = Math.random().toString(36).substr(2, 9);
    state.cardCalendars[targetId][key].push({
        id: 'c-' + Math.random().toString(36).substr(2, 9),
        date: todayStr,
        description,
        owner: resolvedLedgerOwner,
        balanceTransferBy: transferOwner || '',
        balanceTransferId,
        amount: -Math.abs(amount)
    });
    if (feeAmount > 0.005) {
        state.cardCalendars[targetId][key].push({
            id: 'c-' + Math.random().toString(36).substr(2, 9),
            date: todayStr,
            description: `${description} (Fee ${feePct}%)`,
            owner: resolvedLedgerOwner,
            balanceTransferBy: transferOwner || '',
            balanceTransferId,
            amount: -Math.abs(feeAmount)
        });
    }

    // Log transaction on source card if it's a credit card (nothing to log against an external,
    // untracked source — there's no ledger for it in this app)
    if (sourceCard && sourceCard.type === 'credit') {
        if (!state.cardCalendars[sourceId]) state.cardCalendars[sourceId] = {};
        if (!state.cardCalendars[sourceId][key]) state.cardCalendars[sourceId][key] = [];

        state.cardCalendars[sourceId][key].push({
            id: 'c-' + Math.random().toString(36).substr(2, 9),
            date: todayStr,
            description: `Balance Transfer - ${transferOwnerLabel} - ${targetLabel}`,
            owner: resolvedLedgerOwner,
            balanceTransferBy: transferOwner || '',
            amount: Math.abs(amount)
        });
    }

    // Add promo balance item — same balanceTransferId as the two ledger charges above, so all three
    // records tied to this one transfer share a recognizable link.
    if (!targetCard.promos) targetCard.promos = [];
    targetCard.promos.push({
        id: balanceTransferId,
        amount: totalAdded,
        originalAmount: amount,
        currentBalance: totalAdded,
        rate: rate,
        expDate: expDate,
        isXfer: true,
        transferOwner: transferOwner || '',
        // xferFromId only ever points at a real tracked loan (renderBalanceTransfers() looks it up
        // via state.loans.find) — left empty for an external source, same convention
        // recordExistingBalanceTransfer() already uses for "no tracked source." The free-text name
        // is preserved separately so the transfer list can still show where it came from.
        xferFromId: isExternal ? '' : sourceId,
        xferFromExternalName: isExternal ? (externalSourceName || 'External Account') : ''
    });

    saveDatabase();
    renderApp();

    // Re-populate modal view
    openEditLoanModal(targetId);

    logSuccess(`Successfully executed balance transfer of $${amount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} from ${sourceCard.name} to ${targetCard.name}! Charged $${totalAdded.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} (with $${feeAmount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} fee) at ${rate}% APR promo interest rate.`);
}

// --- UTILS & LOGS ---
// mm-dd-yyyy HH:mm:ss, local time — every log line needs both date and time so entries are still
// unambiguous after the log scrolls past a midnight boundary or spans multiple sessions.
function _logTimestamp() {
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    return `${pad(d.getMonth() + 1)}-${pad(d.getDate())}-${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function setDirectionToggleValue(containerId, hiddenInputId, direction) {
    const container = document.getElementById(containerId);
    const hiddenInput = document.getElementById(hiddenInputId);
    if (hiddenInput) hiddenInput.value = direction;
    if (container) {
        const buttons = container.querySelectorAll('.direction-btn');
        buttons.forEach(btn => {
            const btnDir = btn.getAttribute('data-direction');
            btn.classList.remove('active-charge', 'active-deposit');
            if (btnDir === direction) {
                btn.classList.add(direction === 'charge' ? 'active-charge' : 'active-deposit');
            }
        });
    }
}

document.addEventListener('click', (e) => {
    const btn = e.target.closest('.direction-toggle-group .direction-btn');
    if (btn) {
        e.preventDefault();
        const container = btn.closest('.direction-toggle-group');
        const dir = btn.getAttribute('data-direction');
        const hiddenId = container.id === 'trans-direction-group' ? 'trans-direction' : 'edit-trans-direction';
        setDirectionToggleValue(container.id, hiddenId, dir);
        // The Credit Card/Loan edit form ALSO shows a separate "Transaction Type" dropdown
        // (#edit-tx-kind: Charge/Credit-Reversal/Payment) alongside this toggle — the save handler
        // reads #edit-tx-kind for regular (non-automatic-payment) card transactions, not this toggle,
        // so without this sync clicking Charge/Deposit here visibly changes the toggle but silently
        // has no effect on what actually saves. Confirmed real bug, 2026-08-04 (found investigating a
        // related report that editing a card transaction's direction "doesn't update"). Only touches
        // #edit-tx-kind, not #trans-direction-group's quick-add counterpart (which has no such
        // dropdown alongside it).
        const kindSelect = container.id === 'edit-trans-direction-group' ? document.getElementById('edit-tx-kind') : null;
        if (kindSelect && !kindSelect.closest('.hidden')) {
            kindSelect.value = dir === 'charge' ? 'charge' : 'payment';
        }
    }
});

// Newest entry first (prepend, not append) — per explicit user request, 2026-08-05, so the latest
// sync result is the first thing visible on opening Sync Settings instead of being scrolled off the
// bottom of a log that can run long over a session. No scrollTop reset needed: the newest entry is
// now already at the top, right where the container opens.
function logSystem(msg) {
    const container = document.getElementById('logs-container');
    if (!container) return;
    const entry = document.createElement('div');
    entry.className = 'log-entry system';
    entry.textContent = `[${_logTimestamp()}] [SYSTEM]: ${msg}`;
    container.prepend(entry);
}

function logSuccess(msg) {
    const container = document.getElementById('logs-container');
    if (!container) return;
    const entry = document.createElement('div');
    entry.className = 'log-entry success';
    entry.textContent = `[${_logTimestamp()}] [SUCCESS]: ${msg}`;
    container.prepend(entry);
}

function logError(msg) {
    const container = document.getElementById('logs-container');
    if (!container) return;
    const entry = document.createElement('div');
    entry.className = 'log-entry error';
    entry.textContent = `[${_logTimestamp()}] [ERROR]: ${msg}`;
    container.prepend(entry);
}

function logInfo(msg) {
    const container = document.getElementById('logs-container');
    if (!container) return;
    const entry = document.createElement('div');
    entry.className = 'log-entry info';
    entry.textContent = `[${_logTimestamp()}] [INFO]: ${msg}`;
    container.prepend(entry);
}

function updateQuickAddFormFields() {
    const isPersonal = state.dashboardType === 'personal';
    const isJoint = state.dashboardType === 'joint';
    const isAsiaDash = state.dashboardType === 'asia';
    const isSavingsTransfer = isPersonal && document.getElementById('personal-trans-type').value === 'savings-transfer';
    const isJointTransfer = isPersonal && document.getElementById('personal-trans-type').value === 'joint-transfer';
    const isJointTransferDeposit = isJointTransfer && document.getElementById('personal-joint-direction').value === 'deposit';
    // Asia's Checking Transaction Type selector (Phase 3) — same shape as Jason's above, its own
    // element ids since #quick-add-form is shared across all three dashboards and only one type
    // group is ever visible at a time (see the hidden toggles below).
    const isAsiaSavingsTransfer = isAsiaDash && document.getElementById('asia-trans-type').value === 'savings-transfer';
    const isAsiaJointTransfer = isAsiaDash && document.getElementById('asia-trans-type').value === 'joint-transfer';
    const isAsiaJointTransferDeposit = isAsiaJointTransfer && document.getElementById('asia-joint-direction').value === 'deposit';
    const jointTypeVal = document.getElementById('joint-trans-type').value;
    const isContribution = isJoint && (jointTypeVal === 'contribution' || jointTypeVal === 'withdrawal');
    const isExplicitWithdrawal = isJoint && jointTypeVal === 'withdrawal';
    if (isExplicitWithdrawal) {
        document.getElementById('contribution-direction').value = 'withdrawal';
    }
    const isWithdrawal = isContribution && (isExplicitWithdrawal || document.getElementById('contribution-direction').value === 'withdrawal');

    document.getElementById('personal-type-group').classList.toggle('hidden', !isPersonal);
    document.getElementById('personal-joint-transfer-group').classList.toggle('hidden', !isJointTransfer);
    document.getElementById('personal-joint-split-group').classList.toggle('hidden', !isJointTransferDeposit);
    document.getElementById('asia-type-group').classList.toggle('hidden', !isAsiaDash);
    document.getElementById('asia-joint-transfer-group').classList.toggle('hidden', !isAsiaJointTransfer);
    document.getElementById('asia-joint-split-group').classList.toggle('hidden', !isAsiaJointTransferDeposit);
    document.getElementById('trans-amount-label').textContent = isSavingsTransfer ? 'Personal Account Amount' : (isAsiaSavingsTransfer ? 'Asia Account Amount' : ((isJointTransfer || isAsiaJointTransfer) ? 'Transfer Amount' : 'Amount'));
    document.getElementById('trans-amount-hint').classList.toggle('hidden', !(isSavingsTransfer || isAsiaSavingsTransfer));
    document.getElementById('trans-amount').placeholder = (isSavingsTransfer || isAsiaSavingsTransfer) ? 'Negative to move into Savings' : ((isJointTransfer || isAsiaJointTransfer) ? 'Positive amount' : 'Negative for expenses');
    document.getElementById('joint-contribution-group').classList.toggle('hidden', !isContribution);
    document.getElementById('single-amount-group').classList.toggle('hidden', isContribution);
    document.getElementById('contribution-deposit-fields').classList.toggle('hidden', isWithdrawal);
    document.getElementById('contribution-recipient-group').classList.toggle('hidden', !isWithdrawal);
    document.getElementById('contribution-withdrawal-field').classList.toggle('hidden', !isWithdrawal);
    document.getElementById('trans-amount').required = !isContribution;
    document.getElementById('trans-jason-amount').required = isContribution && !isWithdrawal;
    document.getElementById('trans-asia-amount').required = isContribution && !isWithdrawal;
    document.getElementById('contribution-withdrawal-amount').required = isWithdrawal;
}

// Renders one stat "chip" (e.g. "Balance $1,234.56") for the loan/credit-card sticky header
// subtitle — see .header-stat-chip in index.css. Small helper since updateTabTitles() builds
// several of these per account type.
function headerStatChip(label, value) {
    return `<span class="header-stat-chip">${escapeHTML(label)} <strong>${escapeHTML(String(value))}</strong></span>`;
}

// Returns the short mobile nickname (Settings → Account Settings → Mobile Nickname) in place of
// the full account name when one's been set and we're on a mobile-width viewport — desktop always
// shows the full name, since it has the room and the nickname exists purely as a mobile-space
// workaround. Per explicit user request, 2026-08-05.
function getAccountDisplayName(account) {
    if (!account) return '';
    if (isMobileViewport() && account.mobileNickname) return account.mobileNickname;
    return account.name;
}

// Loan/credit-card account names vary wildly in length ("Amex" vs "Comerica Business Platinum
// Visa Signature") — on the mobile pinned header (see relocateMobileCCDetailHeader()) a long one
// wraps to 2 lines, which .header-account-link's underline-removal rule above merely tolerates
// rather than fixes. Forcing nowrap + shrinking font-size until it fits keeps every name on one
// row regardless of length, per explicit user request, 2026-08-05. Desktop's toolbar-sized title
// has never had this problem (smaller font, wider toolbar), so this only runs on mobile.
function fitAccountTitleFont(titleEl) {
    const nameBtn = titleEl?.querySelector('.header-account-link');
    if (!titleEl || !isMobileViewport()) {
        if (titleEl) { titleEl.style.whiteSpace = ''; titleEl.style.maxWidth = ''; titleEl.style.overflow = ''; titleEl.style.textOverflow = ''; titleEl.style.fontSize = ''; titleEl.style.display = ''; titleEl.style.alignItems = ''; }
        if (nameBtn) { nameBtn.style.overflow = ''; nameBtn.style.textOverflow = ''; nameBtn.style.whiteSpace = ''; nameBtn.style.minWidth = ''; nameBtn.style.flex = ''; }
        return;
    }
    // The h2 sits in a column-direction flex container with align-items:center (see
    // `.header-top-row .header-title-compact` mobile rule) — cross-axis items there shrink-to-fit
    // their own content instead of stretching to the container's width, so left unconstrained the
    // h2 just grows as wide as the name needs and bleeds off the edge of the screen rather than
    // ever reporting scrollWidth > clientWidth. max-width clamps it back to the parent's actual
    // available width so the two can be compared meaningfully.
    titleEl.style.whiteSpace = 'nowrap';
    titleEl.style.maxWidth = '100%';
    titleEl.style.overflow = 'hidden';
    titleEl.style.textOverflow = 'ellipsis';
    // Ellipsis on the h2 alone was a safety net for names so long even the font-size floor below
    // can't make them fit — but the icon badge + name button are two separate inline children of
    // the h2, and text-overflow:ellipsis on a parent can only make an ENTIRE inline-block/atomic
    // child (the name <button>, display:inline-block) disappear as a whole when it doesn't fit — it
    // can't partially reveal characters from inside one. Confirmed real bug, 2026-08-05 (visible
    // after the back button started sharing this row and shrank the available space further): a
    // long name rendered as a bare "…" with the name itself fully invisible, at any font size, not
    // just at the floor. Making the h2 a flex row and giving the name button its OWN
    // overflow/ellipsis (with flex:1/min-width:0 so it only claims the space left after the
    // fixed-size icon) lets ellipsis truncate WITHIN the button's own text instead of hiding the
    // whole thing.
    titleEl.style.display = 'flex';
    titleEl.style.alignItems = 'center';
    if (nameBtn) {
        nameBtn.style.overflow = 'hidden';
        nameBtn.style.textOverflow = 'ellipsis';
        nameBtn.style.whiteSpace = 'nowrap';
        nameBtn.style.minWidth = '0';
        nameBtn.style.flex = '1 1 auto';
    }
    const baseFontSize = 1.15;
    const minFontSize = 0.8;
    let fontSize = baseFontSize;
    titleEl.style.fontSize = `${fontSize}rem`;
    while (titleEl.scrollWidth > titleEl.clientWidth && fontSize > minFontSize) {
        fontSize -= 0.05;
        titleEl.style.fontSize = `${fontSize.toFixed(2)}rem`;
    }
}

function updateTabTitles() {
    const activeTab = document.querySelector('.nav-btn.active').dataset.tab;
    const title = document.getElementById('current-tab-title');
    const subtitle = document.getElementById('current-tab-subtitle');
    // Reset here rather than in each branch below — only the loans/creditcards branches (when a
    // specific card/loan is selected) turn this back on, so switching tabs or navigating back to
    // the account list never leaves a stale bold subtitle behind.
    subtitle.classList.remove('header-subtitle-highlight');
    // Single consolidated button now (Starting Balance + Payroll used to be separate buttons here,
    // each with their own visibility check) — see #account-settings-dialog. Per explicit user
    // request, 2026-08-05.
    const accountSettingsButton = document.getElementById('btn-open-account-settings');
    const showAccountSettings = activeTab === 'dashboard'
        && (state.dashboardType === 'personal' || state.dashboardType === 'joint' || state.dashboardType === 'asia');
    accountSettingsButton?.classList.toggle('hidden', !showAccountSettings);

    const isLoanHome = activeTab === 'loans'
        && !state.loans.some(item => item.id === state.ccSelectedCardId && item.type === 'loan');
    const isCreditCardHome = activeTab === 'creditcards'
        && !state.loans.some(item => item.id === state.ccSelectedCardId && item.type === 'credit');
    document.getElementById('header-period-nav')?.classList.toggle('hidden', isLoanHome || isCreditCardHome);

    if (activeTab === 'dashboard') {
        let accountName = 'Jason';
        if (state.dashboardType === 'joint') {
            accountName = 'Joint';
        } else if (state.dashboardType === 'asia') {
            accountName = 'Asia';
        } else if (state.dashboardType !== 'personal') {
            const card = state.loans.find(l => l.id === state.dashboardType);
            if (card) accountName = card.name;
        }
        // Jason/Joint/Asia get a clickable icon badge (custom upload or a default emoji) mirroring
        // the credit-card/loan pattern, driven by the Account Settings dialog — per explicit user
        // request, 2026-08-05 (extended to Asia 2026-08-06). The final branch above (dashboardType
        // holding a card id) is an unrelated legacy case with no icon/login of its own, so it keeps
        // the plain text title.
        if (state.dashboardType === 'personal' || state.dashboardType === 'joint' || state.dashboardType === 'asia') {
            const loginUrl = state.dashboardType === 'joint' ? state.jointLoginUrl : (state.dashboardType === 'asia' ? state.asiaLoginUrl : state.personalLoginUrl);
            const iconVal = state.dashboardType === 'joint' ? state.jointIcon : (state.dashboardType === 'asia' ? state.asiaIcon : state.personalIcon);
            const pseudoAccount = { name: `${accountName} Checking`, loginUrl };
            const icon = getCustomAccountIcon(iconVal, pseudoAccount.name) || { glyph: state.dashboardType === 'joint' ? '👥' : '🏠', label: pseudoAccount.name };
            title.innerHTML = `${renderDebtAccountIconBadge(pseudoAccount, icon, 'header-debt-icon')}${escapeHTML(accountName)} Dashboard`;
        } else {
            title.textContent = `${accountName} Dashboard`;
        }
        subtitle.textContent = state.dashboardType === 'personal' ? "Jason's checking calendar and cash flows"
            : state.dashboardType === 'joint' ? 'Shared Joint Account ledger and expenditures'
            : state.dashboardType === 'asia' ? "Asia's checking calendar and cash flows"
            : 'Credit card transactions and running balance';
    } else if (activeTab === 'bills') {
        title.textContent = `Shared Bills Split`;
        subtitle.textContent = "Split monthly payments and track delivery allocations";
    } else if (activeTab === 'delivery') {
        title.textContent = `Delivery Side Gigs`;
        subtitle.textContent = "Log gig app logs and calculate daily payouts";
    } else if (activeTab === 'savings') {
        // Reflects whichever pool is currently toggled — Asia's own icon/login URL now have full
        // parity with the household pool's (see her Savings Account Settings dialog), so the header
        // badge needs to switch with the toggle too, not stay pinned to the household pool's icon
        // regardless of which one is selected.
        const isAsiaPool = state.savingsPoolView === 'asia';
        const pseudoAccount = { name: 'Savings Tracker', loginUrl: (isAsiaPool ? state.asiaSavingsLoginUrl : state.savingsLoginUrl) };
        const icon = getCustomAccountIcon(isAsiaPool ? state.asiaSavingsIcon : state.savingsIcon, pseudoAccount.name) || { glyph: '💰', label: pseudoAccount.name };
        title.innerHTML = `${renderDebtAccountIconBadge(pseudoAccount, icon, 'header-debt-icon')}Savings Tracker`;
        subtitle.textContent = 'Plan savings transfers and track the projected balance';
    } else if (activeTab === 'loans') {
        const loan = state.loans.find(item => item.id === state.ccSelectedCardId && item.type === 'loan');
        if (loan) {
            const balance = calculateCardLedgerBalance(loan.id);
            const startBal = Number(loan.startBal) || 0;
            const paidPct = startBal > 0 ? Math.min(100, Math.max(0, ((startBal - balance) / startBal) * 100)) : 100;
            const apr = Number(loan.interestRate) || 0;
            const monthlyPayment = getLoanDebtPaymentAmount(loan);
            const icon = getDebtAccountIcon(loan);
            // Current Balance and Projected Payoff live here (the truly-sticky page header — see
            // .main-sticky-dashboard in index.css) instead of down in the page body, so they stay
            // visible while scrolling through the rest of the card's details.
            const payoffDate = projectCardPayoffPath(loan.id, 0, formatLocalDate(new Date()), 0, 0, false, 600).payoffDate;
            title.innerHTML = `${renderDebtAccountIconBadge(loan, icon, 'header-debt-icon')}<button type="button" class="header-account-link" id="btn-header-card-settings" title="Open loan settings">${escapeHTML(getAccountDisplayName(loan))}</button>`;
            subtitle.classList.add('header-subtitle-highlight');
            // Order per explicit user request, 2026-08-03: Original Balance, Monthly Payment, APR,
            // Paid, Current Balance, Payoff — folds in what the removed "Card Metrics" section used
            // to show (APR/Monthly Payment/Original Balance) alongside the balance/payoff chips that
            // already lived here.
            subtitle.innerHTML = [
                headerStatChip('Original Balance', formatCardBalance(startBal)),
                headerStatChip('Monthly Payment', `$${monthlyPayment.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`),
                headerStatChip('APR', `${apr.toFixed(2)}%`),
                headerStatChip('Paid', `${paidPct.toFixed(0)}%`),
                headerStatChip('Current Balance', formatCardBalance(balance)),
                headerStatChip('Payoff', payoffDate)
            ].join('');
            document.getElementById('btn-header-card-settings').onclick = () => openEditLoanModal(loan.id);
            fitAccountTitleFont(title);
        } else {
            title.textContent = 'Installment Loans';
            subtitle.textContent = 'Debt payoff targets, escrow, and installment target options';
        }
    } else if (activeTab === 'creditcards') {
        const card = state.loans.find(item => item.id === state.ccSelectedCardId);
        if (card) {
            const balance = calculateCardLedgerBalance(card.id);
            const limit = Math.max(0, Number(card.limit) || 0);
            const apr = getEffectiveCardRateForMonth(card, 0);
            const icon = getDebtAccountIcon(card);
            // See the matching comment in the 'loans' branch above — same reasoning for cards.
            const payoffDate = projectCardPayoffPath(card.id, 0, formatLocalDate(new Date()), 0, 0, false, 600).payoffDate;
            title.innerHTML = `${renderDebtAccountIconBadge(card, icon, 'header-debt-icon')}<button type="button" class="header-account-link" id="btn-header-card-settings" title="Open card settings">${escapeHTML(getAccountDisplayName(card))}</button>`;
            subtitle.classList.add('header-subtitle-highlight');
            // Credit cards get their own bubble set (distinct from loans' Original
            // Balance/Monthly Payment/Paid/Current Balance) — per explicit user request,
            // 2026-08-03: Credit Limit, Balance, Available Limit, Utilization, APR, Payoff.
            // Charge cards (no preset limit) show "None"/"No preset limit"/"N/A" in place of the
            // limit-derived fields, same as the old removed "Card Metrics" section used to.
            const limitText = card.isChargeCard ? 'None' : formatCardBalance(limit);
            const availableText = card.isChargeCard ? 'No preset limit' : formatCardBalance(Math.max(0, limit - balance));
            const utilizationText = card.isChargeCard ? 'N/A' : `${(limit > 0 ? Math.min(100, Math.max(0, (balance / limit) * 100)) : 0).toFixed(0)}%`;
            subtitle.innerHTML = [
                headerStatChip('Credit Limit', limitText),
                headerStatChip('Balance', formatCardBalance(balance)),
                headerStatChip('Available Limit', availableText),
                headerStatChip('Utilization', utilizationText),
                headerStatChip('APR', `${apr.toFixed(2)}%`),
                headerStatChip('Payoff', payoffDate)
            ].join('');
            document.getElementById('btn-header-card-settings').onclick = () => openEditLoanModal(card.id);
            fitAccountTitleFont(title);
        } else {
            title.textContent = 'Credit Cards';
            subtitle.textContent = 'Credit card payoff targets and promotions';
        }
    } else if (activeTab === 'billtracker') {
        title.textContent = 'Bill Settings';
        subtitle.textContent = 'Setup recurring charges, statement/payment dates, and checking/card sync';
    }
}

function populateCCDropdowns() {
    // Per explicit user request, 2026-08-10: these pickers used to lump every credit card into one
    // flat "Credit Cards" group regardless of who owns it — with cards now spanning Joint/Jason/Asia
    // (see Phase 4b), that made it hard to find the right one. Each select's single optgroup was
    // split into three static ones in Index.html (id suffixed -joint/-asia/-jason); populate each
    // from the matching ownership slice of state.loans, in that display order (Joint, Asia, Jason —
    // the order explicitly requested). A group with zero cards just renders as an empty (invisible)
    // optgroup, not a stray "Joint Cards" label with nothing under it.
    const groups = {
        billSource: { joint: 'bill-source-cc-optgroup-joint', asia: 'bill-source-cc-optgroup-asia', jason: 'bill-source-cc-optgroup-jason' },
        billSettingsSource: { joint: 'bill-settings-source-cc-optgroup-joint', asia: 'bill-settings-source-cc-optgroup-asia', jason: 'bill-settings-source-cc-optgroup-jason' },
        seasonalChargeSource: { joint: 'seasonal-charge-source-cc-optgroup-joint', asia: 'seasonal-charge-source-cc-optgroup-asia', jason: 'seasonal-charge-source-cc-optgroup-jason' },
    };
    const elements = {};
    Object.entries(groups).forEach(([pickerKey, byOwnership]) => {
        elements[pickerKey] = {};
        Object.entries(byOwnership).forEach(([ownership, id]) => {
            const el = document.getElementById(id);
            if (el) el.innerHTML = '';
            elements[pickerKey][ownership] = el;
        });
    });

    // Alphabetical within each ownership group, not state.loans' own (insertion) order — with a
    // dozen+ cards, finding one in a "No Source / Joint Checking / Personal Checking / Credit
    // Cards: ..." picker is much easier sorted by name than in whatever order they happened to be
    // added.
    state.loans
        .filter(loan => loan.type === 'credit')
        .sort((a, b) => a.name.localeCompare(b.name))
        .forEach(loan => {
            const ownership = loan.paymentSource === 'joint' ? 'joint' : loan.paymentSource === 'asia' ? 'asia' : 'jason';
            const opt = document.createElement('option');
            opt.value = loan.id;
            opt.textContent = loan.name;

            Object.values(elements).forEach(byOwnership => {
                const target = byOwnership[ownership];
                if (target) target.appendChild(opt.cloneNode(true));
            });
        });
}

function countWeekdayOccurrences(year, month, weekday) {
    const monthIndex = MONTH_ORDER.indexOf(month);
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    let count = 0;
    for (let day = 1; day <= daysInMonth; day++) if (new Date(year, monthIndex, day).getDay() === weekday) count++;
    return count;
}

function getBillOccurrenceDates(rawBill, year, month) {
    // Day-level end date: no occurrences past it (recurringEndMonth already stops later months at
    // month granularity; this trims occurrences within the final month itself).
    const endDateFilter = dates => {
        let filtered = rawBill.recurringStartDate ? dates.filter(d => d >= rawBill.recurringStartDate) : dates;
        if (rawBill.recurringEndDate) filtered = filtered.filter(d => d <= rawBill.recurringEndDate);
        return filtered;
    };
    const legacyFrequency = ['weekly','biweekly','fourweekly','quarterly','annual'].includes(rawBill.budgetFrequency) ? rawBill.budgetFrequency : 'monthly';
    const frequency = rawBill.chargeFrequency || legacyFrequency;
    const monthIndex = MONTH_ORDER.indexOf(month);
    if (monthIndex < 0) return [];
    if (frequency === 'monthly') return endDateFilter([getBillChargeDate(year, month, rawBill.dueDay)]);

    const monthStart = new Date(year, monthIndex, 1);
    const monthEnd = new Date(year, monthIndex + 1, 0);

    if (frequency === 'quarterly' || frequency === 'annual') {
        // Unlike weekly/biweekly below (where only the day-of-week matters, so ANY month makes a
        // valid reference point), quarterly/annual cadence depends on real calendar distance from a
        // genuine start month. Defaulting the anchor to "the month currently being asked about" (as
        // the weekly fallback does) makes every month exactly 0 months from its own anchor, which
        // trivially always satisfies "is this a multiple of the interval" and charges every month
        // regardless of the configured frequency — confirmed as a real bug 2026-07-23 (a Bill
        // Tracker item switched from monthly to "every 3 months starting in Sept" kept charging
        // every month, because there was no real start date to measure distance from). Anchor from
        // recurringStartMonth (a real "YYYY-MM", not the day-of-week fallback below) instead.
        let anchor = rawBill.frequencyStartDate ? new Date(rawBill.frequencyStartDate + 'T00:00:00') : null;
        if (!anchor || Number.isNaN(anchor.getTime())) {
            const startIndex = getBillRecurrenceMonthIndex(rawBill.recurringStartMonth);
            if (startIndex !== null) {
                const startYear = Math.floor(startIndex / 12);
                const startMonthIdx = ((startIndex % 12) + 12) % 12;
                const startMonthEnd = new Date(startYear, startMonthIdx + 1, 0).getDate();
                anchor = new Date(startYear, startMonthIdx, Math.min(Number(rawBill.dueDay) || 1, startMonthEnd));
            } else {
                anchor = new Date(year, monthIndex, 1);
            }
        }
        if (anchor > monthEnd) return [];
        const intervalMonths = frequency === 'quarterly' ? 3 : 12;
        const difference = (year - anchor.getFullYear()) * 12 + monthIndex - anchor.getMonth();
        if (difference < 0 || difference % intervalMonths !== 0) return [];
        const day = Math.min(anchor.getDate(), monthEnd.getDate());
        return endDateFilter([formatLocalDate(new Date(year, monthIndex, day))]);
    }

    let anchor = rawBill.frequencyStartDate ? new Date(rawBill.frequencyStartDate + 'T00:00:00') : null;
    if (!anchor || Number.isNaN(anchor.getTime())) {
        anchor = new Date(year, monthIndex, 1);
        const legacyDay = Number.isFinite(Number(rawBill.weeklyDay)) ? Number(rawBill.weeklyDay) : anchor.getDay();
        while (anchor.getDay() !== legacyDay) anchor.setDate(anchor.getDate() + 1);
    }
    if (anchor > monthEnd) return [];

    const intervalDays = frequency === 'biweekly' ? 14 : frequency === 'fourweekly' ? 28 : 7;
    const occurrence = new Date(anchor);
    while (occurrence < monthStart) occurrence.setDate(occurrence.getDate() + intervalDays);
    const dates = [];
    while (occurrence <= monthEnd) {
        dates.push(formatLocalDate(occurrence));
        occurrence.setDate(occurrence.getDate() + intervalDays);
    }
    return endDateFilter(dates);
}

// Bill Splitter/Bill Tracker calendars can plot a bill two different ways: "pay" mode shows it on
// the day it's actually charged/due (real Fridays for a biweekly paycheck-funded bill, etc.) using
// its true occurrence dates; "transfer" mode shows it on the 1st/15th date its budgeted share
// actually moves out of the joint account, which for a 'both'-allocation bill means splitting it
// into two half-amount occurrences on the 1st and the 15th. Returns [{ dueDay, budgetAmount }].
function getBillCalendarOccurrences(bill, year, month, dateMode) {
    if (dateMode === 'transfer') {
        if (bill.cycleAllocation === 'both') {
            const half = bill.budgetAmount / 2;
            return [{ dueDay: 1, budgetAmount: half }, { dueDay: 15, budgetAmount: half }];
        }
        return bill.dueDay ? [{ dueDay: bill.dueDay, budgetAmount: bill.budgetAmount }] : [];
    }
    const isSubscriptionStyle = bill.chargeFrequency && bill.chargeFrequency !== 'monthly';
    const dates = isSubscriptionStyle
        ? getBillOccurrenceDates(bill, year, month)
        : (bill.dueDay ? [getBillChargeDate(year, month, bill.dueDay)] : []);
    const perOccurrenceAmount = Math.max(0, Number(bill.frequencyAmount ?? bill.budgetAmount) || 0);
    return dates.map(d => ({ dueDay: new Date(d + 'T00:00:00').getDate(), budgetAmount: perOccurrenceAmount }));
}

function calculateBillFundingAmount(rawBill, year, month) {
    const chargeAmount = Math.max(0, Number(rawBill.frequencyAmount ?? rawBill.weeklyAmount ?? rawBill.budgetAmount) || 0);
    const chargeFrequency = rawBill.chargeFrequency || (['weekly','biweekly','fourweekly','quarterly','annual'].includes(rawBill.budgetFrequency) ? rawBill.budgetFrequency : 'monthly');
    const budgetMethod = rawBill.budgetFrequency === 'monthly' && rawBill.chargeFrequency ? 'monthly' : (rawBill.budgetFrequency === 'charge' ? 'charge' : rawBill.chargeFrequency ? rawBill.budgetFrequency : 'charge');
    let amount;
    if (budgetMethod === 'monthly') {
        const monthlyFactors = { monthly: 1, weekly: 52 / 12, biweekly: 26 / 12, fourweekly: 13 / 12, quarterly: 1 / 3, annual: 1 / 12 };
        amount = chargeAmount * (monthlyFactors[chargeFrequency] || 1);
    } else {
        amount = chargeAmount * getBillOccurrenceDates(rawBill, year, month).length;
    }
    return Math.round(amount * 100) / 100;
}

function getMortgageFullPaymentAmount(loan) {
    if (!loan?.isMortgage) return Math.max(0, Number(loan?.monthlyMin) || 0);
    return Math.max(0,
        (Number(loan.escrowAmount) || 0)
        + (Number(loan.piAmount) || 0)
        + (Number(loan.extraPayment) || 0)
    );
}

function getLoanDebtPaymentAmount(loan) {
    if (!loan?.isMortgage) return Math.max(0, Number(loan?.monthlyMin) || 0);
    // Escrow leaves checking, but it never reduces mortgage principal. Additional P&I is a real
    // loan payment and therefore belongs on the loan side together with the scheduled P&I amount.
    return Math.max(0, (Number(loan.piAmount) || 0) + (Number(loan.extraPayment) || 0));
}

function recalculateBillBudgetForPeriod(rawBill, year, month, cycleKey = 'cycle1st') {
    const bill = normalizeBillSplitterItem(rawBill, cycleKey);
    const occurrenceDates = getBillOccurrenceDates(bill, year, month);
    bill.weeklyOccurrences = occurrenceDates.length;
    bill.occurrenceDates = occurrenceDates;
    bill.budgetAmount = calculateBillFundingAmount(bill, year, month);
    bill.amount = -bill.budgetAmount;
    if (bill.entryType === 'actual') bill.paymentAmount = Math.round(bill.occurrencePaymentAmount * occurrenceDates.length * 100) / 100;
    return bill;
}
function getBillRecurrenceMonthIndex(value) {
    const match = /^(\d{4})-(\d{2})$/.exec(value || '');
    if (!match) return null;
    return Number(match[1]) * 12 + Number(match[2]) - 1;
}

function getPeriodMonthIndex(year, month) {
    return Number(year) * 12 + MONTH_ORDER.indexOf(month);
}

function isBillActiveForPeriod(bill, year, month) {
    if (!bill.isRecurring) return true;
    const periodIndex = getPeriodMonthIndex(year, month);
    const startIndex = getBillRecurrenceMonthIndex(bill.recurringStartMonth);
    const endIndex = getBillRecurrenceMonthIndex(bill.recurringEndMonth);
    const withinRecurringRange = (startIndex === null || periodIndex >= startIndex) && (endIndex === null || periodIndex <= endIndex);
    if (!withinRecurringRange) return false;
    return bill.budgetFrequency === 'monthly' || getBillOccurrenceDates(bill, year, month).length > 0;
}

function normalizeBillSplitterItem(bill, cycleKey = 'cycle1st') {
    const budgetAmount = Math.abs(Number(bill.budgetAmount ?? bill.amount) || 0);
    const paymentAmount = Math.abs(Number(bill.paymentAmount ?? bill.amount) || 0);
    const isActual = (bill.entryType || 'actual') === 'actual';
    return {
        ...bill,
        id: bill.id || 'bill-' + Math.random().toString(36).substr(2, 9),
        account: bill.account || bill.name || 'Bill',
        category: ['bill','expense','utility','savings'].includes(bill.category) ? bill.category : 'bill',
        budgetAmount,
        paymentAmount: isActual ? paymentAmount : 0,
        samePaymentAmount: bill.samePaymentAmount ?? Math.abs(budgetAmount - paymentAmount) < 0.001,
        amount: -budgetAmount,
        dueDay: isActual ? Math.min(31, Math.max(1, Number(bill.dueDay) || (cycleKey === 'cycle1st' ? 1 : 15))) : 0,
        paymentSource: bill.paymentSource || 'jointChecking',
        entryType: bill.entryType || 'actual',
        ownership: bill.ownership || 'joint',
        cycleAllocation: bill.cycleAllocation || (cycleKey === 'cycle15th' ? '15th' : '1st'),
        // Bug fix: this used to force 'charge' for ANY non-monthly chargeFrequency, silently
        // discarding the user's actual "Budget Method" selection (the "Spread Evenly Each Month"
        // option, value 'monthly', shown in the editor — Index.html's bill-budget-frequency select)
        // every time the bill re-normalized. That's why a quarterly bill the user explicitly set to
        // spread evenly kept showing $0 in every non-charge month and the full amount only in the
        // literal charge month — calculateBillFundingAmount's correct spread-averaging math
        // (monthlyFactors) was never reachable because budgetFrequency could never actually be
        // 'monthly' for a subscription-style bill. Just respect whatever's stored.
        budgetFrequency: bill.budgetFrequency || 'monthly',
        chargeFrequency: bill.chargeFrequency || (['weekly','biweekly','fourweekly','quarterly','annual'].includes(bill.budgetFrequency) ? bill.budgetFrequency : 'monthly'),
        frequencyAmount: Math.max(0, Number(bill.frequencyAmount ?? bill.weeklyAmount ?? budgetAmount) || 0),
        frequencyStartDate: bill.frequencyStartDate || '',
        occurrencePaymentAmount: Math.max(0, Number(bill.occurrencePaymentAmount ?? paymentAmount) || 0),
        weeklyAmount: Math.max(0, Number(bill.frequencyAmount ?? bill.weeklyAmount) || 0),
        weeklyDay: Number.isFinite(Number(bill.weeklyDay)) ? Number(bill.weeklyDay) : 6,
        weeklyOccurrences: Math.max(0, Number(bill.weeklyOccurrences) || 0),
        isRecurring: !!bill.isRecurring,
        recurringSeriesId: bill.recurringSeriesId || '',
        recurringStartMonth: bill.recurringStartMonth || '',
        recurringEndMonth: bill.recurringEndMonth || ''
    };
}

function restoreOrphanedPersonalRecurringBills() {
    const currentKey = `${state.currentYear}-${state.currentMonth}`;
    const currentBills = state.monthlyBills?.[currentKey];
    const existingAccounts = new Set(['cycle1st', 'cycle15th'].flatMap(cycleKey =>
        (currentBills?.[cycleKey]?.bills || []).map(bill => (bill.account || bill.name || '').trim().toLowerCase())
    ));
    const groups = new Map();
    Object.values(state.personalCalendar || {}).forEach(list => (list || []).forEach(tx => {
        const account = (tx.description || '').trim();
        const amount = Math.abs(Number(tx.amount) || 0);
        if (!account || amount <= 0 || !tx.isRecurring || tx.linkedBillId) return;
        const key = `${account.toLowerCase()}|${amount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
        if (!groups.has(key)) groups.set(key, { account, amount, entries: [] });
        groups.get(key).entries.push(tx);
    }));

    let restored = 0;
    groups.forEach(group => {
        if (existingAccounts.has(group.account.toLowerCase())) return;
        group.entries.sort((a, b) => a.date.localeCompare(b.date));
        const first = group.entries[0];
        const [year, monthNumber, day] = first.date.split('-').map(Number);
        const month = MONTH_ORDER[monthNumber - 1];
        const key = `${year}-${month}`;
        if (!month || !state.monthlyBills?.[key]) return;
        const cycleKey = 'cycle1st';
        const seriesId = `restored-personal-${Math.random().toString(36).substr(2, 9)}`;
        const bill = normalizeBillSplitterItem({
            id: seriesId,
            recurringSeriesId: seriesId,
            account: group.account,
            category: 'expense',
            budgetAmount: group.amount,
            paymentAmount: group.amount,
            occurrencePaymentAmount: group.amount,
            frequencyAmount: group.amount,
            samePaymentAmount: true,
            dueDay: day,
            paymentSource: 'jasonChecking',
            entryType: 'actual',
            ownership: 'jason',
            cycleAllocation: '1st',
            budgetFrequency: 'monthly',
            chargeFrequency: 'monthly',
            isRecurring: true,
            recurringStartMonth: first.date.slice(0, 7),
            recurringEndMonth: ''
        }, cycleKey);
        state.monthlyBills[key][cycleKey].bills.push(bill);
        syncBillLedgerEntry(bill, year, month);
        propagateRecurringBillChanges(bill, year, month);
        existingAccounts.add(group.account.toLowerCase());
        restored += 1;
    });
    return restored;
}
function recalculateBillCycleTotals(mBills) {
    const allBills = ['cycle1st', 'cycle15th'].flatMap(cycleKey => (mBills[cycleKey]?.bills || []).map(bill => normalizeBillSplitterItem(bill, cycleKey)));
    ['cycle1st', 'cycle15th'].forEach(cycleKey => {
        const cycle = mBills[cycleKey];
        if (!cycle) return;
        cycle.totals = cycle.totals || {};
        cycle.totals.billsTotal = allBills.reduce((sum, bill) => {
            if (bill.cycleAllocation === 'both') return sum + bill.budgetAmount / 2;
            const assigned = bill.cycleAllocation === '15th' ? 'cycle15th' : 'cycle1st';
            return sum + (assigned === cycleKey ? bill.budgetAmount : 0);
        }, 0);
    });
}

function propagateRecurringBillChanges(editedBill, year, month, previousBill = null) {
    const seriesId = editedBill.recurringSeriesId || editedBill.id;
    const currentIndex = year * 12 + MONTH_ORDER.indexOf(month);
    const requestedStartIndex = getBillRecurrenceMonthIndex(editedBill.recurringStartMonth);
    const requestedEndIndex = getBillRecurrenceMonthIndex(editedBill.recurringEndMonth);
    if (!state.billRecurrenceTemplates) state.billRecurrenceTemplates = {};
    if (!state.billRecurrenceStops) state.billRecurrenceStops = {};

    if (editedBill.isRecurring) {
        editedBill.recurringSeriesId = seriesId;
        delete state.billRecurrenceStops[seriesId];
        state.billRecurrenceTemplates[seriesId] = {
            bill: normalizeBillSplitterItem({ ...editedBill, recurringSeriesId: seriesId }),
            cycleKey: editedBill.cycleAllocation === '15th' ? 'cycle15th' : 'cycle1st',
            startIndex: requestedStartIndex ?? currentIndex,
            endIndex: requestedEndIndex
        };
    } else {
        state.billRecurrenceStops[seriesId] = currentIndex + 1;
        delete state.billRecurrenceTemplates[seriesId];
    }

    Object.entries(state.monthlyBills || {}).forEach(([key, monthData]) => {
        const [keyYear, keyMonth] = key.split('-');
        const periodIndex = Number(keyYear) * 12 + MONTH_ORDER.indexOf(keyMonth);
        // Only the month actually being edited is skipped (the caller updates that one directly) —
        // every OTHER already-existing month is now propagated to, past or future, not just months
        // after the one being edited. A recurring bill backdated to an earlier recurringStartMonth
        // (e.g. added in September but set to start in July) used to never reach already-generated
        // past months at all, since this only ever walked forward from "the month you happened to be
        // looking at when you made the edit" — meaning a Clear Local Data + Pull from Google Sheets
        // (which regenerates every month fresh from the current templates, uniformly) would correctly
        // backfill June/July/August, while the live app's own accumulated data never did, permanently
        // disagreeing with a fresh regenerate for any bill ever backdated this way — confirmed live,
        // 2026-08-01. isBillActiveForPeriod below still bounds this to the bill's own
        // recurringStartMonth/recurringEndMonth, so a month genuinely before the series started is
        // untouched either way. Per explicit user decision, this does mean editing a recurring bill
        // can now change what already posted to the ledger in a past month (see syncBillLedgerEntry's
        // own overriddenDates guard, which still protects any occurrence the user individually
        // edited/deleted by hand from being clobbered).
        if (periodIndex === currentIndex) return;
        ['cycle1st', 'cycle15th'].forEach(cycleKey => {
            const list = monthData?.[cycleKey]?.bills || [];
            for (let i = list.length - 1; i >= 0; i--) {
                const candidate = normalizeBillSplitterItem(list[i], cycleKey);
                const sameSeries = (candidate.recurringSeriesId || candidate.id) === seriesId;
                const sameLegacyBill = previousBill && getBillLegacyRecurrenceKey(candidate) === getBillLegacyRecurrenceKey(previousBill);
                if (!sameSeries && !sameLegacyBill) continue;
                removeBillLedgerEntries(candidate.id, Number(keyYear), keyMonth, candidate);
                list.splice(i, 1);
            }
        });
        if (editedBill.isRecurring && isBillActiveForPeriod(editedBill, Number(keyYear), keyMonth)) {
            const targetCycle = editedBill.cycleAllocation === '15th' ? 'cycle15th' : 'cycle1st';
            const futureBill = recalculateBillBudgetForPeriod({ ...editedBill, id: `${seriesId}-${keyYear}-${keyMonth}`, recurringSeriesId: seriesId }, Number(keyYear), keyMonth, targetCycle);
            monthData[targetCycle].bills.push(futureBill);
            syncBillLedgerEntry(futureBill, Number(keyYear), keyMonth);
        }
        recalculateBillCycleTotals(monthData);
    });
}

// One-time maintenance action (Sync Settings > Data Maintenance): re-runs propagateRecurringBillChanges()
// / updateFutureAllocationOccurrences() for every existing recurring bill AND allocation template
// against every already-existing month, catching the live app up to what a fresh Clear Local Data +
// Pull from the Sheet would produce from scratch. Needed because both of those only ever propagated a
// change to months AFTER whichever one you were viewing when you made it (until the backfill fixes
// above) — a bill/allocation edited or backdated to an earlier start month never reached
// already-generated past months on its own, and nothing else in the app retroactively revisits old
// months to catch them up automatically. `currentIndex: 0` deliberately can't match any real
// "YYYY-Mon" month key's own index (those start in the tens of thousands), so nothing gets excluded
// as "the month being edited" — every existing month is evaluated for every series.
function resyncAllRecurringBillsAcrossAllMonths() {
    let seriesCount = 0;
    Object.entries(state.billRecurrenceTemplates || {}).forEach(([seriesId, template]) => {
        if (!template?.bill) return;
        // Mortgage bills and Bill Tracker settings regenerate from their own dedicated sources
        // (syncMortgageLoansToAllMonthsIfChanged/syncBillTrackerBillsToAllMonthsIfChanged) every time
        // autopopulateBillsForMonth() runs — routing them through here too would fight that source of
        // truth instead of complementing it.
        if (template.bill.isMortgage || template.bill.billTrackerSettingId) return;
        // A series can have a lingering template entry even after being stopped (confirmed live —
        // billRecurrenceStops and billRecurrenceTemplates aren't always mutually exclusive in
        // practice). Forcing `isRecurring: true` unconditionally here would un-stop it by calling
        // propagateRecurringBillChanges() with isRecurring true, which deletes the stop as a side
        // effect — respect an existing stop and leave it alone instead of reviving it.
        if (state.billRecurrenceStops?.[seriesId] !== undefined) return;
        propagateRecurringBillChanges({ ...template.bill, recurringSeriesId: seriesId }, 0, MONTH_ORDER[0]);
        seriesCount++;
    });
    // No separate autopopulateBillsForMonth() pass here — propagateRecurringBillChanges() above
    // already inserts/removes each series' bill and its ledger entry for every month itself.
    // Running autopopulateBillsForMonth() again afterward re-triggers syncBillLedgerEntry() a
    // second time per bill and produced a genuine duplicate real transaction (confirmed live: two
    // different ledger entries for the same iCloud Storage charge, different random ids) —
    // recalculateBillCycleTotals(monthData) inside the loop above is already all that's needed to
    // keep each month's totals correct after the bill list changes.

    // Allocations (Bill Splitter's Jason/Asia contribution rows) have the exact same forward-only
    // propagation gap, just via updateFutureAllocationOccurrences() instead — confirmed as the ACTUAL
    // root cause of a real user-reported mismatch, 2026-08-01: a "base" contribution row was created
    // once with the template's old amount and never refreshed after the template was later edited,
    // since applyAllocationTemplatesForMonth() only ever ADDS a contribution when one doesn't already
    // exist for that role/month — it never overwrites an existing one with a newer template value.
    // updateFutureAllocationOccurrences() itself deletes the stale row and regenerates it fresh from
    // the current template, so unlike bills there's no separate "don't reactivate a stop" concern
    // here (a stopped series' own canGenerate() check inside applyAllocationTemplatesForMonth already
    // keeps it from regenerating) and no risk of a duplicate real transaction (allocations don't post
    // real ledger entries the way `entryType: 'actual'` bills do).
    let allocationSeriesCount = 0;
    Object.entries(state.allocationTemplates || {}).forEach(([seriesId, template]) => {
        updateFutureAllocationOccurrences(seriesId, 'base', 0, MONTH_ORDER[0]);
        if (template.offsetEnabled) updateFutureAllocationOccurrences(seriesId, 'offset', 0, MONTH_ORDER[0]);
        allocationSeriesCount++;
    });

    saveDatabase();
    return { billSeriesCount: seriesCount, allocationSeriesCount };
}

function getBillChargeDate(year, month, dueDay) {
    const monthIndex = MONTH_ORDER.indexOf(month);
    const lastDay = new Date(year, monthIndex + 1, 0).getDate();
    const day = Math.min(lastDay, Math.max(1, Number(dueDay) || 1));
    return `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

