// back to the card's own Statement Closing Day (so the fee always lands on a real statement date and
// automatically follows if the statement day is later changed, rather than being pinned to an
// independent date that can drift out of sync with the card's actual cycle) — idempotent (keyed by
// year) and self-healing (reposts if the configured amount/month/day changed since the last post).
function applyCardAnnualFeeForMonth(card, year, month) {
    if (!card.hasAnnualFee || !card.annualFeeMonth || !(Number(card.annualFeeAmount) > 0)) return;
    const monthIndex = MONTH_ORDER.indexOf(month);
    if (MONTH_ORDER.indexOf(card.annualFeeMonth) !== monthIndex) return;
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    const day = Math.min(Number(card.annualFeeDay) || Number(card.statementDay) || 1, daysInMonth);
    const dateStr = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const key = `${year}-${month}`;
    const linkId = `annual-fee-${card.id}-${year}`;

    // Don't back-post before the configured First Fee Date — otherwise adding the fee retroactively
    // posts it into every past year/month this card's calendar has ever been viewed for, not just
    // from whenever the fee actually started applying. Also removes a prior post that's now before
    // the date, in case the user added/moved the First Fee Date after the fee already posted once.
    if (card.annualFeeStartDate && dateStr < card.annualFeeStartDate) {
        const existingList = state.cardCalendars[card.id]?.[key];
        if (existingList) {
            const idx = existingList.findIndex(tx => tx.annualFeeId === linkId);
            if (idx > -1) existingList.splice(idx, 1);
        }
        return;
    }

    if (!state.cardCalendars[card.id]) state.cardCalendars[card.id] = {};
    if (!state.cardCalendars[card.id][key]) state.cardCalendars[card.id][key] = [];
    const cardList = state.cardCalendars[card.id][key];
    const amount = -Math.abs(Number(card.annualFeeAmount) || 0);
    const existing = cardList.find(tx => tx.annualFeeId === linkId);
    if (existing) {
        if (existing.date !== dateStr || existing.amount !== amount) {
            existing.date = dateStr;
            existing.amount = amount;
        }
        return;
    }
    cardList.push({
        id: 'c-' + Math.random().toString(36).substr(2, 9),
        date: dateStr,
        description: `${card.name} Annual Fee`,
        amount,
        annualFeeId: linkId,
        isAnnualFee: true
    });
}

// Posts an installment loan's monthly estimated interest as a stable, read-only ledger row on
// the loan's configured closing/statement day. Rebuilding removes the generated row first, so
// edited, removed, or early payments immediately recalculate the interest and stop it after payoff.
function postInstallmentLoanInterestForMonth(loanId, year, month) {
    const loan = state.loans.find(item => item.id === loanId && item.type === 'loan');
    if (!loan) return;
    const monthIndex = MONTH_ORDER.indexOf(month);
    if (monthIndex < 0) return;
    const today = new Date();
    if (year * 12 + monthIndex < today.getFullYear() * 12 + today.getMonth()) return;

    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    const closingDay = Math.min(31, Math.max(1, Number(loan.statementDay) || 1), daysInMonth);
    const closingDate = new Date(year, monthIndex, closingDay);
    const closingDateStr = formatLocalDate(closingDate);
    const previousMonthDate = new Date(year, monthIndex - 1, 1);
    const previousDaysInMonth = new Date(previousMonthDate.getFullYear(), previousMonthDate.getMonth() + 1, 0).getDate();
    const previousClosingDay = Math.min(31, Math.max(1, Number(loan.statementDay) || 1), previousDaysInMonth);
    const previousClosingDate = new Date(previousMonthDate.getFullYear(), previousMonthDate.getMonth(), previousClosingDay);
    const previousClosingDateStr = formatLocalDate(previousClosingDate);
    const key = `${year}-${month}`;
    if (!state.cardCalendars[loanId]) state.cardCalendars[loanId] = {};
    if (!state.cardCalendars[loanId][key]) state.cardCalendars[loanId][key] = [];
    const loanList = state.cardCalendars[loanId][key];
    const stableId = `loan-interest-${loanId}-${closingDateStr}`;
    if (!state.cardChargeSkips) state.cardChargeSkips = {};

    for (let i = loanList.length - 1; i >= 0; i--) {
        if (loanList[i].isLoanEstimatedInterest && !loanList[i].overridden) loanList.splice(i, 1);
    }
    if (state.cardChargeSkips[stableId] || loanList.some(item => item.id === stableId && item.overridden)) return;

    const allTransactions = Object.values(state.cardCalendars?.[loanId] || {})
        .flatMap(list => list || [])
        .filter(tx => !tx.billOccurrenceDeleted && tx.date && Number.isFinite(Number(tx.amount)));

    // Loan interest accrues on each day's actual ledger balance, using APR / 365. Payments made
    // during the statement cycle therefore reduce interest for every day after they post. The
    // closing-day payment and a closing-day reconciliation are applied after interest closes.
    let dailyBalance = Number(loan.startBal) || 0;
    allTransactions.forEach(tx => {
        if (tx.date > previousClosingDateStr || tx.isLoanEstimatedInterest && tx.date === closingDateStr) return;
        const amount = Number(tx.amount);
        dailyBalance += amount < 0 ? Math.abs(amount) : -Math.abs(amount);
    });
    dailyBalance = Math.max(0, dailyBalance);

    const dailyRate = Math.max(0, Number(loan.interestRate) || 0) / 100 / 365;
    let accruedInterest = 0;
    let accruedDays = 0;
    const cursor = new Date(previousClosingDate);
    cursor.setDate(cursor.getDate() + 1);
    while (cursor <= closingDate) {
        const dateStr = formatLocalDate(cursor);
        allTransactions.forEach(tx => {
            if (tx.date !== dateStr || tx.isLoanEstimatedInterest) return;
            const amount = Number(tx.amount);
            if (dateStr === closingDateStr && (amount > 0 || tx.isBalanceAdjustment)) return;
            dailyBalance += amount < 0 ? Math.abs(amount) : -Math.abs(amount);
        });
        dailyBalance = Math.max(0, dailyBalance);
        accruedInterest += dailyBalance * dailyRate;
        accruedDays += 1;
        cursor.setDate(cursor.getDate() + 1);
    }

    let balanceBeforeInterest = Number(loan.startBal) || 0;
    allTransactions.forEach(tx => {
        if (tx.date > closingDateStr || tx.isLoanEstimatedInterest && tx.date === closingDateStr) return;
        const amount = Number(tx.amount);
        if (tx.date === closingDateStr && (amount > 0 || tx.isBalanceAdjustment)) return;
        balanceBeforeInterest += amount < 0 ? Math.abs(amount) : -Math.abs(amount);
    });
    balanceBeforeInterest = Math.max(0, balanceBeforeInterest);
    const interest = Math.round(accruedInterest * 100) / 100;
    if (balanceBeforeInterest <= 0.01 || interest <= 0.005) return;

    loanList.push({
        id: stableId,
        date: closingDateStr,
        description: 'Estimated Interest Charge',
        merchant: loan.name,
        amount: -interest,
        transactionKind: 'interest',
        isEstimatedInterest: true,
        isLoanEstimatedInterest: true,
        interestMethod: 'dailyBalance',
        interestPeriodStart: previousClosingDateStr,
        interestPeriodDays: accruedDays,
        dailyRate
    });
}

// Posts a card's statement-date interest and payment-plan fees as real, individually visible
// charges on the card's own register/calendar — previously these only ever existed baked into
// computeAllEstimatedBalancesForCard's projected running-balance column, invisible as actual line
// items anywhere (confirmed as a real gap 2026-07-23: user wanted to SEE what a statement's
// interest/fees actually were, not just the net effect on a balance estimate). Mirrors the exact
// interest/fee formulas already used there — see the alreadyPostedReal guard in that function for
// how double-counting between "already posted for real" and "still just estimated" is avoided.
// Posts for past AND future statement dates (self-healing/recomputed on every call), matching how
// every other automatic charge in this app already projects forward (ensureAutomaticCardPaymentForMonth
// generates next month's payment before it's "actually happened" too) — gating this one specifically
// on "already occurred" was the reason a freshly-added payment plan's fee/interest wasn't showing up
// until the statement date arrived in real time, confirmed as a bug 2026-07-23.
// A charge card (isChargeCard) structurally cannot carry a revolving balance or accrue interest — it
// must be paid in full each statement — so standard/promo interest is skipped for one entirely, even
// though its own payment plans (e.g. an Amex "Plan It") still charge their real monthly fee.
function postCardStatementChargesForMonth(cardId, year, month) {
    const card = state.loans.find(c => c.id === cardId);
    if (!card || card.type !== 'credit') return;
    const monthIndex = MONTH_ORDER.indexOf(month);
    // Never fabricate interest/fee history for a month before the current real one. A card's
    // startBal/currentBal already reflects whatever interest has really accrued up to now (the user
    // maintains that number by hand against their actual statement) — retroactively inventing NEW
    // interest transactions for already-past months double-counts on top of that and inflates the
    // reconciled currentBal far beyond reality, compounding for every already-materialized past month
    // (confirmed as a real bug 2026-07-23: a card with several expired 0% balance-transfer promos got
    // months of phantom standard-rate interest backfilled the moment autopopulateBillsForMonth ran
    // for those already-materialized past months, which happens on nearly every render). Future
    // months are fine to project forward (matching every other automatic charge in this app), and the
    // current month is fine since that statement is either happening today or about to.
    const today = new Date();
    if (year * 12 + monthIndex < today.getFullYear() * 12 + today.getMonth()) return;
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    const statementDay = Math.min(Number(card.statementDay) || 1, daysInMonth);
    const statementDateStr = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(statementDay).padStart(2, '0')}`;

    const key = `${year}-${month}`;
    if (!state.cardCalendars[cardId]) state.cardCalendars[cardId] = {};
    if (!state.cardCalendars[cardId][key]) state.cardCalendars[cardId][key] = [];
    const cardList = state.cardCalendars[cardId][key];

    // Every posted fee/interest charge gets a STABLE id (not random) so a user's own edit (date,
    // amount, description) or deletion can be recognized and preserved across this function's
    // otherwise-blind remove-and-regenerate cycle, the same way automaticPaymentOverridden protects
    // an edited automatic payment. `overridden: true` on an existing entry means leave it exactly
    // as the user left it; state.cardChargeSkips[stableId] means the user deleted it — don't recreate.
    if (!state.cardChargeSkips) state.cardChargeSkips = {};
    const planFeeStableId = planId => `planfee-${planId}-${statementDateStr}`;
    const interestStableId = `interest-${cardId}-${statementDateStr}`;

    for (let i = cardList.length - 1; i >= 0; i--) {
        const item = cardList[i];
        if ((item.isEstimatedInterest || item.isPlanFee) && !item.overridden) cardList.splice(i, 1);
    }

    const balanceBeforeCharges = calculateCardLedgerBalance(cardId, statementDateStr);
    const statementDateObj = new Date(statementDateStr + 'T00:00:00');
    // A store card's own name rarely means anything on its own calendar (it's already the only
    // account shown there) — its storeName is the more useful "merchant" to show on these
    // auto-generated fee/interest chips, same as a manually-entered charge on that card would get.
    const autoChargeMerchant = card.isStoreCard && String(card.storeName || '').trim() ? card.storeName : card.name;

    // One charge PER plan (named after the plan), not a single lump sum — a card with several plans
    // running at once (e.g. Southwest with 7) needs each one individually visible to actually be
    // useful, not just a combined "Payment Plan Fee(s)" total with no way to tell which plan it came
    // from or when any one of them finishes.
    const plans = deriveCardPaymentPlanBalances(cardId, statementDateStr);
    let planFeesTotal = 0;
    let planBalancesTotal = 0;
    plans.forEach(plan => {
        if (plan.currentBalance <= 0.005 || statementDateStr < plan.startDate) return;
        planBalancesTotal += plan.currentBalance;
        if (Number(plan.monthlyFee) > 0.005) {
            planFeesTotal += Number(plan.monthlyFee);
            const stableId = planFeeStableId(plan.id);
            if (state.cardChargeSkips[stableId]) return;
            if (cardList.some(tx => tx.id === stableId)) return;
            cardList.push({
                id: stableId,
                date: statementDateStr,
                description: `${plan.name} Plan Fee`,
                merchant: autoChargeMerchant,
                amount: -Math.round(Number(plan.monthlyFee) * 100) / 100,
                isPlanFee: true,
                planId: plan.id,
                owner: resolvePaymentPlanOwnership(plan, card)
            });
        }
    });

    const balanceAfterFees = balanceBeforeCharges + planFeesTotal;
    if (balanceAfterFees > 0.01 && !card.isChargeCard && card.paymentStrategy !== 'balance') {
        const interestAccruingBalance = Math.max(0, balanceAfterFees - planBalancesTotal);
        let promoInterest = 0;
        let activePromosBalanceSum = 0;
        (card.promos || []).forEach(promo => {
            if (promo.expDate) {
                const expTime = new Date(promo.expDate + 'T00:00:00').getTime();
                if (statementDateObj.getTime() <= expTime) {
                    const pBal = Number(promo.currentBalance ?? promo.amount) || 0;
                    promoInterest += pBal * (Number(promo.rate) / 12 / 100);
                    activePromosBalanceSum += pBal;
                }
            }
        });
        let purchaseRate = (card.paymentStrategy === 'balance') ? 0 : (Number(card.interestRate) || 0);
        if (card.promoActive && card.promoExpDate) {
            const promoExpTime = new Date(card.promoExpDate + 'T00:00:00').getTime();
            if (statementDateObj.getTime() <= promoExpTime) purchaseRate = Number(card.promoRate) || 0;
        }
        const nonPromoBalance = Math.max(0, interestAccruingBalance - activePromosBalanceSum);
        const standardInterest = nonPromoBalance * (purchaseRate / 12 / 100);
        const totalInterest = standardInterest + promoInterest;
        if (totalInterest > 0.005 && !state.cardChargeSkips[interestStableId] && !cardList.some(tx => tx.id === interestStableId)) {
            cardList.push({
                id: interestStableId,
                date: statementDateStr,
                description: 'Estimated Interest Charge',
                merchant: autoChargeMerchant,
                amount: -Math.round(totalInterest * 100) / 100,
                isEstimatedInterest: true
            });
        }
    }
}


// Rebuilds every materialized current/future statement after a card transaction changes. Because
// plan balances come from the ledger, this removes fees after an early payoff and restores them if
// that payoff is later reduced, moved, or deleted.
function refreshMaterializedCardStatementCharges(cardId) {
    const calendar = state.cardCalendars?.[cardId] || {};
    const today = new Date();
    const currentMonthIndex = today.getFullYear() * 12 + today.getMonth();
    const months = Object.keys(calendar)
        .map(key => {
            const match = key.match(/^(\d{4})-([A-Z][a-z]{2})$/);
            if (!match) return null;
            const monthIndex = MONTH_ORDER.indexOf(match[2]);
            if (monthIndex < 0) return null;
            return { key, year: Number(match[1]), month: match[2], index: Number(match[1]) * 12 + monthIndex };
        })
        .filter(item => item && item.index >= currentMonthIndex)
        .sort((a, b) => a.index - b.index);

    months.forEach(item => rebuildDebtMonthFinance(cardId, item.year, item.month));
    delete _cardBalanceEstimatesCache[cardId];
}

function autopopulateBillsForMonth(year, month) {
    const key = `${year}-${month}`;
    const mBills = state.monthlyBills[key];
    if (!mBills) return;
    inheritRecurringBillsForMonth(year, month);
    const targetIndex = year * 12 + MONTH_ORDER.indexOf(month);
    ['cycle1st', 'cycle15th'].forEach(cycleKey => {
        mBills[cycleKey].bills = (mBills[cycleKey].bills || []).filter(bill => {
            const stoppedAt = state.billLegacyRecurrenceStops?.[getBillLegacyRecurrenceKey(bill)];
            if (!Number.isFinite(Number(stoppedAt)) || Number(stoppedAt) > targetIndex) return true;
            removeBillLedgerEntries(bill.id, year, month, bill, true);
            return false;
        });
        mBills[cycleKey].bills = (mBills[cycleKey].bills || []).map(bill => recalculateBillBudgetForPeriod(bill, year, month, cycleKey));
        mBills[cycleKey].bills.forEach(bill => syncBillLedgerEntry(bill, year, month));
    });
    syncMortgageLoansToAllMonthsIfChanged();
    syncBillTrackerBillsToAllMonthsIfChanged();
    // Both installment loans AND credit cards with an automatic payment strategy need this
    // generated here, not left to only happen when the user opens that specific card's own
    // dashboard page for this month — a card the user rarely visits (e.g. one on an
    // interest-saving auto-pay strategy they set and forgot about) would otherwise silently never
    // get its payment posted anywhere at all, joint or personal, confirmed as a real bug 2026-07-23
    // (American Express Platinum's interestSaving payments never appeared in the joint register
    // because its own Credit Cards page was never opened for the months in question).
    // ensureAutomaticCardPaymentForMonth() already no-ops for a card with paymentStrategy 'none',
    // so this is safe to call unconditionally for every non-mortgage loan/card.
    state.loans.filter(l => !l.isMortgage).forEach(loan => {
        if (loan.type === 'credit') applyCardAnnualFeeForMonth(loan, year, month);
        rebuildDebtMonthFinance(loan.id, year, month);
    });
    syncCardPaymentSplitterRowsForMonth(year, month);
    recalculateBillCycleTotals(mBills);
}

function calculateCardLedgerBalance(cardId, throughDate = formatLocalDate(new Date())) {
    const card = state.loans.find(c => c.id === cardId);
    if (!card) return 0;

    let balance = Number(card.startBal) || 0;
    const cardCal = state.cardCalendars?.[cardId] || {};

    Object.values(cardCal).forEach(txs => {
        (txs || []).forEach(tx => {
            if (tx.billOccurrenceDeleted) return;
            const amount = Number(tx.amount);
            if (!Number.isFinite(amount) || !tx.date || tx.date > throughDate) return;
            balance += amount < 0 ? Math.abs(amount) : -Math.abs(amount);
        });
    });

    // Intentionally not clamped to 0: an overpayment should show up as a negative balance
    // (a credit owed back), not silently disappear. UI display code is responsible for
    // rendering a negative balance as a credit rather than treating it as an error.
    return balance;
}

// Full-statement-balance automatic payments are calculated from the day before the statement
// closes so ordinary purchases posting on the closing date can remain in the next cycle. Interest
// and payment-plan fees generated by Budgetify are different: they are statement charges and must
// be included in the payment for that statement. Leaving them out creates a small carried balance
// that accrues another interest charge forever.
function getGeneratedStatementChargesTotal(cardId, statementDateStr) {
    return Object.values(state.cardCalendars?.[cardId] || {})
        .flatMap(list => list || [])
        .filter(tx =>
            !tx.billOccurrenceDeleted
            && tx.date === statementDateStr
            && (tx.isEstimatedInterest || tx.isPlanFee)
            && Number(tx.amount) < 0
        )
        .reduce((sum, tx) => sum + Math.abs(Number(tx.amount) || 0), 0);
}

let _cardBalanceEstimatesCache = {};

// Re-simulates a card's entire transaction history day-by-day (interest, promos,
// payment plans), so it's cached per card and only recomputed when saveDatabase()
// clears the cache — otherwise every keystroke in the list filters re-ran it.
function computeAllEstimatedBalancesForCard(cardId) {
    if (_cardBalanceEstimatesCache[cardId]) return _cardBalanceEstimatesCache[cardId];

    const card = state.loans.find(c => c.id === cardId);
    if (!card) return { estimates: {}, activePlans: [] };

    const cardCal = state.cardCalendars[cardId] || {};
    const allTxs = [];
    Object.keys(cardCal).forEach(key => {
        (cardCal[key] || []).forEach(tx => {
            if (tx.billOccurrenceDeleted) return;
            allTxs.push({ ...tx });
        });
    });

    if (allTxs.length === 0) return { estimates: {}, activePlans: [] };
    // Must use the EXACT same tie-break as the ledger's own default display sort
    // (compareTransactionsChronologically, in renderCCCardList) for same-date transactions — this
    // used to tie-break by amount sign (charges before payments) instead, which is a DIFFERENT order
    // than what the table actually displays whenever same-date entries aren't naturally in that
    // order already. The two orderings disagreeing is exactly what made a same-date row's displayed
    // "ending balance" not connect to the very next displayed row's "starting balance" — the balance
    // chain was computed in one order while the rows were shown in another.
    allTxs.sort(compareTransactionsChronologically);

    let estBalance = Number(card.startBal) || 0;
    const estimates = {};
    const firstDate = new Date(allTxs[0].date + 'T00:00:00');
    const lastDate = new Date(allTxs[allTxs.length - 1].date + 'T00:00:00');
    const txsByDate = {};
    allTxs.forEach(tx => {
        if (!txsByDate[tx.date]) txsByDate[tx.date] = [];
        txsByDate[tx.date].push(tx);
    });

    const currentDate = new Date(firstDate);
    const statementDay = Number(card.statementDay) || 1;
    let lastInterestMonthYear = '';
    const todayForGuard = new Date();
    const todayMonthIndexForGuard = todayForGuard.getFullYear() * 12 + todayForGuard.getMonth();

    while (currentDate <= lastDate) {
        const dateStr = formatLocalDate(currentDate);
        const dayOfMonth = currentDate.getDate();
        const currentMonthYear = `${currentDate.getFullYear()}-${currentDate.getMonth()}`;
        const dayTxs = txsByDate[dateStr] || [];

        dayTxs.forEach(tx => {
            const amount = Number(tx.amount) || 0;
            estBalance += amount < 0 ? Math.abs(amount) : -Math.abs(amount);
            estimates[tx.id] = estBalance;
        });

        if (dayOfMonth === statementDay && lastInterestMonthYear !== currentMonthYear) {
            lastInterestMonthYear = currentMonthYear;
            const plansAtStatement = deriveCardPaymentPlanBalances(cardId, dateStr).filter(plan =>
                plan.currentBalance > 0.005
                && dateStr > plan.balanceAsOfDate
                && dateStr >= plan.startDate
            );
            const activePlansFees = plansAtStatement.reduce((sum, plan) => sum + (Number(plan.monthlyFee) || 0), 0);
            const activePlansBalanceSum = plansAtStatement.reduce((sum, plan) => sum + (Number(plan.currentBalance) || 0), 0);

            // Posted fees and interest are already present in the day's ledger transactions.
            // Only estimate them inline for a future statement that has no generated charge rows.
            const alreadyPostedReal = dayTxs.some(tx => tx.isEstimatedInterest || tx.isPlanFee);
            // Mirror postCardStatementChargesForMonth's own "never fabricate interest/fee history for
            // a month before the current real one" rule (see that function's comment for the real
            // 2026-07-23 incident this guards against — retroactively inventing interest for an
            // already-past, never-materialized statement double-counts on top of whatever the user's
            // startBal/currentBal already reflects). Without this same guard here, this DISPLAY-facing
            // estimate silently invented that past interest/fee anyway, so the ledger's shown Ending
            // Balance disagreed with calculateCardLedgerBalance (which the automatic-payment engine
            // reads) by exactly the invented amount — confirmed as a real bug, 2026-08-02: a card's
            // list view showed a $0.00 June balance while the engine correctly saw an $89.38 credit
            // from July 2026's statement never actually being posted, so the two disagreed about
            // whether a payment was owed and by how much for every month after.
            const isPastMonth = (currentDate.getFullYear() * 12 + currentDate.getMonth()) < todayMonthIndexForGuard;
            if (!alreadyPostedReal && card.type !== 'loan' && !isPastMonth) {
                estBalance += activePlansFees;

                // Mirror postCardStatementChargesForMonth's `card.paymentStrategy !== 'balance'`
                // exclusion — a Full Card Balance card is paid in full every cycle by design, so it
                // never actually carries interest, and the real posting function knows that. Without
                // the same check here, this display-only estimate invented interest for a statement
                // that the real function would never post any for, creating exactly the kind of
                // invisible jump between one month's shown Ending Balance and the next month's shown
                // Starting Balance that a Full Balance card's engine-computed payment doesn't include
                // — confirmed as a real bug, 2026-08-02 (a $1.53 gap with no corresponding ledger row).
                if (estBalance > 0.01 && !card.isChargeCard && card.paymentStrategy !== 'balance') {
                    const interestAccruingBalance = Math.max(0, estBalance - activePlansBalanceSum);
                    let promoInterest = 0;
                    let activePromosBalanceSum = 0;

                    (card.promos || []).forEach(promo => {
                        if (!promo.expDate) return;
                        const expTime = new Date(promo.expDate + 'T00:00:00').getTime();
                        if (currentDate.getTime() <= expTime) {
                            const promoBalance = Number(promo.currentBalance ?? promo.amount) || 0;
                            promoInterest += promoBalance * (Number(promo.rate) / 12 / 100);
                            activePromosBalanceSum += promoBalance;
                        }
                    });

                    let purchaseRate = Number(card.interestRate) || 0;
                    if (card.promoActive && card.promoExpDate) {
                        const promoExpTime = new Date(card.promoExpDate + 'T00:00:00').getTime();
                        if (currentDate.getTime() <= promoExpTime) purchaseRate = Number(card.promoRate) || 0;
                    }

                    const nonPromoBalance = Math.max(0, interestAccruingBalance - activePromosBalanceSum);
                    estBalance += nonPromoBalance * (purchaseRate / 12 / 100) + promoInterest;
                }
            }
            // Bug fix: this used to blindly overwrite EVERY transaction dated the statement day with
            // the single post-adjustment estBalance, clobbering the correct per-transaction values
            // the loop just above had already set — real transactions were already given their own
            // sequential ending balance up there (each incremented by only its own amount), so two
            // different-amount charges dated on the statement day both ended up showing the exact
            // same "ending balance." A projected/virtual fee-or-interest amount (the !alreadyPostedReal
            // case) has no transaction id of its own to attach to anyway — `estBalance` already
            // carries the adjustment forward correctly into every subsequent day's calculations via
            // this same `let` variable, with no need to stamp it onto any specific row here.
        }

        currentDate.setDate(currentDate.getDate() + 1);
    }

    const lastDateStr = formatLocalDate(lastDate);
    const activePlans = deriveCardPaymentPlanBalances(cardId, lastDateStr);
    const result = { estimates, activePlans };
    _cardBalanceEstimatesCache[cardId] = result;
    return result;
}

function projectInstallmentLoanPayoffPath(loanId, monthsCount, startPayDateStr, additionalMonthlyAmount, extraScheduledAmount = 0, isFutureSchedule = false, dynamicCapMonths = 600) {
    const loan = state.loans.find(item => item.id === loanId && item.type === 'loan');
    if (!loan) return { path: [], payoffDate: 'Paid Off', totalPayments: 0, additionalPayments: [] };

    const today = new Date();
    const todayStr = formatLocalDate(today);
    const startPayDate = startPayDateStr
        ? new Date(startPayDateStr + 'T00:00:00')
        : new Date(today.getFullYear(), today.getMonth() + 1, Number(loan.dueDay) || 1);
    const isDynamicPayoff = !isFutureSchedule || monthsCount <= 0;
    const projectionMonths = isDynamicPayoff ? Math.max(1, dynamicCapMonths) : Math.max(1, monthsCount || 12);
    const endDate = new Date(startPayDate.getFullYear(), startPayDate.getMonth() + projectionMonths - 1, startPayDate.getDate());

    const futureTxs = [];
    Object.values(state.cardCalendars?.[loanId] || {}).forEach(list => {
        (list || []).forEach(tx => {
            if (tx.billOccurrenceDeleted || tx.isEstimatedInterest || !tx.date || tx.date <= todayStr) return;
            futureTxs.push({ ...tx });
        });
    });
    futureTxs.sort((a, b) => String(a.date).localeCompare(String(b.date)));
    const txsByDate = {};
    const autoPaymentMonths = new Set();
    futureTxs.forEach(tx => {
        if (!txsByDate[tx.date]) txsByDate[tx.date] = [];
        txsByDate[tx.date].push(tx);
        if (tx.amount > 0 && tx.isAutomaticCardPayment) autoPaymentMonths.add(tx.date.slice(0, 7));
    });

    let balance = Math.max(0, calculateCardLedgerBalance(loanId, todayStr));
    const monthlyRate = Math.max(0, Number(loan.interestRate) || 0) / 1200;
    const dueDay = Math.min(31, Math.max(1, Number(loan.dueDay) || 1));
    const closingDay = Math.min(31, Math.max(1, Number(loan.statementDay) || 1));
    const monthlyPayment = getLoanDebtPaymentAmount(loan);
    const monthlyBalances = [];
    const additionalPayments = [];
    let currentDate = new Date(todayStr + 'T00:00:00');
    currentDate.setDate(currentDate.getDate() + 1);
    let lastInterestMonthYear = '';
    let totalPaid = 0;
    let payoffDate = balance <= 0.01 ? new Date(today) : null;

    while (currentDate <= endDate) {
        const dateStr = formatLocalDate(currentDate);
        const monthKey = dateStr.slice(0, 7);
        const monthYearKey = `${currentDate.getFullYear()}-${currentDate.getMonth()}`;
        const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
        const paymentDay = Math.min(dueDay, daysInMonth);
        const interestDay = Math.min(closingDay, daysInMonth);

        // Match the visible read-only ledger row: estimate monthly interest on the configured
        // closing date, before same-day payments when both dates are the same.
        if (currentDate.getDate() === interestDay && lastInterestMonthYear !== monthYearKey && balance > 0.01) {
            lastInterestMonthYear = monthYearKey;
            balance += balance * monthlyRate;
        }

        const dayTxs = txsByDate[dateStr] || [];
        let scheduledExtraApplied = false;
        dayTxs.forEach(tx => {
            const amount = Number(tx.amount) || 0;
            if (amount > 0) {
                const scheduledExtra = !scheduledExtraApplied && tx.isAutomaticCardPayment
                    ? Math.max(0, Number(extraScheduledAmount) || 0)
                    : 0;
                if (scheduledExtra > 0) scheduledExtraApplied = true;
                const payment = Math.min(balance, amount + scheduledExtra);
                balance -= payment;
                totalPaid += payment;
            } else if (amount < 0) {
                balance += Math.abs(amount);
            }
        });
        // The entered loan end date is the contractual final payment. If already-materialized
        // scheduled rows leave a small rounding remainder on that date, treat the final payment as
        // the normal payoff adjustment instead of carrying a few dollars forever.
        if (loan.paymentEndDate && dateStr === loan.paymentEndDate && autoPaymentMonths.has(monthKey) && balance > 0.01) {
            totalPaid += balance;
            balance = 0;
        }


        // Loan payments recur by definition. If the app has not materialized a future automatic
        // payment row yet, project the configured monthly payment without writing anything to state.
        if (currentDate.getDate() === paymentDay && !autoPaymentMonths.has(monthKey) && balance > 0.01) {
            const withinStart = !loan.paymentStrategyStartDate || dateStr >= loan.paymentStrategyStartDate;
            const withinEnd = !loan.paymentEndDate || dateStr <= loan.paymentEndDate;
            if (withinStart && withinEnd) {
                // The temporary estimator amount increases every projected scheduled payment,
                // including months whose automatic payment has not yet been materialized.
                const isContractualFinalPayment = !!loan.paymentEndDate && dateStr === loan.paymentEndDate;
                const scheduledAmount = isContractualFinalPayment
                    ? balance
                    : monthlyPayment + Math.max(0, Number(extraScheduledAmount) || 0);
                const payment = Math.min(balance, scheduledAmount);
                balance -= payment;
                totalPaid += payment;
                autoPaymentMonths.add(monthKey);
            }
        }

        if (currentDate >= startPayDate && currentDate.getDate() === startPayDate.getDate() && balance > 0.01) {
            const payment = Math.min(balance, Math.max(0, Number(additionalMonthlyAmount) || 0));
            if (payment > 0.005) {
                balance -= payment;
                totalPaid += payment;
                additionalPayments.push({ date: dateStr, amount: payment });
            }
        }

        if (balance <= 0.01 && !payoffDate) payoffDate = new Date(currentDate);
        const nextDay = new Date(currentDate);
        nextDay.setDate(nextDay.getDate() + 1);
        if (nextDay.getMonth() !== currentDate.getMonth() || currentDate.getTime() === endDate.getTime()) {
            monthlyBalances.push({
                monthLabel: `${MONTH_ORDER[currentDate.getMonth()]} ${currentDate.getFullYear()}`,
                balance: Math.max(0, balance)
            });
            if (isDynamicPayoff && balance <= 0.01) break;
        }
        currentDate.setDate(currentDate.getDate() + 1);
    }

    return {
        path: monthlyBalances,
        payoffDate: payoffDate ? `${MONTH_ORDER[payoffDate.getMonth()]} ${payoffDate.getFullYear()}` : 'Payment too low',
        totalPayments: totalPaid,
        additionalPayments
    };
}

function projectCardPayoffPath(cardId, monthsCount, startPayDateStr, additionalMonthlyAmount, extraScheduledAmount = 0, isFutureSchedule = false, dynamicCapMonths = 60) {
    const card = state.loans.find(c => c.id === cardId);
    if (!card) return { path: [], payoffDate: 'Paid Off', totalPayments: 0 };
    if (card.type === 'loan') {
        // Long-term loans and mortgages commonly run well beyond the card chart's 60-month cap.
        // Keep enough projection runway to preserve their real payoff date and show acceleration.
        return projectInstallmentLoanPayoffPath(cardId, monthsCount, startPayDateStr, additionalMonthlyAmount, extraScheduledAmount, isFutureSchedule, Math.max(600, dynamicCapMonths));
    }

    const today = new Date();
    const todayStr = formatLocalDate(today);

    const startPayDate = startPayDateStr ? new Date(startPayDateStr + 'T00:00:00') : new Date(today.getFullYear(), today.getMonth() + 1, 1);

    const isDynamicPayoff = !isFutureSchedule || monthsCount <= 0;
    // Estimation must be read-only.  Do not initialize future budget months here: doing so
    // creates bills and automatic payments merely by opening the planner.
    const projectionMonths = isDynamicPayoff ? Math.max(1, dynamicCapMonths) : Math.max(1, monthsCount || 12);
    // A three-month plan beginning Jan 20 has payments on Jan 20, Feb 20, and Mar 20.
    const endDate = new Date(startPayDate.getFullYear(), startPayDate.getMonth() + projectionMonths - 1, startPayDate.getDate());

    const cardCal = state.cardCalendars[card.id] || {};
    const futureTxs = [];
    Object.keys(cardCal).forEach(key => {
        (cardCal[key] || []).forEach(tx => {
            if (tx.billOccurrenceDeleted) return;
            if (tx.isEstimatedInterest || tx.isPlanFee) return;
            if (tx.date > todayStr) {
                futureTxs.push({ ...tx });
            }
        });
    });

    // A custom schedule may contain months that have not been materialized into the ledger yet.
    // Include those configured payments in the estimate without writing any transactions.
    (card.customPaymentSchedule || []).forEach(item => {
        if (!item?.date || item.date <= todayStr || !(Number(item.amount) > 0)) return;
        const duplicate = futureTxs.some(tx => tx.date === item.date && tx.amount > 0 && tx.isAutomaticCardPayment);
        if (!duplicate) {
            futureTxs.push({
                id: `projection-custom-${item.id || item.date}`,
                date: item.date,
                amount: Number(item.amount),
                transactionKind: 'payment',
                isAutomaticCardPayment: true,
                isProjectionOnly: true
            });
        }
    });
    futureTxs.sort((a, b) => String(a.date).localeCompare(String(b.date)));

    const txsByDate = {};
    const automaticPaymentMonths = new Set();
    futureTxs.forEach(tx => {
        if (!txsByDate[tx.date]) txsByDate[tx.date] = [];
        txsByDate[tx.date].push(tx);
        if (tx.amount > 0 && tx.isAutomaticCardPayment) automaticPaymentMonths.add(tx.date.slice(0, 7));
    });

    let balance = calculateCardLedgerBalance(card.id, todayStr);
    const statementDay = Number(card.statementDay) || 1;

    const activePlans = deriveCardPaymentPlanBalances(cardId, todayStr).map(plan => ({
        ...plan,
        balanceAsOfDate: todayStr
    }));
    const planMinimumAppliedByMonth = new Map();
    const monthlyBalances = [];
    const additionalPayments = [];

    // Normalize to local midnight so the final selected payment date is included.
    let currentDate = new Date(todayStr + 'T00:00:00');
    currentDate.setDate(currentDate.getDate() + 1);

    let lastInterestMonthYear = '';
    let totalPaid = 0;
    let payoffDate = null;
    let hasHitZero = balance <= 0.01;

    while (currentDate <= endDate) {
        const dateStr = formatLocalDate(currentDate);
        const dayOfMonth = currentDate.getDate();
        const currentMonthYear = `${currentDate.getFullYear()}-${currentDate.getMonth()}`;

        // 1. Apply scheduled calendar transactions
        const dayTxs = txsByDate[dateStr] || [];
        dayTxs.forEach(tx => {
            let amount = Number(tx.amount) || 0;
            if (amount > 0) {
                amount += extraScheduledAmount;
                const actualPayment = Math.min(balance, amount);
                allocateCardPaymentAcrossPlans(activePlans, actualPayment, balance, dateStr, planMinimumAppliedByMonth);
                balance -= actualPayment;
                totalPaid += actualPayment;
            } else if (amount < 0) {
                balance += Math.abs(amount);
            }
        });

        // Project configured automatic payments even when their future ledger rows have not been
        // generated. Existing automatic rows win, so no month is counted twice.
        const paymentMonthKey = dateStr.slice(0, 7);
        const daysInPaymentMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
        const dueDay = Math.min(Number(card.dueDay) || 1, daysInPaymentMonth);
        const strategy = card.paymentStrategy || 'none';
        if (dayOfMonth === dueDay && !automaticPaymentMonths.has(paymentMonthKey) && balance > 0.01 && strategy !== 'none' && strategy !== 'custom') {
            const withinStart = !card.paymentStrategyStartDate || dateStr >= card.paymentStrategyStartDate;
            const withinEnd = !card.paymentEndDate || dateStr <= card.paymentEndDate;
            if (withinStart && withinEnd) {
                const planBalance = activePlans.reduce((sum, plan) => sum + Math.max(0, Number(plan.currentBalance) || 0), 0);
                const planMinimums = activePlans.reduce((sum, plan) => sum + Math.min(plan.currentBalance, Number(plan.monthlyPayment) || 0), 0);
                let scheduledPayment = 0;
                if (strategy === 'balance') scheduledPayment = balance;
                else if (strategy === 'minimum') scheduledPayment = Number(card.monthlyMin) || 0;
                else if (strategy === 'interestSaving') scheduledPayment = Math.max(0, balance - planBalance) + planMinimums;
                scheduledPayment = Math.min(balance, Math.max(0, scheduledPayment + extraScheduledAmount));
                if (scheduledPayment > 0.005) {
                    allocateCardPaymentAcrossPlans(activePlans, scheduledPayment, balance, dateStr, planMinimumAppliedByMonth);
                    balance -= scheduledPayment;
                    totalPaid += scheduledPayment;
                }
                automaticPaymentMonths.add(paymentMonthKey);
            }
        }

        // 2. Apply additional payoff payment
        if (currentDate >= startPayDate && dayOfMonth === startPayDate.getDate()) {
            if (balance > 0.01) {
                const payment = Math.min(balance, additionalMonthlyAmount);
                allocateCardPaymentAcrossPlans(activePlans, payment, balance, dateStr, planMinimumAppliedByMonth);
                balance -= payment;
                totalPaid += payment;
                additionalPayments.push({ date: dateStr, amount: payment });
            }
        }

        // 3. Apply statement interest and fees dynamically
        if (dayOfMonth === statementDay && lastInterestMonthYear !== currentMonthYear) {
            lastInterestMonthYear = currentMonthYear;
            let activePlansFees = 0;
            let activePlansBalanceSum = 0;

            activePlans.forEach(plan => {
                if (dateStr >= plan.startDate && plan.currentBalance > 0.005) {
                    activePlansFees += Number(plan.monthlyFee) || 0;
                    activePlansBalanceSum += Number(plan.currentBalance) || 0;
                }
            });

            balance += activePlansFees;

            if (balance > 0.01) {
                let interestAccruingBalance = Math.max(0, balance - activePlansBalanceSum);
                let promoInterest = 0;
                let activePromosBalanceSum = 0;

                (card.promos || []).forEach(promo => {
                    if (promo.expDate) {
                        const expTime = new Date(promo.expDate + 'T00:00:00').getTime();
                        if (currentDate.getTime() <= expTime) {
                            const pBal = Number(promo.currentBalance ?? promo.amount) || 0;
                            promoInterest += pBal * (Number(promo.rate) / 12 / 100);
                            activePromosBalanceSum += pBal;
                        }
                    }
                });

                let purchaseRate = Number(card.interestRate) || 0;
                if (card.promoActive && card.promoExpDate) {
                    const promoExpTime = new Date(card.promoExpDate + 'T00:00:00').getTime();
                    if (currentDate.getTime() <= promoExpTime) {
                        purchaseRate = Number(card.promoRate) || 0;
                    }
                }

                const nonPromoBalance = Math.max(0, interestAccruingBalance - activePromosBalanceSum);
                const standardInterest = nonPromoBalance * (purchaseRate / 12 / 100);
                balance += (standardInterest + promoInterest);
            }
        }

        if (balance <= 0.01 && !hasHitZero) {
            hasHitZero = true;
            payoffDate = new Date(currentDate);
        }

        const nextDay = new Date(currentDate);
        nextDay.setDate(nextDay.getDate() + 1);
        if (nextDay.getMonth() !== currentDate.getMonth() || currentDate.getTime() === endDate.getTime()) {
            const mLabel = `${MONTH_ORDER[currentDate.getMonth()]} ${currentDate.getFullYear()}`;
            monthlyBalances.push({
                monthLabel: mLabel,
                balance: Math.max(0, balance)
            });

            if (isDynamicPayoff && balance <= 0.01) {
                break;
            }
        }

        currentDate.setDate(currentDate.getDate() + 1);
    }

    let payoffDateStr = 'Payment too low';
    if (card && (card.paymentStrategy === 'balance' || card.paymentStrategy === 'interestSaving')) {
        payoffDateStr = 'Monthly';
        // A revolving strategy (pays the statement in full every cycle) hits $0.01 balance almost
        // every single cycle by design, so this loop's own `payoffDate` is just "next due date"
        // noise, not a meaningful answer to "when is this card actually debt-free" — that's why this
        // branch never used it. But a Payoff Plan scheduled on top of that ongoing strategy DOES have
        // a real, user-chosen target completion date, and it was getting silently thrown away here
        // along with the noise — confirmed as a real user complaint, 2026-08-02: "payoff payments
        // have been scheduled but it's set to auto monthly payments... this masks the true balance
        // payoff date and only shows as monthly." Surface the plan's own last-scheduled date directly
        // (from real ledger transactions or a pending custom schedule) instead of trying to derive it
        // from the noisy revolving-payment simulation.
        let latestPlanDate = '';
        Object.values(cardCal).forEach(list => (list || []).forEach(tx => {
            if (tx.billOccurrenceDeleted || !tx.isPayoffPlan || !tx.date || tx.date <= todayStr) return;
            if (tx.date > latestPlanDate) latestPlanDate = tx.date;
        }));
        (card.customPaymentSchedule || []).forEach(item => {
            if (item?.date && item.date > todayStr && item.date > latestPlanDate) latestPlanDate = item.date;
        });
        if (latestPlanDate) {
            const planEndDate = new Date(latestPlanDate + 'T00:00:00');
            payoffDateStr = `Monthly · Plan ends ${MONTH_ORDER[planEndDate.getMonth()]} ${planEndDate.getFullYear()}`;
        }
    } else if (payoffDate) {
        payoffDateStr = `${MONTH_ORDER[payoffDate.getMonth()]} ${payoffDate.getFullYear()}`;
    } else if (balance <= 0.01) {
        payoffDateStr = monthlyBalances.length > 0 ? monthlyBalances[monthlyBalances.length - 1].monthLabel : 'Paid Off';
    }

    return {
        path: monthlyBalances,
        payoffDate: payoffDateStr,
        totalPayments: totalPaid,
        additionalPayments
    };
}

function getFirstNonScheduledPaymentDate(cardId) {
    const card = state.loans.find(c => c.id === cardId);
    if (!card) return formatLocalDate(new Date());

    const dueDay = Number(card.dueDay) || 1;
    const todayStr = formatLocalDate(new Date());
    const cardCal = state.cardCalendars[cardId] || {};
    let lastDate = new Date(todayStr + 'T00:00:00');

    // The card setting is authoritative, even if that future month has never been opened.
    (card.customPaymentSchedule || []).forEach(item => {
        if (!item?.date || item.date < todayStr) return;
        const date = new Date(item.date + 'T00:00:00');
        if (!Number.isNaN(date.getTime()) && date > lastDate) lastDate = date;
    });

    // Include already-materialized payment entries, but ignore charges, interest, and fees.
    Object.values(cardCal).forEach(list => {
        (list || []).forEach(tx => {
            if (tx.billOccurrenceDeleted || tx.isEstimatedInterest || tx.isPlanFee) return;
            const isPayment = tx.amount > 0 && (
                tx.isAutomaticCardPayment || tx.isPayoffPlan || tx.linkedPaymentId || tx.transactionKind === 'payment'
            );
            if (!isPayment || tx.date < todayStr) return;
            const date = new Date(tx.date + 'T00:00:00');
            if (!Number.isNaN(date.getTime()) && date > lastDate) lastDate = date;
        });
    });

    const nextMonth = new Date(lastDate.getFullYear(), lastDate.getMonth() + 1, 1);
    const daysInNextMonth = new Date(nextMonth.getFullYear(), nextMonth.getMonth() + 1, 0).getDate();
    return formatLocalDate(new Date(nextMonth.getFullYear(), nextMonth.getMonth(), Math.min(dueDay, daysInNextMonth)));
}

function renderCardPayoffEstimator(cardId) {
    const card = state.loans.find(c => c.id === cardId);
    if (!card) return;

    const futureChk = document.getElementById('cc-payoff-future-schedule-chk');
    const futureFieldsContainer = document.getElementById('cc-payoff-future-fields-container');
    const startDateInput = document.getElementById('cc-payoff-start-date');
    const timeframeSelect = document.getElementById('cc-payoff-timeframe');
    const customFields = document.getElementById('cc-payoff-custom-fields');
    const sliderInput = document.getElementById('cc-payoff-slider');
    const sliderLabel = document.getElementById('cc-payoff-slider-val-label');
    const manualAmountInput = document.getElementById('cc-payoff-manual-amount');
    const amountLabel = document.getElementById('cc-payoff-amount-label');
    const suggestedLabel = document.getElementById('cc-payoff-suggested-label');
    const btnCommit = document.getElementById('btn-cc-payoff-commit');
    const svgContainer = document.getElementById('cc-payoff-chart-svg-container');
    const statsContainer = document.getElementById('cc-payoff-header-stats');

    if (!timeframeSelect || !svgContainer) return;

    const isFutureSchedule = futureChk ? futureChk.checked : false;

    if (futureFieldsContainer) {
        futureFieldsContainer.style.display = isFutureSchedule ? 'grid' : 'none';
    }

    if (amountLabel) {
        amountLabel.textContent = isFutureSchedule
            ? 'Monthly Additional Payment (Future Payments)'
            : 'Monthly Additional Payment (Scheduled Payments)';
    }
    if (btnCommit) {
        btnCommit.textContent = isFutureSchedule ? 'Commit Future Payments' : 'Commit Extra to Scheduled';
    }

    if (isFutureSchedule && startDateInput && !startDateInput.value) {
        startDateInput.value = getFirstNonScheduledPaymentDate(cardId);
    }

    const startPayDateStr = isFutureSchedule && startDateInput ? startDateInput.value : formatLocalDate(new Date());
    const timeframeVal = timeframeSelect.value;

    if (timeframeVal === 'custom') {
        if (customFields) customFields.style.display = 'flex';
    } else {
        if (customFields) customFields.style.display = 'none';
    }

    let monthsCount = 0;
    if (isFutureSchedule) {
        if (timeframeVal === 'custom') {
            const val = parseInt(document.getElementById('cc-payoff-custom-val').value) || 1;
            const unit = document.getElementById('cc-payoff-custom-unit').value;
            monthsCount = unit === 'years' ? val * 12 : val;
        } else if (timeframeVal) {
            monthsCount = parseInt(timeframeVal) || 0;
        }
    }

    const today = new Date();
    const todayStr = formatLocalDate(today);
    const startBal = calculateCardLedgerBalance(cardId, todayStr);

    let manualPayoffVal = parseFloat(manualAmountInput ? manualAmountInput.value : 0) || 0;
    if (sliderInput) {
        if (parseInt(sliderInput.value) !== Math.round(manualPayoffVal)) {
            sliderInput.value = Math.min(2000, Math.round(manualPayoffVal));
        }
    }
    if (sliderLabel) {
        sliderLabel.textContent = `$${Math.round(manualPayoffVal).toLocaleString('en-US')}`;
    }

    // Projections
    // 1. Current Proj (Base) — always dynamic (rolls forward until paid off)
    const currentProj = projectCardPayoffPath(cardId, monthsCount, startPayDateStr, 0, 0, isFutureSchedule);

    let recommendedPayment = 0;
    let payoffProj = null;

    // Only run the expensive binary-search suggested payment when "Schedule future payments" is
    // active AND a fixed timeframe is selected. Avoid it for the default slider-only view.
    if (isFutureSchedule && timeframeVal && monthsCount > 0) {
        if (startBal > 0.01) {
            let low = 0;
            let high = startBal + 5000;
            // 18 iterations is plenty (precision ~$0.10 for a $20k balance)
            for (let iter = 0; iter < 18; iter++) {
                const mid = (low + high) / 2;
                const proj = projectCardPayoffPath(cardId, monthsCount, startPayDateStr, mid, 0, true);
                if (proj.path.length > 0 && proj.path[proj.path.length - 1].balance <= 0.01) {
                    recommendedPayment = mid;
                    high = mid;
                } else {
                    low = mid;
                }
            }
        }

        if (suggestedLabel) {
            suggestedLabel.textContent = `Suggested: $${Math.ceil(recommendedPayment).toLocaleString('en-US')}`;
        }

        if (manualAmountInput && !manualAmountInput.value && manualAmountInput.dataset.pristine !== 'false') {
            manualAmountInput.value = Math.ceil(recommendedPayment) || '';
            manualPayoffVal = Math.ceil(recommendedPayment);
            if (sliderInput) sliderInput.value = Math.min(2000, manualPayoffVal);
            if (sliderLabel) sliderLabel.textContent = `$${Number(manualPayoffVal).toLocaleString('en-US')}`;
        }
    } else {
        if (suggestedLabel) suggestedLabel.textContent = 'Suggested: --';
    }

    // 2. Accelerated Payoff Proj (with slider/manual amount applied)
    if (isFutureSchedule) {
        payoffProj = projectCardPayoffPath(cardId, monthsCount, startPayDateStr, manualPayoffVal, 0, true);
    } else {
        payoffProj = projectCardPayoffPath(cardId, 0, todayStr, 0, manualPayoffVal, false);
    }

    // Update Header Stats Span
    if (statsContainer) {
        statsContainer.innerHTML = `Payoff Date: <strong style="color: #f43f5e;">${formatDateDisplay(payoffProj.payoffDate)}</strong> &nbsp;&nbsp;&nbsp; Total payments: <strong style="color: var(--color-primary);">$${payoffProj.totalPayments.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}</strong>`;
    }

    // Use the longer of the two paths so the chart covers the full timeline
    const pathData = currentProj.path;
    const pathDataAcc = payoffProj.path;

    let maxVal = 100;
    pathData.forEach(pt => { if (pt.balance > maxVal) maxVal = pt.balance; });
    if (pathDataAcc) {
        pathDataAcc.forEach(pt => { if (pt.balance > maxVal) maxVal = pt.balance; });
    }
    maxVal = Math.ceil(maxVal / 100) * 100;

    // Chart sizing:
    // - The VISIBLE window is the scroll container's clientWidth (always fits on screen).
    // - The CANVAS grows at 85px per month so months beyond the window can be scrolled to.
    // - Show the first 12 months in the visible window; additional months scroll right.
    const scrollContainer = document.getElementById('cc-payoff-chart-scroll-container');
    const visibleWidth = (scrollContainer ? scrollContainer.clientWidth : 0) || 700;
    const monthColWidth = 85;
    // Total canvas width: 12 visible months fill the viewport; more months overflow and scroll.
    const totalMonths = Math.max(pathData.length, pathDataAcc ? pathDataAcc.length : 0);
    const canvasWidth = Math.max(visibleWidth, totalMonths * monthColWidth + 70);
    // The svg-container div drives the scroll width; set it but don't change the scroll wrapper
    svgContainer.style.width = `${canvasWidth}px`;
    const width = canvasWidth;

    const height = 220;
    const paddingLeft = 55;
    const paddingRight = 20;
    const paddingTop = 30;
    const paddingBottom = 30;

    const graphWidth = width - paddingLeft - paddingRight;
    const graphHeight = height - paddingTop - paddingBottom;

    const getX = (idx, total) => paddingLeft + (idx / (total - 1 || 1)) * graphWidth;
    const getY = (val) => paddingTop + graphHeight - (val / maxVal) * graphHeight;

    let gridLinesHtml = '';
    const gridTicks = 4;
    for (let i = 0; i <= gridTicks; i++) {
        const val = (maxVal / gridTicks) * i;
        const y = getY(val);
        gridLinesHtml += `
            <line x1="${paddingLeft}" y1="${y}" x2="${width - paddingRight}" y2="${y}" stroke="rgba(255,255,255,0.08)" stroke-width="1"></line>
            <text x="${paddingLeft - 8}" y="${y + 4}" fill="var(--text-secondary)" font-size="10" text-anchor="end">$${Math.round(val).toLocaleString('en-US')}</text>
        `;
    }

    let xLabelsHtml = '';
    pathData.forEach((pt, idx) => {
        const x = getX(idx, pathData.length);
        const labelParts = pt.monthLabel.split(' ');
        const shortLabel = labelParts.length === 2 ? `${labelParts[0].slice(0, 3)} '${labelParts[1].slice(-2)}` : pt.monthLabel;

        xLabelsHtml += `
            <text x="${x}" y="${height - 10}" fill="var(--text-secondary)" font-size="10" text-anchor="middle">${shortLabel}</text>
            <line x1="${x}" y1="${paddingTop}" x2="${x}" y2="${height - paddingBottom}" stroke="rgba(255,255,255,0.03)" stroke-width="1"></line>
        `;
    });

    let currentPathD = '';
    pathData.forEach((pt, idx) => {
        const x = getX(idx, pathData.length);
        const y = getY(pt.balance);
        currentPathD += (idx === 0 ? 'M' : 'L') + `${x},${y}`;
    });

    let currentPathHtml = `
        <path d="${currentPathD}" stroke="rgba(255,255,255,0.3)" stroke-width="2" stroke-dasharray="4,4" fill="none"></path>
    `;

    let accPathHtml = '';
    if (pathDataAcc) {
        let accPathD = '';
        pathDataAcc.forEach((pt, idx) => {
            const x = getX(idx, pathDataAcc.length);
            const y = getY(pt.balance);
            accPathD += (idx === 0 ? 'M' : 'L') + `${x},${y}`;
        });
        accPathHtml = `
            <path d="${accPathD}" stroke="#f43f5e" stroke-width="3" fill="none"></path>
        `;
    }

    // Each point is wrapped in a <g class="cc-payoff-point"> with an invisible oversized hit-circle
    // so hovering (even slightly off the small visible dot) enlarges its label via CSS — the plotted
    // numbers are otherwise too small to read at a glance (see .cc-payoff-point:hover in index.css).
    let graphLabelsHtml = '';
    pathData.forEach((pt, idx) => {
        const x = getX(idx, pathData.length);
        const y = getY(pt.balance);
        const hasLabel = !pathDataAcc || idx >= pathDataAcc.length || Math.abs(pt.balance - pathDataAcc[idx].balance) > 10;
        graphLabelsHtml += `<g class="cc-payoff-point">
                <circle cx="${x}" cy="${y}" r="10" fill="transparent"></circle>
                <circle cx="${x}" cy="${y}" r="4" fill="rgba(255,255,255,0.7)" stroke="var(--bg-primary)" stroke-width="1.5"></circle>
                ${hasLabel ? `<text x="${x}" y="${y - 10}" fill="rgba(255,255,255,0.5)" font-size="9" font-weight="500" text-anchor="middle">$${Math.round(pt.balance).toLocaleString('en-US')}</text>` : ''}
            </g>`;
    });

    if (pathDataAcc) {
        pathDataAcc.forEach((pt, idx) => {
            const x = getX(idx, pathDataAcc.length);
            const y = getY(pt.balance);
            graphLabelsHtml += `<g class="cc-payoff-point cc-payoff-point-acc">
                    <circle cx="${x}" cy="${y}" r="10" fill="transparent"></circle>
                    <circle cx="${x}" cy="${y}" r="4" fill="#f43f5e" stroke="var(--bg-primary)" stroke-width="1.5"></circle>
                    <text x="${x}" y="${y - 12}" fill="#f43f5e" font-size="10" font-weight="bold" text-anchor="middle">$${pt.balance.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</text>
                </g>`;
        });
    }

    const borderLines = `
        <line x1="${paddingLeft}" y1="${paddingTop}" x2="${paddingLeft}" y2="${height - paddingBottom}" stroke="rgba(255,255,255,0.1)" stroke-width="1"></line>
        <line x1="${paddingLeft}" y1="${height - paddingBottom}" x2="${width - paddingRight}" y2="${height - paddingBottom}" stroke="rgba(255,255,255,0.1)" stroke-width="1"></line>
    `;

    const legendHtml = `
        <div class="cc-payoff-legend" style="display: flex; gap: 1.5rem; justify-content: center; margin-top: 1rem; font-size: 0.85rem; position: sticky; left: 0; width: 100%;">
            <div class="cc-payoff-legend-item" style="display: flex; align-items: center; gap: 0.5rem; color: var(--text-secondary);">
                <div style="width: 12px; height: 2px; border-top: 2px dashed rgba(255,255,255,0.4);"></div>
                <span>Current Plan Path</span>
            </div>
            <div class="cc-payoff-legend-item" style="display: flex; align-items: center; gap: 0.5rem; color: var(--text-secondary);">
                <div style="width: 12px; height: 3px; background: #f43f5e; border-radius: 1px;"></div>
                <span>Payoff Plan Path</span>
            </div>
        </div>
    `;

    svgContainer.innerHTML = `
        <svg width="100%" height="100%" viewBox="0 0 ${width} ${height}" style="overflow: visible; display: block;">
            <g>${gridLinesHtml}</g>
            <g>${xLabelsHtml}</g>
            ${currentPathHtml}
            ${accPathHtml}
            <g>${borderLines}</g>
            <g>${graphLabelsHtml}</g>
        </svg>
        ${legendHtml}
    `;
}

function resetCardPayoffEstimatorInputs() {
    const futureChk = document.getElementById('cc-payoff-future-schedule-chk');
    const futureFields = document.getElementById('cc-payoff-future-fields-container');
    const startDate = document.getElementById('cc-payoff-start-date');
    const timeframe = document.getElementById('cc-payoff-timeframe');
    const customFields = document.getElementById('cc-payoff-custom-fields');
    const customValue = document.getElementById('cc-payoff-custom-val');
    const customUnit = document.getElementById('cc-payoff-custom-unit');
    const slider = document.getElementById('cc-payoff-slider');
    const sliderLabel = document.getElementById('cc-payoff-slider-val-label');
    const manualAmount = document.getElementById('cc-payoff-manual-amount');
    const amountLabel = document.getElementById('cc-payoff-amount-label');
    const suggestedLabel = document.getElementById('cc-payoff-suggested-label');
    const commitButton = document.getElementById('btn-cc-payoff-commit');

    if (futureChk) futureChk.checked = false;
    if (futureFields) futureFields.style.display = 'none';
    if (startDate) startDate.value = '';
    if (timeframe) timeframe.value = '';
    if (customFields) customFields.style.display = 'none';
    if (customValue) customValue.value = '9';
    if (customUnit) customUnit.value = 'months';
    if (slider) slider.value = '0';
    if (sliderLabel) sliderLabel.textContent = '$0';
    if (manualAmount) {
        manualAmount.value = '';
        delete manualAmount.dataset.pristine;
    }
    if (amountLabel) amountLabel.textContent = 'Monthly Additional Payment (Scheduled Payments)';
    if (suggestedLabel) suggestedLabel.textContent = 'Suggested: --';
    if (commitButton) commitButton.textContent = 'Commit Extra to Scheduled';
}

function initCardPayoffEvents() {
    const toggle = document.getElementById('cc-payoff-toggle');
    if (!toggle || toggle.dataset.payoffBound) return;
    toggle.dataset.payoffBound = 'true';

    toggle.addEventListener('click', () => {
        const body = document.getElementById('cc-payoff-content');
        if (!body) return;

        const isHidden = body.classList.contains('hidden') || body.style.display === 'none';
        if (!state.uiCollapsedSections) state.uiCollapsedSections = {};
        const account = state.loans.find(item => item.id === state.ccSelectedCardId);
        const plannerKey = account?.type === 'loan' ? 'loanPlanner' : 'ccPlanner';
        state.uiCollapsedSections[plannerKey] = !isHidden;
        state.ccPayoffCollapsed = !isHidden;
        saveDatabase();
        applyCreditCardSectionState();
    });

    const futureChk = document.getElementById('cc-payoff-future-schedule-chk');
    if (futureChk) {
        futureChk.addEventListener('change', () => {
            const manualAmountInput = document.getElementById('cc-payoff-manual-amount');
            if (manualAmountInput) {
                delete manualAmountInput.dataset.pristine;
                manualAmountInput.value = '';
            }
            const startDateInput = document.getElementById('cc-payoff-start-date');
            if (startDateInput) {
                startDateInput.value = '';
            }
            renderCardPayoffEstimator(state.ccSelectedCardId || state.activeCCId);
        });
    }

    const tfSelect = document.getElementById('cc-payoff-timeframe');
    if (tfSelect) {
        tfSelect.addEventListener('change', () => {
            const manualAmountInput = document.getElementById('cc-payoff-manual-amount');
            if (manualAmountInput) {
                delete manualAmountInput.dataset.pristine;
                manualAmountInput.value = '';
            }
            renderCardPayoffEstimator(state.ccSelectedCardId || state.activeCCId);
        });
    }

    const customVal = document.getElementById('cc-payoff-custom-val');
    if (customVal) {
        customVal.addEventListener('input', () => {
            const manualAmountInput = document.getElementById('cc-payoff-manual-amount');
            if (manualAmountInput) {
                delete manualAmountInput.dataset.pristine;
                manualAmountInput.value = '';
            }
            renderCardPayoffEstimator(state.ccSelectedCardId || state.activeCCId);
        });
    }

    const customUnit = document.getElementById('cc-payoff-custom-unit');
    if (customUnit) {
        customUnit.addEventListener('change', () => {
            const manualAmountInput = document.getElementById('cc-payoff-manual-amount');
            if (manualAmountInput) {
                delete manualAmountInput.dataset.pristine;
                manualAmountInput.value = '';
            }
            renderCardPayoffEstimator(state.ccSelectedCardId || state.activeCCId);
        });
    }

    const startDateInput = document.getElementById('cc-payoff-start-date');
    if (startDateInput) {
        startDateInput.addEventListener('change', () => {
            const manualAmountInput = document.getElementById('cc-payoff-manual-amount');
            if (manualAmountInput) {
                delete manualAmountInput.dataset.pristine;
                manualAmountInput.value = '';
            }
            renderCardPayoffEstimator(state.ccSelectedCardId || state.activeCCId);
        });
    }

    const sliderInput = document.getElementById('cc-payoff-slider');
    const manualAmountInput = document.getElementById('cc-payoff-manual-amount');

    if (sliderInput && manualAmountInput) {
        sliderInput.addEventListener('input', () => {
            manualAmountInput.value = sliderInput.value;
            manualAmountInput.dataset.pristine = 'false';
            renderCardPayoffEstimator(state.ccSelectedCardId || state.activeCCId);
        });

        manualAmountInput.addEventListener('input', () => {
            manualAmountInput.dataset.pristine = 'false';
            sliderInput.value = Math.min(2000, parseFloat(manualAmountInput.value) || 0);
            renderCardPayoffEstimator(state.ccSelectedCardId || state.activeCCId);
        });
    }

    const btnCommit = document.getElementById('btn-cc-payoff-commit');
    if (btnCommit) {
        btnCommit.addEventListener('click', () => {
            const isFuture = futureChk ? futureChk.checked : false;
            if (isFuture) {
                commitPayoffPayments();
            } else {
                commitSliderPayments();
            }
        });
    }
}

function commitPayoffPayments() {
    const cardId = state.ccSelectedCardId || state.activeCCId;
    const card = state.loans.find(c => c.id === cardId);
    if (!card) return alert('No active debt account selected.');

    const startDateInput = document.getElementById('cc-payoff-start-date');
    const timeframeSelect = document.getElementById('cc-payoff-timeframe');
    const manualAmountInput = document.getElementById('cc-payoff-manual-amount');

    if (!startDateInput || !startDateInput.value) {
        return alert('Please select a starting date for additional payments.');
    }
    if (!timeframeSelect || !timeframeSelect.value) {
        return alert('Please select a payoff timeframe.');
    }

    const startPayDateStr = startDateInput.value;
    const timeframeVal = timeframeSelect.value;
    let monthsCount = 0;
    if (timeframeVal === 'custom') {
        const val = parseInt(document.getElementById('cc-payoff-custom-val').value) || 1;
        const unit = document.getElementById('cc-payoff-custom-unit').value;
        monthsCount = unit === 'years' ? val * 12 : val;
    } else {
        monthsCount = parseInt(timeframeVal) || 0;
    }

    const pmtAmount = parseFloat(manualAmountInput ? manualAmountInput.value : 0) || 0;
    if (pmtAmount <= 0) {
        return alert('Please enter a valid payoff payment amount.');
    }

    if (!confirm(`Are you sure you want to commit payoff payments of $${pmtAmount.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})}/month for ${monthsCount} months starting on ${formatDateDisplay(startPayDateStr)}?`)) {
        return;
    }

    const startPayDate = new Date(startPayDateStr + 'T00:00:00');
    const cardPaymentSource = card.paymentSource || card.owner;
    const source = cardPaymentSource === 'joint' ? 'joint' : cardPaymentSource === 'asia' ? 'asia' : 'jason';
    // Use the estimator's date-specific applied amounts so the final payment never overpays.
    const committedProjection = projectCardPayoffPath(cardId, monthsCount, startPayDateStr, pmtAmount, 0, true);
    const projPayments = committedProjection.additionalPayments || [];

    for (let i = 0; i < projPayments.length; i++) {
        const paymentObj = projPayments[i];
        const dateStr = paymentObj.date;
        const scheduledAmount = Number(paymentObj.amount) || 0;
        const roundedAmount = Math.round(Math.abs(scheduledAmount) * 100) / 100;
        if (roundedAmount <= 0.005) continue;

        const d = new Date(dateStr + 'T00:00:00');
        const y = d.getFullYear();
        const mShort = MONTH_ORDER[d.getMonth()];
        const key = `${y}-${mShort}`;

        ensureYearMonthInitialized(y, mShort);

        const linkId = 'payoff-pmt-' + Math.random().toString(36).substr(2, 9);
        const checkingTxId = (source === 'joint' ? 'j-' : source === 'asia' ? 'a-' : 'p-') + Math.random().toString(36).substr(2, 9);
        const pmtDesc = `Payoff: ${card.name}`;

        if (source === 'jason') {
            if (!state.personalCalendar[key]) state.personalCalendar[key] = [];
            state.personalCalendar[key].push({
                id: checkingTxId,
                date: dateStr,
                description: pmtDesc,
                amount: -roundedAmount,
                linkedPaymentId: linkId,
                payoffTargetId: cardId
            });
        } else if (source === 'asia') {
            if (!state.asiaCalendar[key]) state.asiaCalendar[key] = [];
            state.asiaCalendar[key].push({
                id: checkingTxId,
                date: dateStr,
                description: pmtDesc,
                amount: -roundedAmount,
                linkedPaymentId: linkId,
                payoffTargetId: cardId
            });
        } else {
            if (!state.jointRegister) state.jointRegister = [];
            state.jointRegister.push({
                id: checkingTxId,
                date: dateStr,
                name: pmtDesc,
                description: pmtDesc,
                amount: -roundedAmount,
                linkedPaymentId: linkId,
                automaticPaymentId: linkId,
                isPayoffPlan: true,
                payoffTargetId: cardId
            });
        }

        if (!state.cardCalendars[cardId]) state.cardCalendars[cardId] = {};
        if (!state.cardCalendars[cardId][key]) state.cardCalendars[cardId][key] = [];
        state.cardCalendars[cardId][key].push({
            id: 'cc-tx-' + Math.random().toString(36).substr(2, 9),
            date: dateStr,
            merchant: 'Payoff Payment',
            description: pmtDesc,
            amount: roundedAmount,
            kind: 'payment',
            transactionKind: 'payment',
            isPayoffPlan: true,
            payoffTargetId: cardId,
            owner: source,
            trip: '',
            linkedPaymentId: linkId,
            automaticPaymentId: linkId
        });

        if (card.paymentStrategy === 'custom') {
            if (!Array.isArray(card.customPaymentSchedule)) card.customPaymentSchedule = [];
            const existingIdx = card.customPaymentSchedule.findIndex(item => item.date === dateStr);
            const entry = { id: 'sched-' + Math.random().toString(36).substr(2, 9), date: dateStr, amount: roundedAmount };
            if (existingIdx >= 0) card.customPaymentSchedule[existingIdx] = entry;
            else card.customPaymentSchedule.push(entry);
        }
    }

    refreshMaterializedCardStatementCharges(cardId);
    const accountLabel = card.type === 'loan' ? 'loan' : 'card';
    alert(`Scheduled ${monthsCount} payoff payment${monthsCount === 1 ? '' : 's'}. The ${accountLabel} ledger will now show the scheduled year.`);

    startDateInput.value = '';
    timeframeSelect.value = '';
    if (manualAmountInput) {
        manualAmountInput.value = '';
        delete manualAmountInput.dataset.pristine;
    }
    const customFields = document.getElementById('cc-payoff-custom-fields');
    if (customFields) customFields.style.display = 'none';

    // The payments are future ledger entries; take the user directly to the year that contains them.
    state.ccYear = startPayDate.getFullYear();
    state.ccMonth = MONTH_ORDER[startPayDate.getMonth()];
    state.ccViewMode = 'list';
    state.ccListScope = 'year';
    saveData();
    renderCCCardList(cardId);
}

function commitSliderPayments() {
    const cardId = state.ccSelectedCardId || state.activeCCId;
    const card = state.loans.find(c => c.id === cardId);
    if (!card) return alert('No active card selected.');

    const manualAmountInput = document.getElementById('cc-payoff-manual-amount');
    const extraVal = parseFloat(manualAmountInput ? manualAmountInput.value : 0) || 0;
    if (extraVal <= 0) {
        return alert('Please enter or adjust the payment amount to greater than $0.');
    }

    const timeframeSelect = document.getElementById('cc-payoff-timeframe');
    const timeframeVal = timeframeSelect && timeframeSelect.value ? timeframeSelect.value : '12';

    let monthsCount = 12;
    if (timeframeVal === 'custom') {
        const val = parseInt(document.getElementById('cc-payoff-custom-val').value) || 1;
        const unit = document.getElementById('cc-payoff-custom-unit').value;
        monthsCount = unit === 'years' ? val * 12 : val;
    } else if (timeframeVal) {
        monthsCount = parseInt(timeframeVal) || 12;
    }

    const today = new Date();
    const startPayDateStr = formatLocalDate(today);
    const endDate = new Date(today.getFullYear(), today.getMonth() + monthsCount, today.getDate());
    const endDateStr = formatLocalDate(endDate);

    const accountLabel = card.type === 'loan' ? 'loan' : 'card';
    if (!confirm(`Are you sure you want to add an extra ${extraVal.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} to all scheduled payments on this ${accountLabel} between ${startPayDateStr} and ${endDateStr}?`)) {
        return;
    }

    let modifiedCount = 0;
    const cardPaymentSource = card.paymentSource || card.owner;
    const source = cardPaymentSource === 'joint' ? 'joint' : cardPaymentSource === 'asia' ? 'asia' : 'jason';
    const monthsFromToday = (endDate.getFullYear() - today.getFullYear()) * 12 + (endDate.getMonth() - today.getMonth());

    for (let i = 0; i <= monthsFromToday + 1; i++) {
        const d = new Date(today.getFullYear(), today.getMonth() + i, 1);
        const y = d.getFullYear();
        const mShort = MONTH_ORDER[d.getMonth()];
        const key = `${y}-${mShort}`;

        const cardCal = state.cardCalendars[cardId] || {};
        const txs = cardCal[key] || [];

        txs.forEach(tx => {
            if (tx.billOccurrenceDeleted) return;
            if (tx.isEstimatedInterest || tx.isPlanFee) return;
            if (tx.date >= startPayDateStr && tx.date <= endDateStr && tx.amount > 0) {
                if (card.isMortgage && !tx.isMortgageLoanPayment) return;
                if (tx.isMortgageLoanPayment) {
                    const linkId = 'mortgage-payoff-extra-' + Math.random().toString(36).substr(2, 9);
                    const description = `Payoff Extra: ${card.name}`;
                    if (source === 'joint') {
                        state.jointRegister.push({
                            id: 'j-' + Math.random().toString(36).substr(2, 9), type: 'expense', name: description,
                            description, date: tx.date, amount: -Math.abs(extraVal), linkedPaymentId: linkId,
                            payoffTargetId: cardId, isPayoffPlan: true, isMortgagePayoffExtra: true
                        });
                    } else if (source === 'asia') {
                        if (!state.asiaCalendar[key]) state.asiaCalendar[key] = [];
                        state.asiaCalendar[key].push({
                            id: 'a-' + Math.random().toString(36).substr(2, 9), description,
                            date: tx.date, amount: -Math.abs(extraVal), linkedPaymentId: linkId,
                            payoffTargetId: cardId, isPayoffPlan: true, isMortgagePayoffExtra: true
                        });
                    } else {
                        if (!state.personalCalendar[key]) state.personalCalendar[key] = [];
                        state.personalCalendar[key].push({
                            id: 'p-' + Math.random().toString(36).substr(2, 9), description,
                            date: tx.date, amount: -Math.abs(extraVal), linkedPaymentId: linkId,
                            payoffTargetId: cardId, isPayoffPlan: true, isMortgagePayoffExtra: true
                        });
                    }
                    txs.push({
                        id: 'loan-extra-' + Math.random().toString(36).substr(2, 9),
                        date: tx.date, description, amount: Math.abs(extraVal), transactionKind: 'payment',
                        owner: source, linkedPaymentId: linkId, payoffTargetId: cardId,
                        isPayoffPlan: true, isManualLoanPayment: true, isMortgagePayoffExtra: true
                    });
                    modifiedCount++;
                    return;
                }
                const oldAmount = tx.amount;
                tx.amount = oldAmount + extraVal;
                modifiedCount++;

                if (tx.isAutomaticCardPayment) {
                    tx.automaticPaymentOverridden = true;
                }

                if (tx.linkedPaymentId) {
                    const findAndIncrease = (register) => {
                        if (!register) return;
                        if (Array.isArray(register)) {
                            register.forEach(ctx => {
                                if (ctx.linkedPaymentId === tx.linkedPaymentId) {
                                    ctx.amount = -Math.abs(tx.amount);
                                }
                            });
                        } else {
                            Object.keys(register).forEach(k => {
                                (register[k] || []).forEach(ctx => {
                                    if (ctx.linkedPaymentId === tx.linkedPaymentId) {
                                        ctx.amount = -Math.abs(ctx.amount);
                                    }
                                });
                            });
                        }
                    };
                    findAndIncrease(state.personalCalendar);
                    findAndIncrease(state.jointRegister);
                    findAndIncrease(state.asiaCalendar);
                }
            }
        });
    }

    refreshMaterializedCardStatementCharges(cardId);
    alert(`Successfully increased ${modifiedCount} scheduled payments by ${extraVal.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2})} each.`);
    if (manualAmountInput) {
        manualAmountInput.value = '';
        delete manualAmountInput.dataset.pristine;
    }
    const sliderInput = document.getElementById('cc-payoff-slider');
    if (sliderInput) sliderInput.value = 0;
    const sliderLabel = document.getElementById('cc-payoff-slider-val-label');
    if (sliderLabel) sliderLabel.textContent = '$0';

    saveData();
    renderCCCardList(cardId);
}

// syncMortgageLoansToAllMonths()/syncBillTrackerBillsToAllMonths() below are O(every month that
// exists) each — necessary when a mortgage loan or bill-tracker setting is actually added/edited, but
// autopopulateBillsForMonth() calls both on every single invocation, and it in turn gets called from
// getCalculatedTransferForJason()/getCalculatedTransferForAsia() on every cache miss. Materializing
// months far in the future (e.g. jumping straight to a month years out) triggers hundreds of those
// calls, each re-scanning every already-existing month — an O(months²) blowup that's the real cause of
// the multi-second freeze on a large jump. These "IfChanged" wrappers skip the expensive full re-sync
// unless the mortgage loans / bill-tracker settings actually changed since the last sync (compared via
// a cheap JSON signature), so the hot path only pays for it once until something real changes.
// Signature includes the month COUNT too, not just the settings — both sync functions iterate every
// key in state.monthlyBills, so a brand-new month (materialized mid-walk by ensureYearMonthInitialized)
// needs a fresh sync even when the settings themselves haven't changed, or that new month would never
// get its mortgage/bill-tracker-driven bills populated at all.
let _lastMortgageSyncSignature = null;
function syncMortgageLoansToAllMonthsIfChanged() {
    const mortgageLoans = state.loans.filter(l => l.type === 'loan' && l.isMortgage);
    const signature = JSON.stringify(mortgageLoans) + '|' + Object.keys(state.monthlyBills || {}).length;
    if (signature === _lastMortgageSyncSignature) return;
    _lastMortgageSyncSignature = signature;
    syncMortgageLoansToAllMonths();
}

let _lastBillTrackerSyncSignature = null;
function syncBillTrackerBillsToAllMonthsIfChanged() {
    const signature = JSON.stringify(state.billTrackerSettings || []) + '|' + Object.keys(state.monthlyBills || {}).length;
    if (signature === _lastBillTrackerSyncSignature) return;
    _lastBillTrackerSyncSignature = signature;
    syncBillTrackerBillsToAllMonths();
}

function countFutureTransactionsTiedToSetting(targetId, type = 'billTracker') {
    let count = 0;
    const todayStr = formatLocalDate(new Date());
    const isFuture = tx => tx.date && tx.date >= todayStr;
    const matchesId = tx => {
        if (type === 'billTracker') {
            return tx.linkedBillId === targetId || tx.linkedBillSeriesId === targetId;
        } else if (type === 'splitterTemplate') {
            return tx.linkedBillSeriesId === targetId || tx.linkedBillId === targetId || String(tx.linkedBillId || '').startsWith(`${targetId}-`);
        }
        return false;
    };

    if (type === 'card') {
        const cal = state.cardCalendars?.[targetId];
        if (cal) {
            Object.values(cal).forEach(list => {
                count += (list || []).filter(isFuture).length;
            });
        }
        // Bug fix, 2026-08-10: destinationAccount/transferTargetId are never actually SET on any
        // transaction anywhere in this file (confirmed via grep — this was the only place either was
        // referenced) — automatic-payment and payoff-payment checking-side legs are tagged
        // payoffTargetId (see ensureAutomaticCardPaymentForMonth/commitPayoffPayments/etc.), which this
        // count never checked, so the confirm dialog's "will delete N future transactions" always
        // undercounted (usually to 0) for a card/loan with any automatic or payoff payments. Added
        // payoffTargetId alongside the original conditions (kept, not replaced, in case some other
        // path does set them) and asiaCalendar (missing entirely — an Asia-owned account's future
        // checking-side legs were never counted at all).
        const matchesCardCheckingTx = tx => tx.paymentSource === targetId || tx.destinationAccount === targetId || tx.transferTargetId === targetId || tx.payoffTargetId === targetId;
        count += (state.jointRegister || []).filter(tx => isFuture(tx) && matchesCardCheckingTx(tx)).length;
        Object.values(state.personalCalendar || {}).forEach(list => {
            count += (list || []).filter(tx => isFuture(tx) && matchesCardCheckingTx(tx)).length;
        });
        Object.values(state.asiaCalendar || {}).forEach(list => {
            count += (list || []).filter(tx => isFuture(tx) && matchesCardCheckingTx(tx)).length;
        });
        return count;
    }

    Object.values(state.cardCalendars || {}).forEach(cal => {
        Object.values(cal || {}).forEach(list => {
            count += (list || []).filter(tx => isFuture(tx) && matchesId(tx)).length;
        });
    });
    count += (state.jointRegister || []).filter(tx => isFuture(tx) && matchesId(tx)).length;
    Object.values(state.personalCalendar || {}).forEach(list => {
        count += (list || []).filter(tx => isFuture(tx) && matchesId(tx)).length;
    });

    return count;
}

function deleteAllFutureTransactionsForSetting(targetId, type = 'billTracker') {
    const todayStr = formatLocalDate(new Date());
    const isFuture = tx => tx.date && tx.date >= todayStr;
    const matchesId = tx => {
        if (type === 'billTracker') return tx.linkedBillId === targetId || tx.linkedBillSeriesId === targetId;
        if (type === 'splitterTemplate') return tx.linkedBillSeriesId === targetId || tx.linkedBillId === targetId || String(tx.linkedBillId || '').startsWith(`${targetId}-`);
        return false;
    };

    if (type === 'card') {
        const cal = state.cardCalendars?.[targetId];
        if (cal) {
            Object.keys(cal).forEach(monthKey => {
                cal[monthKey] = (cal[monthKey] || []).filter(tx => !isFuture(tx));
            });
        }
        // Bug fix, 2026-08-10 — see the matching comment in countFutureTransactionsTiedToSetting():
        // destinationAccount/transferTargetId are never actually set on any transaction; automatic-
        // payment/payoff-payment checking-side legs are tagged payoffTargetId, which this filter never
        // checked, so deleting a loan/card account left its future automatic/payoff payments stranded
        // in the checking ledger forever. Confirmed live via a real Asia-owned loan. Added
        // payoffTargetId (kept the original conditions too) and asiaCalendar (missing entirely).
        const matchesCardCheckingTx = tx => tx.paymentSource === targetId || tx.destinationAccount === targetId || tx.transferTargetId === targetId || tx.payoffTargetId === targetId;
        state.jointRegister = (state.jointRegister || []).filter(tx => !(isFuture(tx) && matchesCardCheckingTx(tx)));
        Object.keys(state.personalCalendar || {}).forEach(monthKey => {
            state.personalCalendar[monthKey] = (state.personalCalendar[monthKey] || []).filter(tx => !(isFuture(tx) && matchesCardCheckingTx(tx)));
        });
        Object.keys(state.asiaCalendar || {}).forEach(monthKey => {
            state.asiaCalendar[monthKey] = (state.asiaCalendar[monthKey] || []).filter(tx => !(isFuture(tx) && matchesCardCheckingTx(tx)));
        });
        return;
    }

    Object.keys(state.cardCalendars || {}).forEach(cardId => {
        const cal = state.cardCalendars[cardId];
        if (cal) {
            Object.keys(cal).forEach(monthKey => {
                cal[monthKey] = (cal[monthKey] || []).filter(tx => !(isFuture(tx) && matchesId(tx)));
            });
        }
    });
    state.jointRegister = (state.jointRegister || []).filter(tx => !(isFuture(tx) && matchesId(tx)));
    Object.keys(state.personalCalendar || {}).forEach(monthKey => {
        state.personalCalendar[monthKey] = (state.personalCalendar[monthKey] || []).filter(tx => !(isFuture(tx) && matchesId(tx)));
    });
    Object.keys(state.asiaCalendar || {}).forEach(monthKey => {
        state.asiaCalendar[monthKey] = (state.asiaCalendar[monthKey] || []).filter(tx => !(isFuture(tx) && matchesId(tx)));
    });
}

function syncMortgageLoansToAllMonths() {
    const mortgageLoans = state.loans.filter(l => l.type === 'loan' && l.isMortgage);

    Object.keys(state.monthlyBills || {}).forEach(key => {
        const mBills = state.monthlyBills[key];
        if (!mBills) return;
        const [keyYear, keyMonth] = key.split('-');
        const periodIndex = Number(keyYear) * 12 + MONTH_ORDER.indexOf(keyMonth);

        ['cycle1st', 'cycle15th'].forEach(cycleKey => {
            mBills[cycleKey].bills = (mBills[cycleKey].bills || []).filter(b => {
                if (b.isMortgage) {
                    return mortgageLoans.some(l => `mortgage-bill-${l.id}` === b.id);
                }
                // Filter out legacy duplicate template bills matching the loan name or containing "mortgage"
                const isLegacyMortgage = !b.isMortgage && mortgageLoans.some(l =>
                    `mortgage-bill-${l.id}` !== b.id && (
                        b.account === `Mortgage: ${l.name}` ||
                        b.account === l.name ||
                        (l.name.toLowerCase().includes('mortgage') && b.account.toLowerCase().includes('mortgage'))
                    )
                );
                if (isLegacyMortgage) {
                    const [y, m] = key.split('-');
                    removeBillLedgerEntries(b.id, Number(y), m, b, true);
                    return false;
                }
                return true;
            });
        });

        mortgageLoans.forEach(loan => {
            const billId = `mortgage-bill-${loan.id}`;
            // Transfer cycle: respect an explicit user override (splitterCycleOverride, shared with
            // the card/loan payment sync) instead of always deriving it from the due day, so mortgage
            // payments can be split/reassigned like any other dynamic Bill Splitter entry. Note
            // cycleAllocation must be '1st'/'15th'/'both' (the convention every other bill type uses),
            // not the storage-array key 'cycle1st'/'cycle15th' this used to be set to by mistake.
            const dayCycle = loan.dueDay <= 14 ? '1st' : '15th';
            const resolvedCycle = loan.splitterCycleOverride || dayCycle;
            const cycleKey = resolvedCycle === '15th' ? 'cycle15th' : 'cycle1st';

            // First Payment Date gate (mirrors the equivalent gate in syncBillTrackerBillsToAllMonths):
            // don't materialize a mortgage-bill row for any month before the loan's first payment
            // month, or for the anchor month itself if the due day falls before the first payment's
            // day-of-month. Without this, syncMortgageLoansToAllMonths() unconditionally regenerated
            // the row for every month in state.monthlyBills regardless of when the mortgage actually
            // starts, so every month prior to the first payment kept showing a real transfer amount.
            if (loan.paymentStrategyStartDate) {
                const fp = new Date(loan.paymentStrategyStartDate + 'T00:00:00');
                if (!Number.isNaN(fp.getTime())) {
                    const fpIndex = fp.getFullYear() * 12 + fp.getMonth();
                    const beforeFirstPayment = periodIndex < fpIndex
                        || (periodIndex === fpIndex && (Number(loan.dueDay) || 1) < fp.getDate());
                    if (beforeFirstPayment) {
                        ['cycle1st', 'cycle15th'].forEach(ck => {
                            mBills[ck].bills = mBills[ck].bills.filter(b => {
                                if (b.id !== billId) return true;
                                removeBillLedgerEntries(b.id, Number(keyYear), keyMonth, b, true);
                                return false;
                            });
                        });
                        return;
                    }
                }
            }

            let bill = mBills.cycle1st.bills.find(b => b.id === billId) || mBills.cycle15th.bills.find(b => b.id === billId);
            const actualPayment = getMortgageFullPaymentAmount(loan);
            const minPayment = actualPayment;
            const budgetAmount = Number(loan.monthlyMin) || actualPayment;

            if (bill) {
                bill.account = `Mortgage: ${loan.name}`;
                bill.dueDay = Number(loan.dueDay) || 15;
                bill.cycleAllocation = resolvedCycle;

                // Initialize manual properties if not set
                if (bill.manualTransferAmount === undefined || bill.manualTransferAmount === null) {
                    bill.manualTransferAmount = bill.budgetAmount !== undefined ? bill.budgetAmount : budgetAmount;
                }
                if (bill.manualSamePaymentAmount === undefined || bill.manualSamePaymentAmount === null) {
                    bill.manualSamePaymentAmount = bill.samePaymentAmount !== undefined ? bill.samePaymentAmount : true;
                }
                if (bill.manualOccurrencePaymentAmount === undefined || bill.manualOccurrencePaymentAmount === null) {
                    bill.manualOccurrencePaymentAmount = bill.occurrencePaymentAmount !== undefined ? bill.occurrencePaymentAmount : actualPayment;
                }

                const wasOverridden = !!bill.isMortgageOverrideActive;

                if (minPayment > bill.manualTransferAmount) {
                    bill.budgetAmount = minPayment;
                    bill.amount = -Math.abs(minPayment);
                    bill.frequencyAmount = minPayment;
                    bill.samePaymentAmount = true;
                    bill.paymentAmount = minPayment;
                    bill.occurrencePaymentAmount = minPayment;
                    bill.isMortgageOverrideActive = true;
                } else {
                    bill.budgetAmount = bill.manualTransferAmount;
                    bill.amount = -Math.abs(bill.manualTransferAmount);
                    bill.frequencyAmount = bill.manualTransferAmount;
                    if (wasOverridden) {
                        bill.samePaymentAmount = false;
                        bill.manualSamePaymentAmount = false;
                    } else {
                        bill.samePaymentAmount = bill.manualSamePaymentAmount ?? false;
                    }
                    bill.occurrencePaymentAmount = actualPayment;
                    bill.paymentAmount = bill.samePaymentAmount ? bill.budgetAmount : actualPayment;
                    bill.isMortgageOverrideActive = false;
                }

                const currentCycle = mBills.cycle1st.bills.includes(bill) ? 'cycle1st' : 'cycle15th';
                if (currentCycle !== cycleKey) {
                    mBills[currentCycle].bills = mBills[currentCycle].bills.filter(b => b.id !== billId);
                    mBills[cycleKey].bills.push(bill);
                }
            } else {
                bill = {
                    id: billId,
                    account: `Mortgage: ${loan.name}`,
                    category: 'bill',
                    amount: -Math.abs(budgetAmount),
                    budgetAmount: budgetAmount,
                    frequencyAmount: budgetAmount,
                    paymentAmount: actualPayment,
                    occurrencePaymentAmount: actualPayment,
                    dueDay: Number(loan.dueDay) || 15,
                    paymentSource: 'jointChecking',
                    ownership: 'joint',
                    cycleAllocation: resolvedCycle,
                    isRecurring: true,
                    isMortgage: true,
                    mortgageLoanId: loan.id,
                    manualTransferAmount: budgetAmount,
                    manualSamePaymentAmount: true,
                    manualOccurrencePaymentAmount: actualPayment
                };
                mBills[cycleKey].bills.push(bill);
            }
        });

        recalculateBillCycleTotals(mBills);
    });
}

// Returns the purchase APR that applies at a given point in the future, accounting for an active
// promo rate (card.promoActive/promoRate/promoExpDate) that expires partway through a payoff plan.
// monthsFromNow=0 is the current month.
function getEffectiveCardRateForMonth(card, monthsFromNow) {
    if (card.promoActive && card.promoExpDate) {
        const target = new Date();
        target.setDate(1);
        target.setMonth(target.getMonth() + monthsFromNow);
        if (target.getTime() <= new Date(card.promoExpDate + 'T00:00:00').getTime()) {
            return Number(card.promoRate) || 0;
        }
    }
    return Number(card.interestRate) || 0;
}

// Simulates a fixed monthly payment against a balance, applying each month's effective APR
// (which may change when a promo rate expires), and returns the number of months to reach $0.
// Returns Infinity if the payment never overtakes accruing interest within the cap.
function simulatePayoffMonthsWithPayment(balance, card, payment, capMonths = 600) {
    if (balance <= 0) return 0;
    if (payment <= 0) return Infinity;
    let remaining = balance;
    // Active payment plans (BNPL-style installment plans on this card, e.g. "Existing Card Payment
    // Plans" in settings) each carry their own real monthly fee on top of interest — a fixed,
    // recurring cost this simulation used to be completely blind to. On a card with several active
    // plans that's easily $50-100+/month of real charges the payoff calculation silently ignored,
    // so the "amount needed to reach zero by this date" it suggested was too low to ever actually
    // reach zero — confirmed as a real bug: interest (and these fees) just kept compounding forever
    // once the scheduled payments ran out, instead of the balance reaching $0 as intended.
    // deriveCardPaymentPlanBalances() needs real ledger transactions to project a plan's declining
    // balance, which don't exist yet for a future hypothetical month — so this only reproduces the
    // one piece that's independent of that (the fee itself, for each plan's remaining duration),
    // not a full plan-by-plan balance simulation. Good enough to close the dominant gap without the
    // complexity of simulating hypothetical future plan payments.
    const activePlanFees = (card.paymentPlans || [])
        .map(p => ({
            monthlyFee: Math.max(0, Number(p.monthlyFee) || 0),
            remainingMonths: Math.max(0, Number(p.remainingPayments) || 0)
        }))
        .filter(p => p.monthlyFee > 0 && p.remainingMonths > 0);
    for (let m = 0; m < capMonths; m++) {
        const monthlyRate = Math.max(0, getEffectiveCardRateForMonth(card, m)) / 1200;
        let planFeesThisMonth = 0;
        activePlanFees.forEach(p => {
            if (p.remainingMonths > 0) {
                planFeesThisMonth += p.monthlyFee;
                p.remainingMonths -= 1;
            }
        });
        remaining += planFeesThisMonth;
        remaining += remaining * monthlyRate;
        remaining -= payment;
        if (remaining <= 0) return m + 1;
    }
    return Infinity;
}

// Suggests the monthly payment needed to pay off `balance` in exactly `months`, accounting for
// a promo rate that may expire partway through the plan. Binary-searches on payment amount since
// a closed-form formula only exists for a constant rate across the whole period.
function calculateMonthlyPayoff(balance, card, months) {
    if (balance <= 0 || months <= 0) return 0;
    let lo = balance / months;
    let hi = balance / months + balance; // guaranteed to clear even a very high APR within `months`
    for (let i = 0; i < 60; i++) {
        const mid = (lo + hi) / 2;
        const monthsNeeded = simulatePayoffMonthsWithPayment(balance, card, mid, months + 1);
        if (monthsNeeded <= months) hi = mid; else lo = mid;
    }
    return hi;
}

function monthsUntilDate(targetDate) {
    const today = new Date();
    const target = new Date(targetDate + 'T00:00:00');
    return Math.max(0, (target.getFullYear() - today.getFullYear()) * 12 + target.getMonth() - today.getMonth());
}

function estimatePayoffMonths(balance, card, payment) {
    return simulatePayoffMonthsWithPayment(balance, card, payment);
}

function reconcileCardCurrentBalances() {
    let changed = false;

    state.loans.forEach(card => {
        if (card.type !== 'credit') return;
        const ledgerBalance = calculateCardLedgerBalance(card.id);
        if (Math.abs((Number(card.currentBal) || 0) - ledgerBalance) > 0.001) {
            card.currentBal = ledgerBalance;
            changed = true;
        }
    });

    // skipAutoSync — this is a derived correction (recomputing currentBal from the ledger), not a
    // user edit in its own right, and runs unconditionally on every page load (init() calls this
    // directly). The actual user edit that caused the ledger to change already triggers its own
    // normal (non-skipped) saveDatabase() call at the point it was made, which schedules the real
    // auto-push — this call only needs to persist the corrected number locally, not queue a
    // duplicate/redundant push on top of that.
    if (changed) saveDatabase(true);
}

function getCardRunningBalanceAtDate(cardId, targetDateStr) {
    const card = state.loans.find(c => c.id === cardId);
    if (!card) return 0;

    let balance = card.startBal || 0;
    const targetTime = new Date(targetDateStr + 'T00:00:00').getTime();

    const cardCal = state.cardCalendars[cardId] || {};
    const sortedKeys = Object.keys(cardCal).sort((a, b) => {
        const [yA, mA] = a.split('-');
        const [yB, mB] = b.split('-');
        if (parseInt(yA) !== parseInt(yB)) return parseInt(yA) - parseInt(yB);
        return MONTH_ORDER.indexOf(mA) - MONTH_ORDER.indexOf(mB);
    });

    sortedKeys.forEach(key => {
        const txs = cardCal[key] || [];
        txs.forEach(tx => {
            if (new Date(tx.date + 'T00:00:00').getTime() < targetTime) {
                // Expenses (negative amount) increase balance owed.
                // Payments (positive amount) decrease balance owed.
                if (tx.amount < 0) {
                    balance += Math.abs(tx.amount);
                } else {
                    balance -= tx.amount;
                }
            }
        });
    });

    return balance;
}

// --- CREDIT CARD SUB-DASHBOARD & DETAILS EDITING ---
// Staged the same way tempEditingPromos etc. below are — the loan-dialog's icon upload only commits
// to the real loan.customIconDataUrl on Save, so Cancel leaves an untouched account alone.
